INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('6f0fd82e3fb7188882fa76a0e9184918fdbf0483c70ff8dc918b5aa5096d1301', E'import sys\n\n# Maximum Subarray - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('5294e26d76684006bd79f34a1e409aa9d96c298bc0c27e111ad2387f0eee6743', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Minimum in Rotated Sorted Array - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('bdcc2a95425ccc4f35f9d85cf676170b2ba37becc68976bc1b38332e40e71114', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Subarray - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('6441cd0fd8f75ff5e6621298983638dccb0ea0c5fd9fc96e93a2423dc827d352', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Array - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('82cb033a4abcb3e21d96ce5098a0bd368897554dbbfdca879ea099b68d9fafb9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Spiral Matrix - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('e2f66b183b989e1e4aaf0e7ddf458b2fc1d867d8b50ada1e2ea81fd1f9f2c5e8', E'import java.util.*;\n\n// Best Time to Buy and Sell Stock - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('144397542305dec595fb3ac5a671088c39a9c7cdf5fc9e3114287f3ec85558ce', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('1c7845e7dd90ad88cbff90c3ab01c95470f01e8e18b9387befe970c0f7841933', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('c4f8fdad499b02a601ad34bc1804827cd9e3a8fa3b5732fd9c0e4ad5ef0a5c6c', E'import sys\n\n# Valid Parentheses - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('5afb07b67ecb5bbf7efe26c3283e5ff12af48cf3b01968c8250379338e084f10', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Array - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('88ecb7cd734eef5e611262c16b5cde9b5c37e66cfa924977856fecf5c4f336f6', E'import java.util.*;\n\n// Rotate Array - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('f6db71915ee520b2128ff4d813c0a8f87ccb71f288d118c46e7680bd8f5cfb3a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Product Subarray - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('330dd8476349e40527bcf7268c46e38146c670d20887bc21f39775c6e2469178', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Parentheses - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('44be16e1dade39aa74bb44b021c5a1fbbd1bcbc324ca4267b1f498f1e664c7f7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5d581584ad417905fb84156a6d955d64093744ccb29b25c87d768e14d222543a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b2473a5d82ac4694004d57bcd236bb717737cbe91c581884b182cbcf48939a81', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// First Missing Positive - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d8018618302d70baef1c9c596168d2ec9afb4c4771d7501a96d9eccda50fdc2e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Window Substring - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b54cfa107be67b6a9646b49eeee01b0b0c54abc2d3b57fed7d4c157a505564ca', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Repeating Character Replacement - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('35b3d718ce14c1241639e22f31cdbd3fd2f67d51be3f819e9f90301ab2ba3476', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('986762b8f47b9ed243fc8944ed12e79728278b4937b26a85e5e682ce4563689a', E'import java.util.*;\n\n// First Missing Positive - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('e5509aba09ef280c30a54aaf5e53a1becf996c138768f6bf744c8135121aca70', E'import java.util.*;\n\n// Longest Substring Without Repeating Characters - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('9593e80d371b1751f0b4b897a93c236780aaf3f6dd53c0c298d84907bbcb5864', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Trapping Rain Water - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('16d66565a6aabc6c2e3003d4e82a8e7ea3d80b84fd2cb28155a999a2581f82a1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('3d28ac7809a7fcabd18009723651d3026319e79294d8e7ddeaa5bfdde1048c23', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('4f9c201168f37abf75af87f8c287f100425847f1ddfaf16ef16c81a92273da46', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search in Rotated Sorted Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('156b790a1d3da7e5cd47c2404afeeb8b61833bda29b613a06c8ff45733dad501', E'import java.util.*;\n\n// Longest Consecutive Sequence - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('013b91667974a1689fecfefe7af23c0d2e7cc4be62488f08fff2d614e2575c0b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('8c7e7ac4d6bb5b1f68edfb5ce9be2aa29ac7588599c84ec7676ae338733e8e31', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('4d48fa55a0bd28db86838013db003ced41015611586646d263bde1efa3034a6e', E'import java.util.*;\n\n// Two Sum - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('bd6945341ecc61031b89b722c0e54cdb1477da0227d2b1b6cfd25a2c7289d1ce', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// String to Integer (atoi) - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('4d636fe33daa087bc6498365a2c203b3ba39248175dbadbc4feb92910fdd72ee', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Image - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d84ac124b1444156eeb249a40c230de06e2b6b0f42ca484e520263a512fcd674', E'import sys\n\n# String to Integer (atoi) - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f3b51f9607ec0297b346374ed3ff36e24039cea4438046b8763eeb8df482795c', E'import sys\n\n# Spiral Matrix - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('4cb3bbe9a4ab178534862bd9294bea2a6c43e261499323794287f378acd2b318', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// String to Integer (atoi) - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('41a3cf3877eefc13e21de9ef124440e1902037952383b01483ec2a91bdde2b81', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Substring - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('3340a2b61b7e76ed5ec04e16aa49b704daa882cef9f031cecc9872d1f4219a21', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Image - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('2b428694972fdd55e8ee73d21ec9d3d5b3a8ef7619431c4cd2f94a4ba42c5cac', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('aa993baa3664f8b3ef7e099fc2618c75e4113b868a8abffb84a58b9824b27dbe', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Contains Duplicate - attempt 3 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *nums = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('5dda59fdcd0df2d76d30c65471a7d35d94742a359b94ae7c9a09aee36d7b0077', E'import sys\n\n# Valid Anagram - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1\n\nsolve()\n'),
    ('1bed723408a21825cd4f7dd1b3b8e1f86d9c278478f99bdbbf203a7559c565f7', E'import sys\n\n# Contains Duplicate - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('2389330ff47a43bbdd1742463708ef400635a7ebb8c4676f8d751df33408a46e', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Sliding Window Maximum - attempt 3 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *a = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans);\n    free(a);\n    return 0;\n}\n'),
    ('240ea0d6a075e5247138d8ee7fd5e900c938354acc174a7f37d18548a819d726', E'import sys\n\n# Valid Anagram - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('f44416465c46b399410055166b3595b198de7ceff1c6a9489aad84c567286cfb', E'import sys\n\n# Find Minimum in Rotated Sorted Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('11202703321dad818d4f3a7d59e3f530de278a81a685b3cac2c72ab76e5d509f', E'import sys\n\n# Contains Duplicate - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('490d509cdd865565473b37e5f3e6678ead4de675ded6344dc54bac4e191a570c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// String to Integer (atoi) - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('1bc9a9004e12dc2b6b82b7abb3f06218957acd7d5c63eb53f5bf1b6bea1cdd71', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('0cefbf1da718253ecfb485e4a8e24df2a85002f9121a97b9f641768634775f4b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('de2af9b40fbc21a278e157fca47580da1f70bc85bfb94302b052b1e0f469b7d3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d1b9973ae5b2335e729a19b19e2bf5dc7f9246dbbffa8d28b5c4aadb36898f4c', E'import sys\n\n# Valid Sudoku - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('379c372e9a524956f9fd6e48071ac1ab9eac1a642f42b465b644fb8f6a3a4231', E'import sys\n\n# Product of Array Except Self - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('d22c7025e032e16904a14f1304c30e799c98d7d2831bf55cfbcdf152ce0e98ad', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('12c4cb44f8908a750a97f1527ae5913ec3aa7110225b53eefb10473d11d79f46', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('93fe0e30b861487c1bf473cf89f796c92a47fe080ff91178f0568b12d99a7a8c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Words in a String - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n''\n    return 0;\n}\n'),
    ('dc9addf30a3096b92b778dab4b81e4c267b06765f68b065608cd07398e003db5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Missing Number - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('511e72deb1f253b36c4ea72cdf1b653e6ad2ca14c4de43cf9960566a630b92cb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Words in a String - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('04822600d907b646df08ea7fb79475862d735e7adffe936f8356180335272d48', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Palindromic Substrings - attempt 4 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *v = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('252495d412fa19decf9239df894885a9bc3306c090362756c4bdae9f92b89a07', E'import java.util.*;\n\n// Decode Ways - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('6a1a0f7b1d75ac44171f9a3503e22a3e0bb65bc199c7e60c74f4f95542a1cab1', E'import java.util.*;\n\n// Reverse Words in a String - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('995b4ec15f5cae33073a68737b2151440943257f3684175d033759a9c7eb117c', E'import sys\n\n# Reverse Words in a String - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('ed9a25c046de6d65db5a54f22010b1442f0a2ff793d61ac18b18b19e52d99b2f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Container With Most Water - attempt 4 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *nums = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans)\n    free(nums);\n    return 0;\n}\n'),
    ('2961585a8e41febb7010737152c726c380a0b3d9e46d40c49b340c31b10da1e4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('97588922a19a5bdae599815e432b616f2906ca1f62e6732e24a8ecee3fecd750', E'import java.util.*;\n\n// Letter Combinations of a Phone Number - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('405b504fd38e4eee32637f15a80982287327963b8581997f257477d9b3a09d9e', E'import sys\n\n# Container With Most Water - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('6e674e5224731d7bee4759f05c9f546d971ed5cc5e7d0191c8396ff1ddb12bb3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Set Matrix Zeroes - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('2727936f39767493d3508db50edc3b03cac1fed63c1af5254e7a08e6a62d0a5a', E'import java.util.*;\n\n// Container With Most Water - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a865d9106f9eab85317812db268311fe597fda1af43bdaebf663ea77b2e9625b', E'import sys\n\n# Set Matrix Zeroes - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e5eb863aa9609b908e7eaa2d6fcb8639b6557130ea59d6afbdf5bc1ca235ce37', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Search - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('4a956dc961f74ff1fa3e3de5470003d7c0c705996fa6ca22ec7afc7e4ca6df1b', E'import sys\n\n# Container With Most Water - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('b7409affdde80affd41185b2c93559b2c4daa00f6a3fade5fefea5751421b117', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('99a11456d88f274899b7a22d6cf15d0d9040d1dc0ddf74be50945f8e05ab5d01', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Implement Trie (Prefix Tree) - attempt 3 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *data = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('09af11b631f544dab8238c08bc6ce824cc640a8919222f5ee584764327af1539', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Intervals - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('bd44d50a0a50bda925f0bd239b1cbeacc52151e28136271b732e992064dbc4f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('7ff4e04825ce9a992350e13a14d80131af78e67cf8801dd40b89cd9bde70eece', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n''\n    return 0;\n}\n'),
    ('f8c559bb5a8d98c6b3362aa7cbcd5f9f5d808ad53a3096f93379f4c4d2c9e8c6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n''\n    return 0;\n}\n'),
    ('841be2be5861181d68ae1bfdfa0099401e6bd8c4d6d723f8775aad883dff9afa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
