    ('b079f5df42852600a8edad3f685d0b9ef2c02d3e1a59e66fcc3a9afca5ec1c76', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('eed549711c1526fe1862cf9aec15bfd60aeaf7f52fdc1d146c95bedf6f5ec376', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('11ae8a3a2d9344fa60a0bbcb277944985030204e1fb5ea093f6f01b9770e3b53', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f18ec0f30e69c42f82d1c3943be63a8bebd94c8c34ffa1d4376d276cdcdbcf0e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('4231c7815f052e6de594da71a4c5bb34f6b88a7e1c43122902dfcaf845d8829c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 8\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('147b1fd91c79b370072bcd0a681da27ad9b57b6b68e2ffa26c7111d13ae2d641', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('bacabe033d97e104d86c8932e1b27f4e430613e0c92fdcba548884a475559b30', E'import java.util.*;\n\n// First Missing Positive - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('1d52d72a8ee4a035d58ec4341a6842ac9ba690ce4a18b11da60c980a905dd41a', E'import java.util.*;\n\n// Wildcard Matching - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('d323fc0b4af02b7b00d991665e1ff5372627d1cf2a8c08c15f8b80394826a687', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('c2fd7a7dfb252e106cf83aa57e4fc5bfac313d4f5b18a880bde22d66c9d3e14b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Common Subsequence - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d6f2e58574ccadbd007c0e4730b0ff14b0b82620978155e904a8d8414c0ec498', E'import sys\n\n# Word Break - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('39bcdd1fb03bacb50f24d5e535cef3ce8f94dc73035af922361a7cbd40db502f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// First Missing Positive - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('59ff846258b3bc3ed0f63f611a6118d70fa4e4ca9e781ffb4b8f27b89bf9a5c5', E'import sys\n\n# Wildcard Matching - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('e691c459a3a9a50610ca58affdb28fa35b9c6e8da193c98bee77944dcdf9f189', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// First Missing Positive - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('3db918e24ccb76265f2999de6f3f7154ec3604e6462a18a294828eb5ee4f8ca6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Common Subsequence - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('07c487f4efabfc1a0a534b3309b0b3dbaab2beefb6ce8adde3445025458f44cf', E'import sys\n\n# First Missing Positive - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('6c84c25215b29f7b8fbde18b29102588e95470974dd839090ec6a4d7b60c7df5', E'import sys\n\n# Insert Interval - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('48a0cd086a35544181a6cc1f2da96f3c4e72e329f8b7dc234a4872f4ddf6c580', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Generate Parentheses - attempt 1 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *arr = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('61e4b42bb155ee67ad1d0901e5bd7be1ab7234ba8002ba85ce5c51d0854c842c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('8ee336f904b24afd3a7f552b9b41fac91bcb54960f1049fd59dc64f2c39d0ed8', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Two Sum - attempt 6 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *data = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('02985f46b8959e505da58be2972cf9af390d125fb6915df6ffde1caf266caf37', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Generate Parentheses - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('27ea73b32a7ba252cb0e16d43dc0b2d64355a2051b563daa8e3850108ae4983e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('2647383a809fb7f0e301a491c6770f6ac18026ab025bd00f0ba07c5e61f2f653', E'import sys\n\n# Insert Interval - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('fa54f3bb053bb00390acfae96a853747140a821a7e77d5537a9306bc27dc7c3a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Repeating Character Replacement - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('a4c0eeb589b76a433ce4da549413ca503fd51144a521275a3c983d530f5b51a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('b18e32580eaf6cb3f7a9d41f728da2f12c7cb9101643f4047f7b522179793b95', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('67cbc89ad102cbefae966db5bfa80ca4bdc71be77f1f63cc5bd0e760588f321d', E'import sys\n\n# Edit Distance - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('58846e715b12a5180b23358e5c628e760126421db92dc18a8e247fcd56d9664c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Non-overlapping Intervals - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3daed6c4a57f5957a0aff70ddd2cf821277ff66a3c9c1aabbb81970fa2188e4c', E'import sys\n\n# Count and Say - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('ff0cddf32a299f6e674af67c069957ebddd297cfac46d6c727fb9fe5e4d20daf', E'import java.util.*;\n\n// Implement Trie (Prefix Tree) - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('74228e1d3459774b2d6600abd4bfb85e30cd21ce96414a59647c7daff58aabb7', E'import sys\n\n# Reverse Linked List - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('58d14d276fb6aee18f6ff302a1b9cee87c6b38eb0871dffdb885eb0c4325c65b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d6b20434fee95c1a8379d7a1254d35341754bfcc95c72bb75a825ed3524cb8cc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Linked List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('16dbd5f435f5f22ee142e55e2c315118892813069a8c573ea4a6ed14eb81c619', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b18728116f5a9e5990c12901b499feadf4168397bc74f743b9535e65a4a12466', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('9b705ae8f70a56810cf5d4e4ade5be6e0bba6e5d7e25ef900b6955d4ae697ab2', E'import java.util.*;\n\n// Count and Say - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('37f00a294365345a89ff7adae754e49a0faf413fc38cf4cef299128d0a1175ce', E'import sys\n\n# Two Sum - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('ec52844f54857f725a0182cb8b23f37dbff471c03006813e9564e6b3ae46b0a8', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Set Matrix Zeroes - attempt 5 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *nums = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('43c6e8ca07b1b129974f4cb41788136d65961f2d0d10d4873f774e6f934bffea', E'import sys\n\n# Generate Parentheses - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('386517a1c72b65d495b34b470aa333b2d8852c04865c20b43fddf58c826969e4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('642cd191b05a2e5e4d8ab09bd1870ae63d1e8ad8b38e67077d6bfa08cecfda9f', E'import java.util.*;\n\n// Linked List Cycle - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('f4bea7103ba32e9863f3e113ae371d64fc624165210088afdcf882123b032b55', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('1241e27b1258ff213208c2dd517fe5bf2a781a294c7ad24343f542968040e80d', E'import sys\n\n# Top K Frequent Elements - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('720d30cadcd72253407af20e2dd09e18e2176feb9389769f41a9bbaedbfdd394', E'import java.util.*;\n\n// Sliding Window Maximum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('081f3174262ca4f54b4bf4aa67c0f665f74b6781de18fdb0c8fac1846598effa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('cb754e45e8f6666513a1fd87ab915b41b934eec385943fd9e7330a87cf8c8c31', E'import java.util.*;\n\n// Move Zeroes - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('6c83fd208a15da2dad48db2da7ca6e94ffc1d1069ceaa47a0d73cebaf629064f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('6af79be5467f3f55349b9f8662a9ab756560860964a2ea56d3dff42146196b7b', E'import sys\n\n# Move Zeroes - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('e2b163bb3052ab9c6ed8a18f16d050c2016653662f2b5fa003744c51bdcbf41c', E'import sys\n\n# Merge Two Sorted Lists - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('91ecf436909128ebbb815910ced9d2e0e7e071790de673280860f9926b13b81a', E'import sys\n\n# Add Two Numbers - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('07f662fa508971c4e1088a8b16c8a61c69d65492a768a85cbdfb8d36721c0b49', E'import sys\n\n# Majority Element - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('488240559db3ef4c72937b6270ce61d54fa7f2d87025e92371cbdcd8ecd117b5', E'import java.util.*;\n\n// Merge Two Sorted Lists - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('033023542073dd160720245d13be200e62f4bb8b2a927eb65b154cf28b526877', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('5c1182527de914b08f8188d59985294ade472784c7d1e05ffe9255e52c6a6780', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge k Sorted Lists - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('ee1c3f35e53064d572646fc8ab07d23dfd8f8c8992c92c9b98fb6b8c4536ab52', E'import sys\n\n# Reverse Words in a String - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('1790ccb643244766c17da25dbf91927c4d601dfb4a58e7fe7c7f3006ca351ac0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search in Rotated Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('b660925227bd2896fb994a19fdb559a95c3f1477885a12b4981b8832d8b17afa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge k Sorted Lists - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8726686fd4ba9decda0e03fbfe310286292aee8ef1755b089fc45ebb285a8431', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search in Rotated Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('2e729f6d44496b1586dda487c4ebefaa47e796234404800bc22f84e1781f1391', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindromic Substrings - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('943875b9711a07235471071e488a3fcde7faefe0f57fb659166566636b6a99c9', E'import java.util.*;\n\n// Insert Interval - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[N]);\n    }\n}\n'),
    ('744c04d79f289e132db606872c203b5b0e31790613468fe9191610b4dd3655e3', E'import sys\n\n# Implement Trie (Prefix Tree) - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('50607cc67cefb7cbbadd0b8c4b5344e32bb0058a4d3dd4965a9f126551896686', E'import java.util.*;\n\n// String to Integer (atoi) - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('253f369b9cf384b28745443e782eb81b8ff425fcf063c4b5df04a0186af2ed2f', E'import sys\n\n# Implement Trie (Prefix Tree) - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('fcee5049f261fb36fdd2303c855a33d34b7e354663b982ac0db608d06e3694da', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// String to Integer (atoi) - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('35b55d86e0cebdff7b1d2fc67db9acf7edc800e3bde8f2cd7c8af9a0840bcd50', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('6f97327a02ba287323dfa88297b793bad6db6fa98d4b39d41cd83bfcb9ec9ced', E'import sys\n\n# Rotate Array - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('3dc82dc97050de964b648e30c4a07419f06c5f54f4e5abb35e1b0a8c079d508c', E'import java.util.*;\n\n// Subarray Sum Equals K - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('226d898465e5470370c4c648f550cfa03f7ead375901caf379c7c03e3ebeae36', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindromic Substrings - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('1d814fa9cdce97d8a1c7d60d35e3336853ba5d7fe85fd1cbb4a33ec6030a56e5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Subarray - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ac59826cd32a2441f14d651fe64b7c16e03da0802c420422a12bb35063ec0ece', E'import java.util.*;\n\n// Two Sum - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('e8a88ce432953832b76e2eda4a1fb384e1b869821cba78cb5625cd225e3c0c88', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Nth Node From End of List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('453dd36ba58df19d55600454bdffea53c0acef483b2fbf4e2b40b3a633619e40', E'import sys\n\n# Palindrome Linked List - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N]\n\nsolve()\n'),
    ('c5c34b24c8a46843d408b1e6b416404506d86e2aafd64ad87629546f982a7518', E'import java.util.*;\n\n// Palindrome Linked List - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('3884eb869963b468387ac45c93401511d4005fc23b6027395a130d563b4a21c9', E'import sys\n\n# Palindrome Linked List - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('058fada8858c91db183a36f5d12185b73cbbc6299835b842281394157eff5f9c', E'import sys\n\n# Remove Nth Node From End of List - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('5b853895e80d60705448d1fdb91b2966e06384745ed2e75dc2e6026f5ed8ecac', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('7aa93d33cfbe5901ef8b0eeda807ef863d3fa337d76026ded6e94490a50a7ae2', E'import sys\n\n# LRU Cache - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('26c38cd64a8f5f08f086b5e5c4f28d680e2bd989210cf92d1c088ec432c1d2a4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Minimum in Rotated Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('f84d77dc3809f4742b5df95766fbeed4ea24065db543a03c9be7f73a2fbae021', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Subarray Sum Equals K - attempt 7 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *a = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans);\n    free(a);\n    return 0;\n}\n'),
    ('fad8c1906acf911dfc3051a8bbcbb8a8b00072becd6ecf92e01cc80c1cd0be13', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('538542000165b60a5350dc38e968f2a3ca2df34836db461fce052e07b249e4b0', E'import java.util.*;\n\n// Three Sum - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('52a062c63d651da50bcaaf7969ceac085ea053c6d047f0fe561585ac65deaaea', E'import java.util.*;\n\n// Maximum Product Subarray - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('523317c379e5e158fc4324e57fc8f5e1333b5c89145dda3465023e18850ff33a', E'import sys\n\n# Three Sum - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('b8b3bf7616d48adfb637ffe1ae63b247a87979194eb53964a9a7ec6a67d67fab', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('ea884d3e72b6cfadccc093739c90be7360dbe6ee37f642e30ce61c38dc2220d0', E'import java.util.*;\n\n// Maximum Product Subarray - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('7ca8225d01a669d23d1ecc8a4d929cd4662a1fc67a39b9c83896f42ce0d08928', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
