    ('42463d2fbc6db44b1804a99c83a7231e285670a7b8d687c457e0f3727653c6f9', E'import java.util.*;\n\n// Add Binary - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('0c091ed5b36cae22086e11c54cc658d780d0ae50af213aa020c2d8292c95b29f', E'import java.util.*;\n\n// Add Binary - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('aa6f952d1cacfc254731f20f6172c08a87950b5b0de4091136d79666b6c56b8f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('88ba0c8933edf4705101c5d93a97f4575835e85919434cf67cceb01a7e1cd14c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('be8e1eb93513c0a20618aa6787f5edff8048054219c80ff3ec3235bed37aecc8', E'import sys\n\n# Min Stack - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('d3b96e7ef598a942df5c9079cb82bfc396389a8501b884e7531f37768427ea38', E'import sys\n\n# Word Search - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('2f3999fc77c1dac7752204a6f861fbefd6bfb01c2e9323a60408d821dc97fb6c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('7e6aa687e7f7af06495a067c592ba8df122d10254c1e745870cddd35b0ab5c4c', E'import java.util.*;\n\n// Word Search - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('4885380ae65fff63ca35765c802c606fb89155720d70b2e2d3a4fc2361b653ad', E'import sys\n\n# Next Greater Element - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('dfe409f6e61493b33cd40743b2573d335e3bc904c24fbcc210a90bfba45d09d3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('20550726094183d6cfdda4f96d63a8a3dda529e299b5f275d6f66e00d823ecae', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Search - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('1d0ed82cde76884d1f61ce4a869a157b9c667023ef5e8b7a324818f84b69a839', E'import java.util.*;\n\n// Next Greater Element - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('a9e3ba1c2a3a511b01f1b8a1cbb642435bbe396232caa21ca6aac8482f99dc56', E'import sys\n\n# Rotate Array - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('ea90f1e64c07a60acb9a6078766ac4fa6cfe5fe02dc043689a1d43cf91f6cd80', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge k Sorted Lists - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('4de0c2e391082da9b899f9f23e4ab473a0bce99dbce7635c6c9e4fdb08aaed65', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Array - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('c831ad84a083cd179921035807fa80ffedcae3ec78f73209aa67a3ebcdb9f411', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Window Substring - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('733cb0d92aa70f22dfc24c85d8e67dff7ddb66b06cf17438756fb83b0f3714e0', E'import sys\n\n# Best Time to Buy and Sell Stock - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('b9f3be8a374919fc403471c480c41bdd2f6f962b906772b6479e76e7ffd2ec8c', E'import sys\n\n# Evaluate Reverse Polish Notation - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('90bfa7c4ad3d7eed79982ae6634a5fc348a8457976c0855abb5adf8d54da5171', E'import sys\n\n# Spiral Matrix - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('4c60d467d71433756a71b475cfb649339909e8e889f288b1640a2ab37a0f2173', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Spiral Matrix - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('63f5699a86c4d96502e14861999a246051b2a5b86d649405e0ce119d79dd2290', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Substring - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d9cd717eb6d22617853cf097619081f983d2d00e1e10bcc5f8c818bc4a6aacdb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Spiral Matrix - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('131ffe85a14e95a27fe806dd1b08779761bb58034112ac7e382f647686764dae', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('5ddfbc7990610fa88e3f5065b118b21ea1e3facf9796a2ac8052e119608c2669', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Common Subsequence - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('9a5b6365666e22092f0a4b5f8464c38715cda761b18db7b8e33988308916dbda', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('75573c6216ed429a6e2af35d2ec331d705041ed4f08ae7897a79ba8270b62ee9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('5525e6f1c1d5f1d2205cad6c21d9835d1065a407aeb3d2d5e89bcc2956864f3c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// LRU Cache - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
