    ('eb0c62dd314470e4a1b3a3e2d82bb02960d553b231807173389f0d1a7da58c87', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('19dec17402b84087aae3dae963cb5bba37918d60c6ef02b4de131d48e4580cae', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
