    ('d85be6067c5604e134a8ffde04fe4de07850ab64eb55b5ab974bb4596f13e378', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Generate Parentheses - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('383aa805111dad662c14d74447bf465cf82830b0a0788e46d20e68bfe2393a0e', E'import java.util.*;\n\n// Valid Parentheses - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('d3da7fca003847643151f7c6531386ce99965baf30185d8cecb243061251d8e4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('778bc1cce332183be86d87561ae9c3ccf4bb073dc139590900bb90e56e0743df', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('51e6351b27c3e46bc99def367dffa7a7cb3103eedd5a02806d98e4cfb6279395', E'import sys\n\n# Task Scheduler - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('06348e14f32954cc1add555c42a957bbf00b4fac6642c0fa9c78948e0673da1f', E'import java.util.*;\n\n// Valid Anagram - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best)\n    }\n}\n'),
    ('7a69b8d6f7c06d53a613df3c52a231677232ddb9fbcb88efee2ba8acdba1a08d', E'import sys\n\n# Reverse Words in a String - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d7d0d2db4cafdf4becfc1f040bd08e530f6c112585a5258cf7d425f08b42d1bb', E'import java.util.*;\n\n// Meeting Rooms II - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('d5ebc0645a3dbc0237eaf9f72bf1a8ebf330d97d35d7b69ebf5cf1c5699cba6e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Edit Distance - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('cbc3c0049f65f6af77efb441603836007f1c306304aa70853b200c77dc0815bd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Image - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('44a27e3c512c272f42628cdeb3c652cc02b3b934264200c35b651cf85c7e0619', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Rotate Image - attempt 4 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *a = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans)\n    free(a);\n    return 0;\n}\n'),
    ('6e86760c321a1b735763893f2db872db74254e82fb7c08ceee61a3702ca03cc3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Edit Distance - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('139623c09c376916304b38175b5fc12169222b03cd56b15e6a63453941ff19b0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2ddee9269a20f27b6e0d53693e85f83885bf753ff57aebc3898a0a85a7e931ee', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Design Hit Counter - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('767cf477ccab01e17be24a03b38f419934905603fed1079f6b44ab3797458fa5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Largest Element in an Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('0af8943e998e24f45eca68fd98386206f7f5b05ce2250ff34259324f914dd8b7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('8b945a8d1298f911bae6127fe2d288dff369e71169966bb1e59579d1a1b670e1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4a4a35985e288487f9517e680739b22da8402c31678e71e95451e4b4fff5e206', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b72f8107005a074d6c066e17064d5dbcdd374e13ed7efa2ebca3e9daac85f614', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f94068936f45e0f1f4f63ed14c59a22c038a4bd1d7ac27a48a7200acf15d9791', E'import java.util.*;\n\n// Invert Binary Tree - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('05037e62aadabc7f3d899dd512d59ca5c2a9dde5dfeddd5c9127f58ce630c914', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Regular Expression Matching - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('aae1c07ee13bd20933780893e07ac47283fc71877054f595775b74f0b4628c0d', E'import sys\n\n# Regular Expression Matching - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('018b7f51c2100aa85f0e27085bb15b5c64f6ff26bc532fae822ae28a76fcfcfa', E'import java.util.*;\n\n// Maximum Depth of Binary Tree - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('c50fee1d5cb7e23f6094ea04e467b7b4791911bb50e8afa7c1f54c0f3beba58e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Intervals - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('97f07dcc5502ae151913747e3dd1b33d8b17893676ffc52fb64645bbd6f2b43b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Invert Binary Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('92cc8fae5ba5ee422d3886d2b4ab85e92e6b915147d5aceb4db56b701cd7bafc', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Invert Binary Tree - attempt 4 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *a = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('e372943e596043bb486585640df9ae4bae74dbb29c27b72cdbb53dd448027818', E'import sys\n\n# Merge k Sorted Lists - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('14e9e6467aec73ef9deb02211eb54709e6ac128afc16b09966b55c26b353761d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('c6b6db38f827fc5e78de8b5284e16a41a06d9d7c4e4d1ed56661c706297aa667', E'import java.util.*;\n\n// Invert Binary Tree - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('2ecf26248fa835ec28d5fc7dd4dab8ba1a8a0ae02acc9162f8c3d189eebbb6b2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('0fe0a3ccc3db3edc3270643fff0c40cd1cede2b77cf329c4aa498e2fb50eb64c', E'import java.util.*;\n\n// Maximum Depth of Binary Tree - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('62ab3c04fcda3eaa53f085e0d1fb3d5ccf3b10d1ce2f8ee488034bcafcb8c7f4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Daily Temperatures - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('04d3ab0c8c53cd36487d9ce1742c93882a7ce99247f552de1be4bbd22e2c34fc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('1fffbce636a5f99133d3b7ef18cef6bc27f5e3b6ae04151594f20a504ad1f499', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('748813d9985b0e571c1556402d42c718e47b684fbbf2cf4e924e6e8273b3b45e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindromic Substrings - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('35c7a05eaadcccfb18b256b13ca66f13c4426d6e8f5cdfda86d699455fc42a80', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Daily Temperatures - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('ee8a2a31906e8b6e579a9761f3d60e0e32d7811e109741f3aa39ba598847743b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Daily Temperatures - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('01ee1553c58648e360662ff6f38e9894aa9e7c11edf4276425147a267019e2c6', E'import java.util.*;\n\n// Min Stack - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('d1812dfaff62d1eaaa0d463d242618c5d3306fb4fcf936358f0b254d8c755d45', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('325431fe6b2cd193993ed5c7b484fa4ab56e2b6004e11919e6ab341d64a4d721', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('baa3e4c8ad30e6065dcb5dc541307fe89309818d7cd04a4faa7de166b7370c5f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('26755c556759ceb9e9c50245dd6d9a5fd9d8710087813b49cc39b3c8878c9e59', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Palindromic Substrings - attempt 5 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *data = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('313f919fc9e04d3b951cc0f30df820760cf40319cf2b0559961dcd475a44b651', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Min Stack - attempt 2 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *nums = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('44c08b3eda560ac03ddf51167e5644e11c1cd5746bc9c712b386e6f0aa6e9a63', E'import sys\n\n# Daily Temperatures - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('d441e14fd9ecd22e5fab0e0a49852572578197583c8c964c8f71e73d215c8747', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('747c0b643f3eace227d1d204512ebea6d990a7ede4dc2979cd85d029379e776d', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Maximum Subarray - attempt 1 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *a = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('44aeefaa5a25f8b90141b8b1dae5a2ee67df5c30ed56fc8f10cdae961332f969', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Product of Array Except Self - attempt 7 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *data = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('f39d09f216a580bf7de2067c65e28dc8d96764fc3ef1bde806c59da40d02730d', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Find Median from Data Stream - attempt 1 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *a = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans);\n    free(a);\n    return 0;\n}\n'),
    ('33bdf6c42d393197a858f6e0ab2f31fdff65d013bacafe08224f218d3d623188', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Product of Array Except Self - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('d5b5840c9ffc66f6e154744b11a0b106c7a741b6fa2f75d4b259cc1d74ee9635', E'import sys\n\n# Largest Rectangle in Histogram - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('8396f514423e213b91e34437f6a2c62e66afc49f21124cfe7b12df4628b3e3e2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('c2f4d680d4db5691e3dd34db07e141c972cd13d6c60e15b6de9006159f70b72b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Substring - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('f2a9fd7562619576debd05ef3c6e2fece79b9b0592e367a4a14d6b1ee6ed6ac5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('7f2108cd4977b6bde9c13f7a1743ca77787ed84343da71fbd92a76ee19d48ee5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2905d257826c026076a26f740d545fa288cb9a90083866bb11134b3af1800997', E'import java.util.*;\n\n// Symmetric Tree - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('6f2f6a1aca167989c2a940c5baeb23d71cbb8db919d392900adfdc08fe99ed66', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('0aa64911fa3eebe3f3c41d51dc7827349a3d04ec1012a214f8f38282bb3e7296', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Contains Duplicate - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('30a9807fb4c19b6d585b028f0aa55690200d58da0757f67be1cb2aae4dd541f6', E'import sys\n\n# Evaluate Reverse Polish Notation - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('3fd5158ab7d8941de38ae8797887bf27e7e3e73511d3c16d492258a38aa224d1', E'import java.util.*;\n\n// Find Minimum in Rotated Sorted Array - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('0044d0e796901f80a39d38a2ba9fd182901ea9224d5eee8d74124dd6dcc5aa79', E'import java.util.*;\n\n// Symmetric Tree - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a3c4e03512769ede8d7dd58ae9ae478a5fc8e04decffe25ef63b148964fbccc6', E'import java.util.*;\n\n// Longest Common Subsequence - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('31cef6e3ced59e5be7268b47af2bc06f2403c17e0284e2b6d62ae5105346aed2', E'import java.util.*;\n\n// Find Minimum in Rotated Sorted Array - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('41f49ffc75cc304a802872b74df5cad1d252fa049a75fd01c846d21f1e42d657', E'import sys\n\n# Group Anagrams - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('78f2a9915e02e60d4f12367979b9dfbf892127bf1f971082c90089fbd9524e85', E'import java.util.*;\n\n// Sliding Window Maximum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('9b0dee1213e04680ac3400312974336d2d15fb23ba57ebf19ffe1a6f261e4d94', E'import sys\n\n# Set Matrix Zeroes - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('47b284047ad6dbaa405bb1f8b14211ae81eb6d230efb9e022bfdf3524665c713', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Substring - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5c68ea3e97bd06d761a0ea9f291dca9b86db9b7453e721ba12b983d952bfe23b', E'import java.util.*;\n\n// Validate Binary Search Tree - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('440137814c3912d6d529a48c68f5c40c7784ef336f935e848b41375189e8e271', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('21460f8c93e4d0eea3d2d6e477041c343fa8f3e6fa32836f9db35affc1615605', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Product of Array Except Self - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('6373414f2c5e87be11004cc3cb1bcb9fcc6c7fb6fb005f728797ac54a1e58953', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Missing Number - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('6a3d6862475c7c6c8e19aa3d89af23e5b58f8569b98ce7e436ac3c5aa085394f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Smallest Element in a BST - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('80dd2de69500129c9bb5b05fb9aa56e32ec7e97cef9779446ec70f89cd9a6fc6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Validate Binary Search Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('27a57b239c7d70ff5ee257423d8812285e9b5bc47a039ed72eaaaab04ad5b544', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Nth Node From End of List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('c022c4a6e876fdde1a710eba9916362d32ff879f0f163590f8736b76bc2694d7', E'import sys\n\n# Merge Intervals - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('e1325c9d400c9eb3fb91aae1b96e7b530856d2c5cda49219cf36ad9e7322ed46', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Missing Number - attempt 6 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *arr = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best)\n    free(arr);\n    return 0;\n}\n'),
    ('791d2ff31dd995f324265f3b6cf49a7b4f87fbb8e862d8e65afb629efc493c1e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('3016fcfe89084efdb2fb2d4de5aa85dd9ce9cc8ec07c1d3e4bfc4e553648d15a', E'import java.util.*;\n\n// Valid Parentheses - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('2c2b0d0f3ee5af11c6b314a1221247fc8f416da1507d11233909c357d742a9d5', E'import java.util.*;\n\n// Reverse Linked List - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('d35620ccb38a7a2ddd9bb5a5117eac8c233be6f4a2f5d5bafd338296318c9447', E'import sys\n\n# Invert Binary Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('5925096fa58940048928a3c874428aa57e3f07d0ace6125e5ed034bc87064a48', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Invert Binary Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('54147845f7c9af747cbe7961b05176874d5603a50333ffa81c5dd51c1a789e57', E'import sys\n\n# Invert Binary Tree - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('e3decb3a1aca701d611dfa570afc5c267db44e91f8ba15b181e7d1acd0a9d681', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Insert Interval - attempt 1 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *data = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('b815d65f9b782f256a0b79ba3181d1c4688fdb0e26aa83ebe60dc404dd971acb', E'import sys\n\n# Reverse Linked List - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('15a30aeea976a699bdc9d0b192dc3aa4feb9301ab7606c45b2713859d68d2623', E'import java.util.*;\n\n// Spiral Matrix - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('367abb58a3a268349bc252b90c0ec3cc15a526dfeb038bb6c126af082e6756a5', E'import sys\n\n# Lowest Common Ancestor of a Binary Tree - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('23acaeed9755cf51f8270b85d740262f1a44dbf915fb287c73d92d37e40ec2b6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('a3d8f5744be76c5078db984048e6fa656744d09c9e8e88c4446f3dfe0f36cb92', E'import java.util.*;\n\n// Binary Tree Level Order Traversal - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('256aee3fb3ed5d19e122bf00e3cfb499bbf32338675b12c996bfcb94dbb061ca', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('b915d040cfc992994f8231ca5ea0047dc39bb3d3de34c09afdbcf30e55c5b9b5', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Binary Tree Maximum Path Sum - attempt 4 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *v = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans)\n    free(v);\n    return 0;\n}\n'),
    ('4bf0deca8cec5e95798cd3a6f51e1f960f7ae675afb372e0d5193c2755f05d16', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('339b174d4b84991143f5052947b730a46c8e1bbd2fd1124e3af5b707e42f2484', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e4a8b2174687ba18d91683e6d95e365f4b49e1b2ba146f0e5593edd99b21eea5', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Lowest Common Ancestor of a Binary Tree - attempt 7 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *data = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('2de1c59de052c1429d3b8ea20d2fbd21802918d2fe129d821627eb4b99f32140', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('d7cdb97203053f3f980df12e49574ad52f38c08778b5ff8d0a6b5595c27c5b55', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Minimum in Rotated Sorted Array - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('4067712790ba1fe92d493a8577f8df9681cc5ad9a42329cbcbafe04c62e94562', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Contains Duplicate - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('a7637a60d01b32a70b81a75b03be2faab46d3c6b168e38d70a0b92325e3d9b33', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('52d998968002cbac9fe4a09970a208b8735a6264befda8d60337d4d2b9214720', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b18c09612ceacacb1ada32b725971bdf36715ec4755ec510d353bf593fb5ca7c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Design Hit Counter - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('c68834029a175b90258e65f7c65c61123474e495ddc4cb9f41080dbb7beb940d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sliding Window Maximum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('58ff6174dec54d7124288b2e335a97a67f346a73eb79e79b1e86902f3ca917c3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('09732f98580ef88deb5db8d6287ef7cbee7e9a850e7c88433ca43a2ca5635e90', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('c5932e540483da3da370795f1d6526db4b0be3d42b2bc5d4f730ce2a9cc5b424', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('6fcdf28e13d604834d09ebe7300ee5170e531b5e0ecfb861503ce41de66499fc', E'import sys\n\n# Implement Queue using Stacks - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('520a800d7230b641ca15c6bd8b41d57ce154772bd195052df186975dd78f1853', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('c27bee074630461d9fd1e678ba6fd0a53c18d440c5410307bf947f928303d1f0', E'import sys\n\n# Kth Smallest Element in a BST - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('5fc900daf7b07917eb026095857929763974730e3531472eac0b79ba6623b500', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Wildcard Matching - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('26f6c470b71d2571b1b5e69a99a72dd681829a435409971bf73cdd8f867bf635', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a2dc701ecbebe27ff3f9961c23d4275dc4d00f74bb61a1c2303e4fc75229b9de', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8e3b056a15b47878d082e7e3702b520fdf233b64bb4cec3f9b64c0f9704efd85', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Array - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('ab95589d8f3ca4f2e3059615f8b406c79606d917ef80a3efe27ef9560b9203a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('a4fdc5adb85b3beea7ec46156330eb483548c8615881bdced24e2da4b22de0df', E'import sys\n\n# Add Two Numbers - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('2083755ff429cf1225a391d0de290621f914348c9ce36431ba2327907778ca9c', E'import sys\n\n# Palindrome Linked List - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('73a80d8195bcf09f72d4b51cc568f3d2a4190ea11cceb5fe626314e4d21c3086', E'import java.util.*;\n\n// First Missing Positive - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('4e894a570cae4c50029f12ed33454a6f5e437324ccddef4a1cd87aed9b3b86c7', E'import sys\n\n# Implement Queue using Stacks - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e0e65dcf231d36d5636bb68632af025c3c6b6358b76ba8f1c525031277cdcfa4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('07491f5b08ae1d58ed43620f8041dd0738dabf8cc3657b97c24f8dc477e0d700', E'import java.util.*;\n\n// Implement Queue using Stacks - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('d6441610ae1c6a40f0728ae1473910dabd12816b9ad2104f38cdddebd12c61c7', E'import java.util.*;\n\n// Diameter of Binary Tree - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('e36b2729ad4055fc7352102cd0bea9e2b04188658c15c4626143a8eb334dd089', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Balanced Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('7720b8ac85268ae1c52677fa6d3795fe6b63e1792c753bb7f74527044bffc5a5', E'import java.util.*;\n\n// Balanced Binary Tree - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('5e0625fd68772ca1ffca1bb653cebcdd9c16b11bdc7c7c1d1c101d1828c16e2f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('bcb59f8414f7e8e6267920d12398d0951c5baf0cc17ee29a4faa75b7e50c4da1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('a93becc26e457cd1aa8b9c35f49180b30e551d2474876558ef978f921e60e686', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('51fa9b29e74674438b0345b99baea6ec9fc492979786a1e5e9d36b5c73bdb669', E'import java.util.*;\n\n// Set Matrix Zeroes - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('5d5e04d561a7ca575ab09f0b5ebd12b184bfee971d4516f6368cd345d27bafe8', E'import java.util.*;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('75eebbcc8585d8f12a2f90d434024dd6ded389731fc85c84218304464a13f49b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('838d7824c96ddb7fd146b8afb9f23c65d2ac6c650bad6f975c0941106f02222c', E'import sys\n\n# Copy List with Random Pointer - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('a919acef65061c6389bdbe76229331f9329cbdf81510c1d59a93e516db1db9dd', E'import java.util.*;\n\n// Flatten Binary Tree to Linked List - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('90b204324858991f4984f468ec950dd1122331eb3f9e27f5510a1e96abcf92ed', E'import java.util.*;\n\n// Binary Tree Maximum Path Sum - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('cfec0c4a9ca080de4c0921c8176ff2d77934f1215432f156de9a68a32e36e128', E'import java.util.*;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('9bf1053cd98c941e91cd3b2f86f48443a0bca9fccb36eed66150ada3cbb3c809', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('74755fccfdbd1b3eb0e0f7aa6b54ccf455646d16b6a0f9f4e0389304a5063490', E'import sys\n\n# Binary Tree Maximum Path Sum - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('77d99dff2d945798302948d1f0c7276b45643a8db4048c52936b11625787e1ee', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Missing Number - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('85bb0d0dd691147c2e5d128a6095d4624803b8aa03f76bf6fc332aca20a982a5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('80d68e0fa3171d82dc61ebc33d086c643af81b942dddc54ff7ad6c338ec22966', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Largest Element in an Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('1e7bc3714df6235bd0085a9a91c65afc416cdef497f1124ebe4dbc86376d111f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('fc30cec79dc66f6f9bae9e2baf1f8e8d7b53e740c9dfcf9e3fbcc62fb01b3f5b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b733e3b9c2d0fcc4039a8c1eca40ec17689492db165bd2988d3754586ab0fab9', E'import sys\n\n# Design Hit Counter - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('cf33b3b3a75d661566815a4d7edb45207f0694cffd7785d4a2720bb6406dfc46', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Top K Frequent Elements - attempt 1 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *nums = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('ea09676afe46e2cefe6c380b2d9ec8d86c403fde23b772aeb992d590157bd72b', E'import sys\n\n# Symmetric Tree - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('7d815de53226cd62da272b7586fd30e4753e7afad01f144094b439b39acb59ba', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('8ce76c7426cb2860d866321829b49b661120733cf5033fbeedac5b9d53f59d98', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Number of Islands - attempt 6 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *a = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('32e5af4ce6b17dc7262091534528fcb093f3fd666f3f1eac3dce87607673e00c', E'import java.util.*;\n\n// Number of Islands - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('34ac0c753265bf3ad87dd1061aeeb0368056d50ce0b09ef6131fd47181fe0bdf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('830a81b1759370ad625a8cefeaa0562fe78f482ee838a2aa2632c1c0a3bcf698', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Islands - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('7e7e5cba9ac44c040899d1e2b09f1331b77e171fde61ae824ef8b63959c52e79', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Decode Ways - attempt 1 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *a = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans);\n    free(a);\n    return 0;\n}\n'),
    ('19bc716456d98b42a551fbac948d3c700a599be324b120842793a7a8a3049b68', E'import sys\n\n# Next Greater Element - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('273863975bd470c006a7ee46fe6df5cca7f740f19072cc354719e0f9476e06df', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('9df195124650cf3fb15b63c111e258d1c4c1ed7e9ae96acf536e2f41e7833c01', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Islands - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('3c89e9f97455930665830d70888348fb896ee194406ced5570b518506f27be35', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('7fd5bd57975c8bf2bf09592a75f9acb0c3bf4129adde87da6b2807ba3ae05639', E'import sys\n\n# Invert Binary Tree - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('be216863fc6d9a959519cdd913f41d1c52f82f72372cffd2fa9761c3964368aa', E'import sys\n\n# Longest Palindromic Substring - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('6caacc46a863caf602b2a6bf8a8e78a9b2e86e53b1a69b185a76767af501bbff', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Design Hit Counter - attempt 1 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *a = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('f9ab69743ed51d31092e3e0dc258356429e48e1a997514d6af51bbcea6e4a30c', E'import sys\n\n# Reorder List - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('3bd52a0b499a1f9a0973240e63e18f688cc2325b6d14042e63d697b7dd852c61', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Smallest Element in a BST - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('c9808723afab58635396176dccee6ed794a77e546fcae75adcd072f4965057ab', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('dc64be152718da5c14b2b56d8f370791393b3fac7123caf5d6030af3ae2c259d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Islands - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('e144885da9b6d3cea29a8e936136b40443c9b3f84700e9b1f48919973b0eaba9', E'import sys\n\n# Path Sum II - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('bd972d2c7245720a4ee145772bb888c8387f1fca41559ca90a09c9c72004847e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('8334ac7001e4aeb8ea8704462265e22dc7b52ce4067e3fd1b99b1fd0e55c47e1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('0edbcc8bcaab5576549a16c6cb4a79c320363662400d69d7fbe9137ec4c4d16b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Path Sum II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('21c4a6e1423bc82970c44c3f5b0345b08153c98f3b63ff1a5452fda4224a9c07', E'import sys\n\n# Course Schedule - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('88fda2b50ee662b7a65892095b78405a400c56fe490913f6dff442c9c25b1c25', E'import sys\n\n# Diameter of Binary Tree - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('881f7b86175446f37cb52b221eae2d6200c77b9d133455e52fc7c9c523cc030d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Islands - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('ce826762578b598f47c3d1344713d3900515e98a9f0e14274144dcc6d39ccb1f', E'import sys\n\n# Course Schedule - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f0e312f0dee4e1c258d82dc5d20de57a2dc89cf77f84c01cdb207552982c7cc3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Design Hit Counter - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('209352e2fe49a8dcaf40e3f74db65398bfe004a87b88a613bc6341276f6ae668', E'import sys\n\n# Linked List Cycle - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('9e2ec01eb25add6c0480b5ebaa7a36fb8d43f6179f01c12a37a5e580e1e91297', E'import sys\n\n# Valid Sudoku - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('690a5b3f5c958d29c4010530a69d88706f85c5c8ccadc2e29d846db29431b60a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('5e2fbd3b682c84af5e8f027ba8d0c00856b2ab7269f303c691b40bc840941611', E'import sys\n\n# Course Schedule II - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('4b5ad4f7c1169c4a7e44eb76a479719fae19b461d6ac0bb850992dd00373ff4f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Path Sum II - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d2a1c957a0928feadf6a83c0d573584ec7c2e18796df8205fc9cc7f0393e46a6', E'import sys\n\n# Maximum Subarray - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('d72f13197c540518f60776710b565efdaea770ff3371d1b61d9f31bc7e890939', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5a96b8d998e9d340b416f7923011fb61a2b0bd8c091338074acfa1b6f29b30a1', E'import java.util.*;\n\n// Word Search - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('2df96ac0eb42ffbfbccc928f2a5f458cc8a8f4c232348702dbf50bf6c70b49de', E'import sys\n\n# Missing Number - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('c4c721712699247ffb9118800b46eda24f06e392395b0e3ea4db9a3bdb8f5474', E'import java.util.*;\n\n// Pacific Atlantic Water Flow - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('0a0493d5860b0e46a41b19e61f7186de347353bb29bcdf0790c9852b4bf0d295', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Intervals - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('808d4eb881f32e2303af57d668adf3e4e688c8652cefdb32c5522919e37c5a9c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('245dbb0fee4fd3a1bef882f791456be9bf7d064385c753cefdbf564f9ced455f', E'import java.util.*;\n\n// Maximum Product Subarray - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('b0469a76e52f55cecffd6c8c295b63121d44f1f43efaab06f45a9491c1a45357', E'import sys\n\n# Kth Largest Element in an Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('8af2b8a11490a72ffbb0f35f88b8a1f5432a0826c34a8c19f9e93c3e1d445e9a', E'import sys\n\n# Kth Largest Element in an Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e8cd6c9a13f07866abc8e3d20bf1d933649516a54bd6233bd75e44628a1af799', E'import sys\n\n# Task Scheduler - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('4aab436e7b6f492d6f2cdf2d5866b2a300b6de04492af7dd65ce6e1cd4959d51', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('505c180e8b8cec5b28b1c901dd7c2c488c79781191d80176b98869836a698398', E'import sys\n\n# Kth Largest Element in an Array - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('22b740940ca2309f51356f3deae969db0f0593c3d9f8495b9f66b2f85f9733a8', E'import sys\n\n# Pacific Atlantic Water Flow - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('405c1662d903184b79b2bde2d34f94c1a6c916a9474d87e5f6423c4229e5d941', E'import java.util.*;\n\n// Task Scheduler - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('05b8a7c8dfcd198622e2b138569fbee48c31e2ccee2b77bf81896824333c7164', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('07613b89b1193a53b473cef0b904d9685634b0f00084250158eb3a2dcd4a5f0c', E'import java.util.*;\n\n// Sliding Window Maximum - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.printn(best);\n    }\n}\n'),
    ('7f27bdf55b141d22406a52169ec8964018b4943ae34de6a393a5d355c4bf64c5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('c3675e66e99aa977cf5dd5d952c77dad347ea1d86292cf536ede641df5a1d56c', E'import sys\n\n# Three Sum - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('f8d69c8fdccb3d650fcc15f21767783dbd68444fb617e2d53f2f0f757ec6c700', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Rotting Oranges - attempt 2 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('39edf58c4d3e82f903a026f41764a167ded317e375f468133c7ad39536061f59', E'import java.util.*;\n\n// Flatten Binary Tree to Linked List - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('59b25ea47639dda168fa64ff23ea060354f36d38b7ec30c3814fc71e6d2731f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Ladder - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('672ee24b1e50c6d706301cf48e5beb302c6cc760871582fce982a0fc712fbcfa', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Flatten Binary Tree to Linked List - attempt 4 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *nums = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('be86dc2ce785b7235d6d742a6d507e35d04e7b687e09bc22c33ba3cc76937a79', E'import sys\n\n# Lowest Common Ancestor of a Binary Tree - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('89910cb2e02302fad39d27b3b9fa778a5443fc85c21b1b7b5c18449c8948f77c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('870b7746b6185ba109a9436feeec0c80e03b69f757d70e224ca19e76b3773baa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('3de9dee4dd1791299f566ee16c958c31d031a1e8eb3e0c44ea1cd2a63e6ce1c9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('e50c3f8a19d495409979c41c98f81d18fef7d832bbae1c46ee9bf5f86cd6ef1e', E'import sys\n\n# Non-overlapping Intervals - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('2f8b1a9ef667528d0512d0f305c5cc4a455ba158d454b6815b96ec4f6e6114ba', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotting Oranges - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a67555336861bffe1a09f9fd39228c27ac579211f6eee79a33cf613b5903e451', E'import sys\n\n# Implement Queue using Stacks - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('5079536dbda3ad60722f580b568655f23970c28c15c64b27bb9ab7713140d330', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('deb6bec4167059545082ea6287cef140b858cd69193e06396b2ee6929495a9ca', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('4b7b089a974fae2b476e86219c8991b1c937139bee3ff5f0f1c9ebf800b12c6e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('ebd758b7ef42f2983844a562724362ae4a704102e5d59cc1568eb493c9c05700', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('591b979a02f535eede2f7d76865756bb0ccb8d025c0cd50b63813461dfa054fe', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8fa37bcc37fcb08f99faf46abc5ba8ad1e8c1919959339175eb7dcf3721d37b0', E'import java.util.*;\n\n// Linked List Cycle - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('f934fee7812ed38468e38d97472a78c24ed6dde0638fa519f739e723abf85d18', E'import java.util.*;\n\n// Cheapest Flights Within K Stops - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('dd8da24683a186d635fb3dc6623ae360bd3957612e7d6ad428b0a28c6352ca2f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('c2cb1b39c8ab815287f5c435a241a988cfb25f7fac424ab13a18a7ec668758af', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('392a89b83f276e91b4b59f9f1d9c6b08dbc7bc0d05017dfb588e93c25393398f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('7fe43608e944102c40cbd683b0ba484351fb06c0bf17d036bca98ff361bdbeba', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('7f7f51e0d1c210fdb42cd1c59c468cc280ab331dd9b567c7d443119d23372d96', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('60a2cb884d2cfaa79b7dae9da6f665efc4e39340d0eb98fbc874023bc65ab7a4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Cheapest Flights Within K Stops - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('a56871027179a4ebf0d87b5adee0f6982e6cc5d4821678d1d319de75015a6339', E'import java.util.*;\n\n// Cheapest Flights Within K Stops - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('a6d98f60fb3498208164a8b48c71a7728f73bc428a4f9bd8bbb273a4845b2cf2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('55d5b9dea2c500a3db31a0454479ba92b016f90b253080b89e279aef6224f158', E'import java.util.*;\n\n// Reorder List - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('ada661818f6bc3990406667173b35b5aa62a8057e0844757fd2276c001dff1cc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('adfe12e80ecdcd5b0bb08160d6f06d12149f3440b01c6c33d305d7bbbd91d56e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Network Delay Time - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('74645e8f6f1755ea6606317191ec7450dba267a164d7973e06596947b538d8f3', E'import java.util.*;\n\n// Rotting Oranges - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('92dbe08d38e19e6e855e14715300dd0a57423be90ac7ec67033f7782a78be589', E'import sys\n\n# Pacific Atlantic Water Flow - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('347a01626c62e50ef1d697c5bec03a1ff867f7c6570c7dfcb9ddfbc090da1129', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('e37e64b66c74af7f72400c8a39f0aef71cf34ab10d329fcca896902f27e18c4a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotting Oranges - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('01f719d85bc50e2036f07173ff862f5e2fcfa65ebfa3c00e647a4b60c379c530', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule II - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('4fbc7b2a74d4510bf3023fbd0c1d0a1e0732299d3a6638ca8479f0a4a6e7aaac', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('7467734d50dcd2198de319df8f70834d3fe6157045d7d2631ccc67505315d9b8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Largest Rectangle in Histogram - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('7747743691d4865b1db524090c37318efa198449fb05abc47467dad8952fcce3', E'import sys\n\n# Decode Ways - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('8c4fd219fb76b8bee9b8ee2f77ff51ba1fb9dc523521378c71649cc5b12f6320', E'import java.util.*;\n\n// String to Integer (atoi) - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('1c398c84e3a0225e5d996af1c65b11ab659db271cfa64bc76352a40b9c120683', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Graph Valid Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('dee81ee0186df484afc792aecad37185579570aed2ed6ec8793f1a7281643710', E'import sys\n\n# Graph Valid Tree - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('8438524ebf4813da6474e14b7997750a5b7196a8e49f19ec9b97e63d62c2a82e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('87f70065bfcd251a1ba517c474e3b8537f3c0f37c5b2024e722c39d869f69f1a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d5b54a842f7662be3fa344e55bba346a8ed8e7840da309aef9d46f6e7352e605', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 8\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('0b10dc4fc9793de0323da353e3ca6d42d159c9a6c3fab95582910467451b52e7', E'import java.util.*;\n\n// Redundant Connection - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('3b3aea608f64e49e5cfd720ebeacad6492980a80d991592b1af926f0f8b43b9b', E'import java.util.*;\n\n// Course Schedule II - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('e6796d00f3f88275a012f3c5769378efe0236ae997fd8a9ce00012aa4617202d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Balanced Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('a08cb040b0ae008c176e358913c54a376c2ef1301ae487efb9db2abe9ce70956', E'import java.util.*;\n\n// Rotting Oranges - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('11ae2dd23da451314e021536ed5e377152ac6d9abf5cb07516b71425b29b274f', E'import sys\n\n# Word Ladder - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('f4dc80c747ef2399324128ada20d5230a56377d170a8f706c47ba4882228bb51', E'import java.util.*;\n\n// Course Schedule - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('aad61c72a9970aee85a2788c0970a2ae07e917b40db24401505d86aab8361d73', E'import java.util.*;\n\n// Add Two Numbers - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('4e21701936d3fd6b20716b03d87d7797843a286f96a63f80ca0263c763389e39', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('8dca90639a78c303110ccd4b98e4451844a2e2a39df17715fc0a68ad640317fb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('4b539c1032707459e240afeb3e7895d8978149216b2c33e1c439852821229a13', E'import java.util.*;\n\n// Min Stack - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('1e654b6521fbfe6a7e2702205e50a7f14e1c786d4389f9bdb8ed723f14d0e05d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e4f811077399fe889b15d51d4bd0d8e6b158fc62c5e2009f528164a9a6a484ab', E'import sys\n\n# Generate Parentheses - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('df7dd8d2dc0cfc98c7e9e5e68b743120761cf7fbe1fcc2663fce40e1ec9dd25a', E'import java.util.*;\n\n// Graph Valid Tree - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('0ebf61f6cc89b852b3bf6b306066821fb7c80b6df8b90c6bcba82c4380b44e40', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Connected Components in an Undirected Graph - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('e5929502fcd840f5f9c77424d2f4376b5debee8aae515573758adb9c8892154b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Graph Valid Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('784e1c462d345f8e59e9cd33b1ae969f274c8a171f88c0d13c805e26c116726a', E'import sys\n\n# Graph Valid Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('8c4e889881d7118ffc717d3277b5a40f9fcb50decda96217e103a7705df0b6be', E'import java.util.*;\n\n// Graph Valid Tree - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('c477b85bc8f839dd7f3547f63b86c58db705091fc007f4dcda587de6f578fb91', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Network Delay Time - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('303cced195cbe8eba8dcf4ba50cf6ee06390a7d227da3c5707b5eb7f006d62f6', E'import java.util.*;\n\n// Network Delay Time - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('c3758c530070cc96a3742725bc3b4d476dafca78c02d13a83bd7c9c0e1ec48e9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Network Delay Time - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('f1d324d786d82475dad4c2ba8ba56ef58cc346cabf62eea6436be50d8132c3f9', E'import java.util.*;\n\n// Evaluate Reverse Polish Notation - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('8cacf2fc474ceaf26164e9bef12a02b46cc83e5e7330681d4edbf901cac5d281', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// LRU Cache - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('cf4e17eb047dd9e438d0025ebe4bb7e82089d8c4843c3bbb0c093a7d7b11a1a5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('8c651c00545d1549e8ce22be00e0ac23f663adb018ee0955d7f7a05d044ba2a4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Spiral Matrix - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('e4a67ca9d891311c63a5c08aa22387a0ba3c2221854fe987dc5e4c665ea82b53', E'import sys\n\n# Rotate Image - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1\n\nsolve()\n'),
    ('a4b996f79cb13d1e657d2d7b24f5e3c0ed038eee8a0705431da2e049b2186df6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('47aef0d8ef34e4a415e8d2636a7b539624bacf21e97693fe559170bb05fec4e9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('086c4114aaab0eb4e62a27e904426e3e5f65d66f1e24ac80204fe392ebbd85f1', E'import sys\n\n# Count and Say - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('34a81b6dd6fd337723baebebc3a92168abed5fcfdd467e01d580bb97e4ef2359', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('abedf5de7f6576c0c5256eb12ec85ca7ea4e0dc56fa2f910633475eeba665487', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('dd2bbf92b4369cbdc97d6337e749b1efa499ea8d9c095b77b4b4bc5a6daf2547', E'import sys\n\n# Symmetric Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('5834e75ff01e16b4541ac5b20287d3436167585c6fd43c30206016a409a4d499', E'import sys\n\n# Symmetric Tree - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('cfce55793c60d503696648efe58f452c31cc28df5c9eadbb58e1c6d363e90dd8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('8e25ba956eaf74c06bad08438b64917d5e163c11d12a82c6abe0651556f2c059', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d62b63e31d77434a712b608a79f3cba4e715db94bee856b5b340dbfc3b56a5ab', E'import java.util.*;\n\n// Count and Say - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('e80dd10ccd49ed793ed81fc68262552fb0087e0e14a2f679352d0bd2c5e73ccc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 8\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d6e3f377196022f2716d5b2a24a1e619172c62f0d6891a39120887887643f5a0', E'import java.util.*;\n\n// Symmetric Tree - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('518c321cd274d84ead9812ba112a9f74b9e96047278d22bcb9c2c0ebc6cff9c3', E'import sys\n\n# Find Median from Data Stream - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('041effe4da095bf6d4a8757ce628c3f5714437e1d9ee22d56f398457a7f1bd2e', E'import sys\n\n# Insert Interval - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('9c6766069d599318ac2e0db59cfb0af6b9a739a5ce91ed4dfab1a1e8558729e8', E'import sys\n\n# Reverse Words in a String - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('fffad88d64cec9eeec6945ee004001ef78814da945ebb68eb0ae8e6f3e7b30d5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('896b1e208c5e0ae76b1b9adf2daa5dbcba7a7705a18afbd85b3e998dd970c252', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Balanced Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('d09f98e78aae4dbde0d69b584936990e90ef86a845ac88340c337dad6982a6e5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('548a77a1b52380a35625aac9c4eb987bea5125bbd47b6e706554204cb53c077f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('4651be70dfcc7966bf1448c98c3701c283c1c3c9126017d9f4e8befed008c27e', E'import java.util.*;\n\n// Container With Most Water - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('1ea9caea7977eb09bef50e4f55f6a6870d8df196f9d43cdd26729ba865c48056', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule II - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('023d843d2266908a9ee16838d3ab1a62680cb8c6de1334e0de57f0aba9210af4', E'import java.util.*;\n\n// Palindrome Linked List - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a87ae8411ca6027fd3443819339bb7b5610c170dcebda03cb975a0976daa8a55', E'import sys\n\n# Decode Ways - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('ca7f8ccb0371adf526b15b309eb2fac0fc83127b073f249445e650e7bc85fc1f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n''\n    return 0;\n}\n'),
    ('f10b86aae9912c058a838174354e84ff667a13a8303c434c7f0d29421d1edb05', E'import java.util.*;\n\n// Implement Trie (Prefix Tree) - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('bb3496692de6582575f5a16eec9930aa9a0ba364ace13d8b95f9fac2e6b318cd', E'import sys\n\n# Kth Smallest Element in a BST - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('35279327564e76886ebd764255219dae2d1058ee93887b2835a5da9b912c3c45', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Is Graph Bipartite - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('27b754211293645e76d8ec853fcfb187d2a47f71cacec65b35ac87c07a4298af', E'import sys\n\n# Is Graph Bipartite - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('3a0bb434b03cbf46e34cde2f146c5494ef9c8d2c3d26c212d395112b1f5b0331', E'import sys\n\n# Shortest Path in Binary Matrix - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f281a4bed97982b9c8b006977b3637a172dad3ad9eb156395e431b7404ee1fa1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Shortest Path in Binary Matrix - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('c091a153317b37c6bcb4c3c46f2abc4765310efede23fb83fecf5400073a355f', E'import sys\n\n# Serialize and Deserialize Binary Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('f1c0191e14e8441be4b4dea3d60384d38a5be78740495541f4b31b194b66c915', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Ladder - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2efa3c85de11f4a6821766b6b0fe904b5379340460b6a2a0e5050d88a801bf93', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('689b8c3c9c18d4451fbd4181119dd6cfc2a165f0878378e2f3f148a331012db2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Is Graph Bipartite - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('2872d4a859b01b731ff914dc52d252be617aa347924553bade46f6f956065665', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Group Anagrams - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('320fb9098fc04e3139b71c5bf9d30df94654e3f0781687ba174d9f4f29dbba77', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('42e308a76c29589244eb46903ab761034c774fb808f922850dc199cf85e64cfd', E'import sys\n\n# Critical Connections in a Network - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('c4a4c2a445310b0cf5216e701bcb9bd17582b6a7d5763d27c5ab42c09b44f655', E'import java.util.*;\n\n// Decode Ways - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('e7b8e63a459d1e8c38d821b42f4dab862aef27e5232b6309655253f6a4dbcab1', E'import java.util.*;\n\n// Alien Dictionary - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('e5d134f6da1d0d3c7b896b18609ffa3d203723db54685566f0726a8bc17b5966', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('d88999de47bb595fad75c914ca8ec1ba70735f8a90029d40ede1d6c887a87695', E'import sys\n\n# Implement Trie (Prefix Tree) - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('194af8d0063d85eec69dc774f2bf95e8cf500e8e78fd9c8459b0edd4062d9a79', E'import java.util.*;\n\n// Alien Dictionary - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('7433fcd2ca623f6abb7b65f632272d17a979116ba42912784deb6f6dc44d635a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Copy List with Random Pointer - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('9108d9d111ec5c892c83c53d375c529f5ecc67f4b789feef80f4686e8588eddd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('18fbdf68edb3aede202385ccb4882de3eaa1d1f34a177e3282b297017a19ae28', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('0c21ee75f5a715b130a88de78020e0ef0622c1589ca2c417a620626ab0ec5d19', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ad633433b6157781369fa2ebc8bd7727fc242d5d3337deed5ae49439298291c2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Image - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('362e9c32ac7366e23e96e347bdb27b4edfd836daddc642c9a8203f2f19bd7c21', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reconstruct Itinerary - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('24eb2d88de059f2bb29e2dc83644f0355ae843d22fe3a3a1d9ef5883c6027c82', E'import java.util.*;\n\n// Surrounded Regions - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('03c81c7abb9346e2c67cdfc3d4b500cca7281a332cdcb79ec7042601a416b28f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reconstruct Itinerary - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d4d30b5c0babeb24314acbe066e9ffc537190a2067cb8c06222d6ed022d0e4e3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Critical Connections in a Network - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('eaa0136b23d6cb27c0029806e476a739087df19f64b8f1653b1e32345488c649', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Critical Connections in a Network - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n''\n    return 0;\n}\n'),
    ('ca1a23325c7fcaa2a02c887b683711f42777b5a5112c03b32299e316ca12b330', E'import java.util.*;\n\n// Redundant Connection - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('28dc5862e3069990549a9118311cae1bdc2b57d0da924c824491201ae933bdc8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d0f2198a73b5c455a929860c3f265134e446744314d4f9b3a62b74186848f148', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('01366c001006ae9af8db72e03a6a6e72c60e7a3cb27755ee97ea6ffc98df452d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reconstruct Itinerary - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('44bf8a0295989c91f78c2be328f4def5f60f868fa174231b0f06b9b7f97c1edf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3b74bd749348d44edc55511654fbf396562c2306aef3771a8d0470593421c927', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4366f369b5999a41956bba4d67153cf8507338eaafb68e264359c5e0db1890b3', E'import sys\n\n# Rotate Image - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('9832711333ba51e320729fa83aeb1c22600a817dcc22ae16ddb788d4c89bd02a', E'import sys\n\n# Two Sum - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('7969559795df4c4b62cfeeb04350e97127bc4904617d5974a2cf4d2a090bc25b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Path Sum II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ab24fdd963929f324e154af12debe8f120b2db1129f5de6ac9e8ca1892313959', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Add Two Numbers - attempt 3 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *nums = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('5a9e54ff8164022136f7da0009b656e41a7a0d0cc9a1326ef23a8f9bf34fdf8b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('34dc5abc12e6eb4907b9b5134ebadefadf7be06587ee211fef175ddd2ec99e1b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Wildcard Matching - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('0c4d55f7225e7e5b8d4eabda1b6e1bc450a4867884270daa83434d010c3bd02a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('f52f5c691cf394bddfdabc2f5a4f876dd4a2d2b7423a29bf3eb52d2ffedfb16d', E'import java.util.*;\n\n// Longest Consecutive Sequence - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('f27546dead363abe1619d7f3e7a5e4acaff2ef195c258dbb5b31188b3b11e0d6', E'import java.util.*;\n\n// Add Two Numbers - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[cnt]);\n    }\n}\n'),
    ('b42b529c2335380f4068ddb0778ae6b7480b6ef3116a2256f4aff3e1ada57049', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('bf7622af0bd97ef23396bc152a2d264a0d394b988aef88f136df46d6eb29386c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n');
