    ('1932ad6238c1c33144c9b7ae7fd215e08389efc590baacd5f73d7cff02043db7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('54b2fded3e3f2cdfc43ffa76f56d1fe9913244576ae24db0b7fa3e2d8364655d', E'import java.util.*;\n\n// Implement Queue using Stacks - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('0f3d1d90be96ef888dc0fe496adcf7f19ee55d15d15bf5af2cd7c21d03f33ffe', E'import java.util.*;\n\n// Shortest Path in Binary Matrix - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('db950922d91078403e0cdef4f2f81b13456ce17ee16dc2b85a1752b502c1d27f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Swim in Rising Water - attempt 2 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += v[i];\n    }\n    prnitf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('46759053ca26b47389442bbe0525a22d53218471c34c56a334474e942f17c7d9', E'import java.util.*;\n\n// Minimum Cost to Connect All Cities - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('4428a94ffd64d8802a8dc64a8a4a41d6fb94f4c04394f36787cb73456b7be1ea', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Shortest Path in Binary Matrix - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('e126b5263eb5c33738bb64fd88c1d09ec8b75eacfa6787da8169411dd4be9d84', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Shortest Path in Binary Matrix - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('13b7e6cc4a4a77bb6bd5bdf190fefbb66daeafcd755f538dc7bd4ec4c497d0ce', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reconstruct Itinerary - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('e1f85b84200d1eb227dda4ccf74fffb71db6771c8d40e3000eec150cd4d39a97', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('a611e9ba745e95bcd50129538b578cb9e98b0f7fbdc73b6c7b8f35ea8d903104', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Parentheses - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('0a1b4cb2c6bc9b3c00ad3d4977061b1f5824bcd0cbf55f3ee309c2a7df3bf431', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Evaluate Reverse Polish Notation - attempt 5 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *v = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('f242e2240947827e419a58c954ed9e257b59c0c361d6849a341cda0c80991841', E'import sys\n\n# Invert Binary Tree - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('2a3abaaad44658bf1220ce09e31bae8f979eb9b711a9e3410629b60ccfc6a62f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Path Sum II - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('743020e3b2e07a030a3f9dc974b52e86d4abeb1495f0523232d99f4bc2377941', E'import java.util.*;\n\n// Climbing Stairs - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('d9da50782f4f14ce6f7186aca74d072de490098e06f2ec1c87336839b7007718', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Cost to Connect All Cities - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('d059ea0d94b10ece312aa40da19d2bc421f7d968d931cb666e690eb6d6228672', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('ff50187192fea2de7786ae9682febe32f42f4b996291c7853bad16eac34b7bb9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('788dd327afa788e446ab5d9181f601fc20522e1f91638327e450a9ce706af7db', E'import sys\n\n# Majority Element - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('96bdce07578407cf44e0bcd14262b8058cc940621aaa52e0d302982c21bdd8d8', E'import java.util.*;\n\n// Longest Substring Without Repeating Characters - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('ed83036ac0e17b37bda17651f65d3e42eaf4dd68642e8a8cd087ef5972882c3f', E'import java.util.*;\n\n// Merge k Sorted Lists - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('2ff60543b832abb970e57870fdaf3d3e63d1f62a6caabd92c5f2844845747900', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Set Matrix Zeroes - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('3bd40dd1634762ada3148af27620a5a3b88e44acf75aebd5e5aaf170f8d60018', E'import sys\n\n# Pacific Atlantic Water Flow - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('8503f90ebe306524930346f65372e89e8a7013aefeb2b9d9f9f2a35a04a10a1e', E'import sys\n\n# Symmetric Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('8324560c14816e3290553bae50fa34e46b9c20a80af90bfd820221f340f53dd3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Majority Element - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d440b2407e3c0c89f06ec03867dc516a41411810568f68e431013677dca4ef47', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Group Anagrams - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('7023b8a9402ceb9609e818c913f44b3d486e3303c4265304d788f3f4a232a954', E'import java.util.*;\n\n// Climbing Stairs - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('d885b105cb8c2565a34c8815b31ec5b245a517a3d8cf5955907e94fa483e7dd6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Regular Expression Matching - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('b26201f437466dfd8cef377cda7e76dc2e7131a2a7bd6b93be722e759fe5e87e', E'import sys\n\n# Missing Number - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('146864b8da567c473b1ba1e190b8e3bf59a64263cad62f37f88ec2a18b1374de', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('04c16314806a8db31071f7dc78a42f70e37b8789e2444207ea47b4591beeef13', E'import sys\n\n# Climbing Stairs - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('be891de446e0967ae1fff8e3c6d690948516a093213de3b3aa50ceacf760388a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('80d7c09b553590ef2ebd3ffd3385aa81d16190d7287c4ed51777f329f57a7384', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8070022417f2257c8d57190a33c578f0f48a2db8661da1e362bc340062a7f506', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3273dad89292b183fd44f6cdf0ed3915373f5fa1a8acab3a6542f16f50d91be0', E'import java.util.*;\n\n// House Robber II - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('9a64ecefabf0499ba940df6c1ea20fd3d66a82d3b1ed2cb74aef88e518f3ed86', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f75304dee8ebd2d118ca7db82588af09627aec8b942d834afc6259cc30edaf84', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('db3ff726b76efb5f8053470489d008a79f3595e471a2100fcdcdbc56e3081a3b', E'import sys\n\n# House Robber - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('09fab66e6829107784a6cb9f9746329cd6fdbbcca61f25621a33620376394712', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('5768409f7a724455d3fef0813e72e47ef38508ca9519c31cd74ba9e2c4f04b1a', E'import java.util.*;\n\n// Climbing Stairs - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('c0e8bd8e324cba6b3f4b977d9c185832ef575da9fcb3001676c034540cb8f49f', E'import sys\n\n# House Robber - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('dbeaa03dbf5be00c9f5df76169735933765fcf89cee5eb9ddb1ad3fd12b7f4fd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b4c7f40ea71bed783e2ddacdf8c8001606f754c9983c308d5f788447b88da5b2', E'import sys\n\n# Climbing Stairs - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('07eb963f05729bea8906f8f5417b6e0992a4f0bfeb2b91bb5a5c2e7b1b9f5dd5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Container With Most Water - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b9dffc3dc87ee21aac1f9396a7a26b896e3e59ebe381171d15711dd5324b14a2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('3d53cc77ee35dbbec4892246f21af1566ca3a0431b314047c375d4f401b04894', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('e669c542017f3e9672961d512ac9583b0aabd401896c507e5171895b80789ea1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Group Anagrams - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('4678c5563e0e0f7f2209929b9f1787dd2e39c093e3357b4e913ab4f5fc591f1a', E'import sys\n\n# Word Ladder - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('a73178e8c8de9ae2c3f581585d251a801bf92c0ff2f702a7386fab7d291428a3', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* House Robber - attempt 2 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *nums = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('684c0fe3c7fc90e883639cb0f491166e50a91498882f1f22c50e36c2c10d2690', E'import sys\n\n# Coin Change - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('837d759448e0fe37565b50eca9ccc12f1b3d26e3f09788fd21aceaacffc4c390', E'import java.util.*;\n\n// Kth Largest Element in an Array - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('731717e3cca6fcf1ecc3abfda53898b1de2482dff466d511ab0ef7ca24b09672', E'import java.util.*;\n\n// Task Scheduler - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('ec4ddbe5a085522493b93288c0188de62bbe4a4f32ee1af66cac08c8fd925b79', E'import java.util.*;\n\n// Climbing Stairs - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.printn(best);\n    }\n}\n'),
    ('6664c84525a84aa1cb75fb1c099a08616ba1595c5cd3896d4010ee6d3606b5bd', E'import sys\n\n# Maximum Product Subarray - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('b6a9965b88a62ba399e5c9b6364c26de59a609766733c3318232dbd9f06e74a0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('11efda43219a7d1abeea008de7b41c26c9f7d511c2fb38697ef0cfbc3c449fd1', E'import sys\n\n# Count and Say - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('f9c9d0668c5e89e7ed36f15972b23fef275123ba4877be548ca534264ad4dcd9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Linked List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4b845f9608e0e687f7cdd21dee836e7aeddcffc17935dfaf3956354789c165e4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('6afa1c5c53340b447324bd20a9ff9880a0907bec2aba1124e86423cf7b578fc4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Parentheses - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('88d33044971c100bd40413d27c3b7b21c3778ecced9786800e1a41202b3af5fa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Graph Valid Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('6af94a2bac25d08308790aaaea6136b0f8a49637945189802d342028cf440c62', E'import sys\n\n# Sliding Window Maximum - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('bb268ef6f118cd63052484db9e5328bb554c480438615b45d05bd2aac2f24203', E'import sys\n\n# Two Sum - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('6da3205a9c63916ab3b50d9f95277609d07246a104f381e048dab7622a3bc55a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Product Subarray - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('f1186f064c364385dc5c7258c074fe34c5839945d527757d5dd3eac6d71257c6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Balanced Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('75755b5c3a2dd440be7b8bb1d6add806843126540a4c6cfca033bda0507f7201', E'import sys\n\n# Merge k Sorted Lists - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('f5956b1576baa5f48a11f1dbbbf3eb0318aa0c207320b6340c816535255972e3', E'import sys\n\n# House Robber - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1\n\nsolve()\n'),
    ('b70557482943057207b16baf72629e09152de18e358b03746f9edf021d35509e', E'import java.util.*;\n\n// House Robber - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('d9223604eae1b7662721636acfbe5ddd386a649c094fd5aed39c04f98fc47511', E'import sys\n\n# Coin Change - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('b86e1cd492369063fb8e0434a15de712662d6beb47b7c7bd943020adac839206', E'import sys\n\n# Coin Change II - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('f659b29e35d39d8c19f1817f6697506b9b917efc09795df09b0b0486f3835ff1', E'import java.util.*;\n\n// House Robber - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('327c5c0686585bb9dfc3e69409fae64765898a6122bcdd9b702dceedb6616a7d', E'import java.util.*;\n\n// Coin Change II - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('1b0a719d7361e7e3c681c423fc5b9460c9f36d7eacfc7294a45095a6b5534502', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('3e992c02ce74f538247da4cfae6d3f0da91884b9354cc385cb50026e21bf7ac0', E'import sys\n\n# Swim in Rising Water - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('8618f15de010396b094b06314d78381b2ae02079f2de58ce255e0c9554c2441e', E'import java.util.*;\n\n// Non-overlapping Intervals - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('fa11d6749a7239140a09bfc9fccc6cedacb54c5109e0d1d5e921c218da4d6e9e', E'import sys\n\n# Reverse Words in a String - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N]\n\nsolve()\n'),
    ('16ba9b9eb786b6537f5d10ca6a35036bd0d90eebf00b5ef24343247aa5e997be', E'import sys\n\n# Regular Expression Matching - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('6c20a33205d3c5ffa23675bde7919885ea2a202458a6c845b81d56aa38fa1e80', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Find Median from Data Stream - attempt 7 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *data = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &data[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (data[i] > cur + data[i]) ? data[i] : cur + data[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(data);\n    return 0;\n}\n'),
    ('9e15851947aa0d0d10db79404fba538baf18c199d9ea92f3fd2c05113a65ec26', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('2a1a66baf4e83d2740b19bd335803b1efebdeef1aa9476ad6a4251f6d2450836', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule II - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('0a9b25044cdc4bb76906b657588de27a01be4a3f1ecabb2701796e60d3d58b2d', E'import sys\n\n# Word Search - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('28dcd8923366fe5c389639baa4d7f4b74aa849176bb78dcaba334dd311e448c0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Swim in Rising Water - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('0b71816d04a43621ed05b83e8170fcff3c18a39e72a1ec3c4f42a083543e5c22', E'import sys\n\n# Contains Duplicate - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('cdbe91f0fc707683a2e220f2d2ff7cf20f0b308a72fcbb43c047fc40a8110f59', E'import java.util.*;\n\n// Contains Duplicate - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('cfab7e6c98b3b50b8437fd581cd8e9374aba3f9588a6f268411dbe4bf44f53f2', E'import java.util.*;\n\n// Diameter of Binary Tree - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('38a2aed0f2f35314e3e043f893ec9f9b8b8c23d114f2f7124e400d2a457ae38f', E'import sys\n\n# Critical Connections in a Network - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('4e76331ff51ef7256d34f50fde7cb6a8bc17a6aeb978f31661cbf29eddab4ce0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber II - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('c33a5589157239f691ffe787f0e4960e9de91c621185945609d59b91459649f0', E'import sys\n\n# Longest Increasing Subsequence - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('ebe92468bf33796327465f0ce8a6191e0cc4c6fa5e2f723041e8a858f0db7df2', E'import java.util.*;\n\n// Longest Increasing Subsequence - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('3030fa9ec67790d51e33243cce2b2389496fc842df8d6612bcb4f58ecd151a1b', E'import java.util.*;\n\n// Clone Graph - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a861accefaa561a66de5702b8c2ddaf9b4b267702fd596f601a2b4a3d13d284c', E'import sys\n\n# Unique Paths - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('7dca5c8e1fb38addce7bc54fae77852e7b31d73b2d557fa555ce1dd247887be1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Nth Node From End of List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('523ccec6f80e3e4ca793eaec2780b39d71bb4e5b7ae6ae7cccfafe9dc6977545', E'import java.util.*;\n\n// Binary Tree Maximum Path Sum - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('aa09d896b96613ce7f3b64c864a23030a41081e06d79f851e79e1e4b613384d2', E'import sys\n\n# Number of Islands - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('1b2bd66a3f525f5cc4ca5c38f321c0cc09b4d658f9a34d9d87459af631300d4f', E'import sys\n\n# Largest Rectangle in Histogram - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('9e939ae11065b2f752390d45086cf6bb85ba80c9525f54f3b2d06c789ae4f2dc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Swim in Rising Water - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d71858f214cd8c85f5e857586c55deb73b866e6f6ab76145e6c869360ef472ae', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Jump Game - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('9c89899be7bb07735fba7d4a7e5791f9fc1d7acf5b66f21d7556e96172f0eb10', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Jump Game - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('39131bbf2e6d980634301a48729c27e06971aa0e7d58f01692a5d76bb565277d', E'import sys\n\n# Kth Smallest Element in a BST - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('6e5e796a54e6be6655212975799821d74e3649c8ea0cda6f433a7612df87efb5', E'import java.util.*;\n\n// Jump Game - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('22b4d96b10c629bff480961c1748edd13c2e6531b3bf6de9fb6581f149dcc066', E'import java.util.*;\n\n// Coin Change II - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('c4ff33c1aa764c25a3d8e63b029d9967f4b925c62a019f5ff59dbdd89197471b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('9b82075d68073a0650201666ee356190e942edfc65f1dd84d3af295a3f870147', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Edit Distance - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('64201cd221278f2ccabfe2796f70035218e8a02d34f850cb5ca1c3bcded8a3f7', E'import java.util.*;\n\n// Validate Binary Search Tree - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('b5f11c124f11d49cba6dcf00abb821c4053f301766063e93dbe7894b1325dd69', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Cost to Connect All Cities - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('a00bc0b0f87b44aaf79f8eaa5a238d28a80fc591882d535d4a84781753cc7c91', E'import sys\n\n# Minimum Window Substring - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('065af57ada3b133ed3cb1afbf27d56555b1e6ad0c75568c9295b7529a384f5a7', E'import java.util.*;\n\n// Alien Dictionary - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('dc8ce9116ae04551a828edb708fcc9a0f9dcadcdbe60bff8563c860842c6009e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Wildcard Matching - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('7a20788bd8abbee0ddefc5956358eae7934f04c8d36b6e8147615c68e9f95133', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('6d49b47a7c50552627fa00dfa8cfc0e01cbdd17314c22865bc9d9c4c3e1eb3de', E'import java.util.*;\n\n// Jump Game - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.printn(best);\n    }\n}\n'),
    ('2129a9dda636dd21ed407660eba49efc8ac3d6eec59c990b984fbcee7d92a6a4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n''\n    return 0;\n}\n'),
    ('bc166b86ce0c4ae84b1a488e3852e86604fb4cba8b172d20d4dedf99893637f9', E'import java.util.*;\n\n// Jump Game II - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('14896e02b6169639c7604a23aa15e72c9df32613f5cd831f2df372d4dbcaa951', E'import java.util.*;\n\n// Partition Equal Subset Sum - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt])\n    }\n}\n'),
