    ('cf7514dacc2cb5b7adbd7c79b619b74733019c65537d717fe4593e70ca996c41', E'import sys\n\n# Find Median from Data Stream - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt]\n\nsolve()\n'),
    ('2ec31a68121b7dc505c747d2177f0a58b34c8732749297fe75162f45c8f44c8c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('92e07c59641ae56de00d082a76c486708c1d28641defb8a6d3b8b574e2eba372', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('1bfadc7cb9ec5bdffc4b53a607c4741f7cb922c663991b02a09bfba48bdbb096', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Set Matrix Zeroes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('27ef0b709b12c845923e01615862bc8d4eef2a1f5aa294ab0f5dc8baf2a59232', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Shortest Path in Binary Matrix - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4fd93a0150a02ee87c68d04ad6edbc5de7e76498819600540ec9a4b56ed6cc59', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Generate Parentheses - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('315f56ee73d951833a39e01ed799f2191084d06d670de64460aabfbaa6397a31', E'import sys\n\n# Sliding Window Maximum - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1\n\nsolve()\n'),
    ('12892c7f5daa8225435d060c4ce316d308f59caeb6aeca7ec173eebbb2e4ec90', E'import java.util.*;\n\n// Symmetric Tree - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('60c34e5ac16bfc37c83e6dfdc62f984d8bd65e1b29109ecb0934135114633cc3', E'import sys\n\n# Generate Parentheses - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('d8e6605fe4452f6f1603a956dbb42ad48d6cabc4132f4c122ea1ba00092472e9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('766f722e016d372105ac90b3ea4b64a682429fd70dd2f9962af7655bea4dfe56', E'import java.util.*;\n\n// Contains Duplicate - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('54184441dd1750e9a68d058d1522376c309108aa0f8c17a5c6ef80864eb98c31', E'import java.util.*;\n\n// Pacific Atlantic Water Flow - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('34e9d7ccc40a9621ad475b5b7fd87137827c4baa51c994a1a2cb99ce059d944c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Target Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('ae38c838bf4a540ede3785b8beed0b0552af44827c3d771c6eed02b68b65a874', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Coin Change II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('92c3f6990d2c38690646df31d9a0d79b82bae654eacc1a88cde4142e97729284', E'import sys\n\n# Jump Game II - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('cd346e148fa5ecc3aa6d20516509db35aa322cf06f70c75bdb2919f332690d2c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ad06c3b848e3a944d97aa5daf452e0442941aa3b17dcbd47a1c4803975f007bb', E'import sys\n\n# Decode Ways - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('ef6113f68df85812532b5d9ff691374a43a36d32e0f773e6540ec6797850cda9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// LRU Cache - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('fbbd302823522dc5eae7e84bdb8f66e2ef0d3a03ffb5e93c6aa0142b0b8ab877', E'import java.util.*;\n\n// Subarray Sum Equals K - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('307eb5e779f2939558e4ce6e7ede44a6ca3ce81eb60b3394482688f264664662', E'import sys\n\n# Subarray Sum Equals K - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f5359a3b2c37a0a23818465ce63553dce0601753be60bf8e4920d327cfa34d28', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('8caf66aa13d6e19b1a8dd9722535c2f33243e32583ac5e21657f44985cae3507', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Connected Components in an Undirected Graph - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('76c717d1b19a492a5764447cd939e03e769f99b069bf83f4e183b09a6df3b3c5', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Number of Connected Components in an Undirected Graph - attempt 7 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *a = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &a[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += a[i];\n    }\n    printf("%lld\\n", ans);\n    free(a);\n    return 0;\n}\n'),
    ('8d7e0c80c9446de8c0ff33d305609afe0f7e1190cef71cf21d0fb12736aae31c', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Subarray Sum Equals K - attempt 4 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *nums = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('8b83ef64ee4fee203531b3ec0ecb1c0c3c2e8e5b2d07bbcb6b0fa0018af52638', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('d44714c260dd487cf7f1d88fc962f4b3b1ade3598553ea14e57203479d25fe10', E'import java.util.*;\n\n// Network Delay Time - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('92ffe2459b758473c46dfe90e3421dc8f2d3ce2f7501bfdc8e11165b24d5cb77', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Network Delay Time - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('198f2964c275bf2e4b745b6a55f2adcdca77b318eb97bb10ef8e7cbff9d3dafa', E'import sys\n\n# Contains Duplicate - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d6af1dabbddc1993f68e03823bff30d38bd182cdc1e1bd8c15a0f3f2b8e3de15', E'import java.util.*;\n\n// Critical Connections in a Network - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.printn(-1);\n    }\n}\n'),
    ('54ce2d53eeae06bf72412453cd1dc1c0b704913a184caf65a41140d64973bc62', E'import sys\n\n# Coin Change - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n]\n\nsolve()\n'),
    ('c1f3bd3afa625f8df08792ac1943e1c8d91f188feabd061f4ae11edbad4f5f85', E'import java.util.*;\n\n// Invert Binary Tree - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('f05e038f596119db56dd84b70dd38b5c06e1fd212c5525d751589bc591b7e342', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('50fbe3bb15f7902ac67a6f1295a0afed12cbc0e0a605f656636c9499fb422690', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Product Subarray - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('94451339674d9047307941f8c0fb538caf680dd25c868120101e6ed05a34f508', E'import java.util.*;\n\n// Two Sum - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('a87fc580afbf8c6e00c70f0598e1d4985eeed223f8c59955f9fa40b774de9417', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Critical Connections in a Network - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('99e5ee33b839000602b8d20d2706b158641f6af528364b1d2983ebbcf2f9c6f7', E'import java.util.*;\n\n// Majority Element - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('05154180819f81d43139e5b9c1454ce4ef97e81329c0082a4db4cc7afc427471', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Smallest Element in a BST - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('d733514204a67008b24fa0936bf8f1b5b58cfe725eb501b16aef4143555dd9dc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Jump Game II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('005a376f77f691e43bc06ab83bf2af0687c34390ecc5a8270cd03dc6021c32a2', E'import java.util.*;\n\n// Find Median from Data Stream - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('e915a25c4a574fe51ae52372e5d7f58593446a9c42dac9aaa462eff23aef9009', E'import sys\n\n# Cheapest Flights Within K Stops - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('1cf6c46c6cab578dd973c02382c6658062669e646a8a8b9f506203e7f5cadb14', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('011ca5d11f4e656a60e60fd32261e8f3fb2f9a22ef83fcf2a6b6c2b062416682', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('defb61df53148f1a94ce65c84753333390c6c08dba26e9ab3dcf4c8e77c462d4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Largest Element in an Array - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('acd19a2998693e6d0bc097709f4fd1b390633cd8214f2696de8b4e4f50990050', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Best Time to Buy and Sell Stock with Cooldown - attempt 3 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *data = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &data[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (data[i] > cur + data[i]) ? data[i] : cur + data[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(data);\n    return 0;\n}\n'),
    ('d31a8657cd4bf40f76df50397d36ef23127ea88a2d07108d5c70b65d39afa56a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Linked List - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('38d6d5a341215ae9c6ec8437b87d50051370c8bbf78b9621a3b1f326132e1acc', E'import sys\n\n# Kth Largest Element in an Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('a1ed0aabd3f78ba6cc5ce5d4f28864d0f24c3f7e517c248aa658bbd3808ad033', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock with Cooldown - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('cee54985791811d0168453e13a463b167119f936f736b6375fb49fcfd014ee39', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('9c4713d71f76a228fd3082f41fc33ad68cba395866bebbfc4f6c22aa218f2b18', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5ac9843245a0d7ab89fa2f1f99f9aeeb28dcefecb5b14663842c5743fe34276a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock with Cooldown - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('020033ddf4aa85102d2cd15325d0fa37b098774edb5bd65e7a792c1fd9a9ddb7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('9139e379466b0a91daaf9f756a192efb77f68a0d17666d3445a355c727e16de2', E'import sys\n\n# Partition Equal Subset Sum - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('21c8c16b3b279d16b226faf07b8f6ac80a562b29ee1da4f7cd159d2362faa910', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('6c21f841b975f9bb67d6177b72978dd2e12b2512db981a7e215cefbf56fec86d', E'import sys\n\n# Rotting Oranges - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('a334b3f518282e4d39224fe6f064642e23113f947839d1eb2b8f331abdaf5bb2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('a0fa8401cb7924828f99ba4ed43b181fe9bca1deaeff7a3a02cfcaa626af06ae', E'import sys\n\n# Same Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('152a8e2631819bad4388573836046abce603d5e51d72e07d27c142391991380f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('1d93131e439e11360df5b8301f5594cd46fa35d767108d2778a04e17b86d1ddb', E'import sys\n\n# Binary Tree Level Order Traversal - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('9e2f05209217f2cdd1a97707d13decda441a9eb4291beead0e2666dae34a103d', E'import java.util.*;\n\n// Minimum Path Sum - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('c85ef90f29b424c3690f8a08644aec06cf53eff91e5c6381f55605ac9b9deee3', E'import sys\n\n# Container With Most Water - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('222f886f15ea969d4387179a8f5a92292662af34a89fc5e920dd7a618e05d742', E'import sys\n\n# Cheapest Flights Within K Stops - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('103f05ebd5c59b875c08baa00e560d6725e68fd919cdea5d508272a092b72999', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Network Delay Time - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('afd64cbfeaa6cc03622c4eeb4d1f2417767ee1a22c3626d4036b09382b66b6a4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Design Hit Counter - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('fb57eaf0d4b055f07636ee51a6c16ded15dab07b0773098087940a671caeff35', E'import java.util.*;\n\n// Shortest Path in Binary Matrix - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('faacdad10e9bfbda266fde13ad7744880e9bc601aafe719c642dc5335de2104f', E'import sys\n\n# Generate Parentheses - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('c3ee3c9c981e64e75385a4a5b00c022f658a8d423d3195b4dc60ad7027f46ae1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('986ec7978b080cb43de9e7099087888cb70340be0f430dc25bd1902ba8464446', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('679d63a3acb6329909b05a533b89105047faaf5b99f4e35185eea6abbd5fd5c5', E'import sys\n\n# Triangle - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('b53edc653c5f5abbb98b8781a3ec4b8b6ca9c68541c5a1b50095a2474a69392a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Target Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('bf4f7441701d22861462a902c52bdec6e5c0a49ab48c02eac3f44e0ba35746a5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('46c9f3da981041d3bdb4bad5d70029a26659d618fb64bbd68a6b9f4534db8914', E'import java.util.*;\n\n// Implement Queue using Stacks - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('eb4b06b2c50f13c576390df9f54e0dba620d6f224db5b84d59ac5290e428d66d', E'import java.util.*;\n\n// Sliding Window Maximum - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('80b4cf35f0e3049d0e7808ca8ec285da057e965ccb26534c56369f19d2e016a5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('289c5a39c69330f8c711ceec5463e8963b51400424bdd4bce5ffc0eecdb29fb4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Unique Paths - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('54eb7bf19a5424c77f6df8dd764da6f12443890429775f911bcd4899b988c98a', E'import java.util.*;\n\n// Number of Islands - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('8dd263bc8a22a35033fa1f9278ee1c733210273c652bdd7c1bb51971af69c242', E'import sys\n\n# Valid Anagram - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('3e7ac5aa20dfc72b9231b8e59200a0467d58cce62fac8191d2509cbc895429bc', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Coin Change - attempt 3 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *arr = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('a777a3b5acba2e2ef4f2c996cc31c89763941b3b4a1611f0d52d8f15f0836f49', E'import sys\n\n# Triangle - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d50311f7b6e1f2d51fd965c1fe1bf423afc28e88490997d92a82095c903b5842', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('57aa851b5c6c75fa6c153c4f601e22e1dcb1884dc33228109fb8ba7c88d6472a', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Evaluate Reverse Polish Notation - attempt 7 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *data = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('9a5a7dee093072f96dadb8640fb2433d09059c769019e74f8d3af3c2c2270f4f', E'import java.util.*;\n\n// Evaluate Reverse Polish Notation - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('38cef30d8d65226f52ee3f55f3af40f0055b3a3e9048333cb4f2d8cf919ff440', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Triangle - attempt 1 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *arr = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n        ans += arr[i];\n    }\n    printf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n'),
    ('c92b564f236f43f3d549968df42a6776e112ef0003c99d9292230c4197852980', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 8\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('7cdce6c7ed0a1fa9b43e3a71d5cd8926bb24b7c2fb7b0a25964329c280e5ccff', E'import sys\n\n# Evaluate Reverse Polish Notation - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('3a4cd2c959e2e00c5a49c8cb6da5a0afd700953c7a097b4abe77ed80c4a591b6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('596be660caceed39d6397e852f6c44af7a377f8abbb490217d0ce5da3c20ebfe', E'import sys\n\n# First Missing Positive - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('8251c9d7b0fe0963542dc85f8376e07f1a9fc2b7bcc994f34b53ddaef0b58c87', E'import java.util.*;\n\n// Burst Balloons - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('dd07d3cd10de736fba8cc1f16b00b5e98bdaef1b9371d56bbe98266d7291c7eb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Product Subarray - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('71379e4c04e3c54cc24a089a5c662da5a55748315ab6cc6b2e89c50dee0ec9ea', E'import java.util.*;\n\n// String to Integer (atoi) - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('d5da9649913216af218682a2c90e18e7b99c65189eb9eddfcaa9b6e0d3876985', E'import sys\n\n# Kth Smallest Element in a BST - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('6408fccd00cf5c5cd4892ccac175d50b2221c1ba48f94ddafd64f3d036c96173', E'import sys\n\n# Reverse Linked List - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('4b8537fcd9ff8672b7020e9b056ca48c6bec440bf7e142cb996aacb4cc7477ab', E'import sys\n\n# Subarray Sum Equals K - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('1b7ea6e5bdd5b39aec35fb7c9b6389129b80fb4d37258b6d4f6cb6cec8af4b18', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Cost to Connect All Cities - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('91b65744b392d84f47d878c871493d9051e80648307ba445e90aa6b79cf15eec', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Linked List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('e5318fbe7552d8cc2af800048c083ff22265312da10baea36f55b47a23909777', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Unique Paths - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('13f67972b7ab6010c140651201da6717c10097fe7b10f10312e4c5bcec1468cf', E'import sys\n\n# Pacific Atlantic Water Flow - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('8a8a062bd9226d54c098942bbe30f4af8cf304a1d705ff3eb02fe5c4fa8c87b1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Coin Change - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5f4dfcb0883f110f82c30c34576ef2bbad363c03afaa81a9c96e560b39dab3e2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n''\n    return 0;\n}\n'),
    ('1854e6d2f636380655838cccfc6fcc748ff1f2eb501fcdeb5c304c19d7865d68', E'import java.util.*;\n\n// Distinct Subsequences - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.printn(best);\n    }\n}\n'),
    ('9d62cef79d44ab3e8c208f54da9a12a8b0dbae77e19a81b2d8ecf81e41b709d8', E'import java.util.*;\n\n// Count and Say - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('e29596154ee1f9a58779603d5855f2d3a716dc9921a29373d90a3f32468e8aa5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Ladder - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('36f61bacae5271a8cee0ab214a88507021148224d85929d6148c8913c93cdd85', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// First Missing Positive - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n''\n    return 0;\n}\n'),
    ('23935051e33aee89cb7e87cefb610ffe145f7f3c2ac94dd9b5812e3a1d9e2bad', E'import java.util.*;\n\n// Distinct Subsequences - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('bf800165b0b366aa93ad67c6efb8d010786fa67d92fa2fdcd09c06d6c7ce7ad8', E'import java.util.*;\n\n// Minimum Path Sum - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('512ef74cebf865b076d69d3e515606d6e75508e91c98d593ad14df3c855fa84d', E'import java.util.*;\n\n// Minimum Path Sum - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('52a6ad8c9bf91cfb8f8a1f60a70e4e1cc39388d2024dbf260272a2ec61d1a656', E'import java.util.*;\n\n// Minimum Path Sum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('ad40c11ae8033e5c35791bb4877a935ec5b8e14c99e117867b775021e758345d', E'import sys\n\n# Interleaving String - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('bd627c8d8b9fe123152b9134fb5a4501c694aeb9f77d5cdf510c41c8a399cef9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('8ca74b362eddef95badaebf5bbe0db745f51679a091c7e051bb3d52eca3d7eae', E'import java.util.*;\n\n// Best Time to Buy and Sell Stock with Cooldown - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('016db09f10791a4179df2f2aa41f6d2f509fc8ce52adb74c2aa0e98cbc6b2423', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('99c4062ac22886747f26e0bdb5fbf32a37461678f42439413d6562a4ef963a2f', E'import sys\n\n# Spiral Matrix - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('c029e1f9970d0f78289653fbc31e694c6b05635bb3a5de0c36d7d27c2e4deaa5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('de0a23f92b13cfde94ea8efed1e885ea80603dcf3275d11dbd323ab1201f7f08', E'import java.util.*;\n\n// Palindromic Substrings - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('37e590cc7ecead5359bf1f4cf2422cd6c6db2b3af97c87718ba7515d2e00e22b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Triangle - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('e083fc6cfb40db0d3361c8bc933ebac6ada9f43e2473947a64460483c6ff7b54', E'import sys\n\n# Majority Element - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('14dcdd1287366ccd49f42c8e25dba245d90577a9aec6d9af1b65efa809ff37c4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('4b5b9b0b9f17914a3845c9cce6e3847d96ed1f0589ac66086f029dff471454d2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('3518195d8026fb8f4969ebcc23d2668c262aece65c553fcf3c5e38df266b8084', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('b0f2e0234de3e4225b67e76c0bc54976facc4fe39b428cf8bf364de8c898b9d8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('83c88122063761d88bd407114213e15516598946dc0bc73c75808b0eca690235', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('2ff00017590388adf716b7940384a209824f6918fb9c9459c8cc2254ee13f619', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Target Sum - attempt 2 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *arr = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('ed96739e1885b13b59608b5a97d5e1fa8cd5aebb137905d01207153179944d23', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('1f869b3131daca7fa0a9902051b9977224b4c823ab1ec6871e442097cada0bd1', E'import sys\n\n# House Robber II - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('abd83fac113bd4aa1d1966de443058deb6fc25ab0b033bf017eb53b8cdf41132', E'import sys\n\n# Surrounded Regions - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('7fedccf6fc0a1ea6579a187988fceee4b54b3391a47d2f42c38828cfeaebe5c6', E'import java.util.*;\n\n// Search in Rotated Sorted Array - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('f7de60d5b64f001e35e22e2a52c703ea498ba95688f63607b661f93d10a3d799', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('f913d30449a4dac8ef65bae52b674fc255171dc479df2cafdfda06708e252fd7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Swim in Rising Water - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('4a0c130abd617bd43133d4e59f50ff9e4fa79d078c458291b1f234481629f934', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Wildcard Matching - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('96839301db8253c625e085a170b09e1078f16e9149a652013cc10d7ff7c60982', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reconstruct Itinerary - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('b545b7a5fb94c2d5120428968ded2afbdf1b02228815ca0138294be179fdabac', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('931d25866fd71783369d9848cde93d7f33aa70713e4307a4b2f80aa530692074', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('99d7b6bce849bdb5be7d7fa842ac5b507159c23b3d17ea5f8f7fc1aba090e98e', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Longest Palindromic Subsequence - attempt 7 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *nums = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('0ccdbb9d94f8e6fb36e6bd1ba2472cef546f8fb79f06e05d939d83f78f9d617e', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Surrounded Regions - attempt 2 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *arr = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += arr[i];\n    }\n    printf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n'),
    ('c06447836031f6a78927f25e19f4916b8ced45c7f08afbd3bdcce4838500497f', E'import sys\n\n# Surrounded Regions - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('24f2135e619f4685a9fb61b98b52bb8b7369ffd9ebe11ee13b1874dbe1c2be68', E'import sys\n\n# Design Hit Counter - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('20bc2b14105341926a4c921162b99b7089a3fd83c29d9c4945663a0f5d765198', E'import sys\n\n# Regular Expression Matching - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('c2a0ea1df33fe9f96046cec829cdb0bed91d5c4df07ad98a2478358088f36a04', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('6fe23c0c5c828a77f57b8c0a678f36512b7474d0909032034a3f050fd3c164c2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('75f5b6e0c5be867326b1ea9857191f755b55b2e2dfd50b43fa40e23b217a483a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Two Sum - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('f9f7b7b1a38d7680d091b4beaf430583cb92515e0f3bd57cb1ed67ccaf4f1cff', E'import sys\n\n# Partition Equal Subset Sum - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('db6db1a68547d5988ef0be9d6428b34ed523f83e7fb83dafd3a89d81312d5da2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge k Sorted Lists - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('841305357dbd814de159669797819034f7f8af6388a6e32365d1ec3a3bedc67f', E'import java.util.*;\n\n// Triangle - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('76714c2771ac914162410dca033b53dbbfeea6dee86ef2aeb022e7a98f487c1d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Trapping Rain Water - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8e8d791556e4bc00865fe4c370c6c63d21121b340a5283039d484a987af363b7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Regular Expression Matching - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n''\n    return 0;\n}\n'),
    ('9b0ac248015276f5355a40db8852dd9a7147f1a47d8271cafd95115b141a1c6e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Russian Doll Envelopes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('6277cd33e4a775c088163458601c60c45be79da4ae0edbb5b995058ba8dd2112', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('06ebb9c5c23a212912b2ccbf2a24b0ac44d7a91deba396a734b3ae17b2cfc7c1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('42e75caca825044ebc673486a5fa6f3b14a3aaf0e8cb6b284c7a52347e7781a3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4e99346e60a7bb8acdfd88a054b0d3f535c3843ec1ea6b5334406f237fecc7b4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e593185e1cd2e1cd2acfbe788f61bd3bebb6cd534338386d85d5649c6d701e6f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('29afb60d5006f7be9d8fae0e7633cf4ce6acf34bc21f033f8818a02237b5f22f', E'import sys\n\n# Maximal Square - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt]\n\nsolve()\n'),
    ('42adfba4654bd3ad52a6c3656cdb6aae54c92e37ff33b9017b7c68978bee0447', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('650e1b00383ad880405d966bcaf84966ca4610a750cb12c49bd546504a371278', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('fc17af3c93ab567a24edda0bfd572425817db8c65db2398f66213414bded2708', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Partitioning II - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('55e970ef630f14ba562508a94081b37662e7fa7461fd830b40b36ec60a1a21a0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('83c3f4437dc600a29f0e08cd2b67265e11bac39a5af73fde38314e751574aad7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a6a2c09af16a1d4a740fba0fa6b0ca3ae420e09d4557f87be5822a8d3123382c', E'import java.util.*;\n\n// Maximal Square - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('83326719836d7add0eb9bb752a6330e85eabc0670be615db34964c19c69a64ae', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('2aa500d7d21cdd918aef280c6e835eaaa92d51de96d5f727a33c3fc22bd0af8a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Connected Components in an Undirected Graph - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5ffda49f72a2117e453153d90bdb409a86d9a7442135bed8a46032a576c82200', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Set Matrix Zeroes - attempt 3 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *v = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('969de5766940b97af3950cf5283112ba7c6bbf338ffe808fb5d1193402e0c630', E'import java.util.*;\n\n// Implement Trie (Prefix Tree) - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('a29ffe0b17b8eb4ab8215272f203483beb95b6990f7ce06b84a287c8a7692576', E'import java.util.*;\n\n// Binary Tree Maximum Path Sum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[sz]);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('ded93436994104b4652e2027b9df6f98c9c386cd9d718afac870eeefed5a8517', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('4234a9427e828a970b0e82b2def734dc37f8150bd0f521e8dad93bfd467b7521', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f3e61d1dfc3bf8fdcc691dc31d86fb192f10815d30cd95f106259afae403409f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('04626100ed37cea76bf67febccf769ce7090dcb573676db0588d4a2e6039c61b', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Minimum Path Sum - attempt 6 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *nums = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('e168b4901e007d510f80a807ea4661ee243a62aea3beefc895d45cf2d75e5af0', E'import java.util.*;\n\n// Minimum Path Sum - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[N]);\n    }\n}\n'),
    ('4de9c1ef3b39c233c3678484d1c71080b3d1ab3ca1c7a3c405dc418dd6e09953', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Image - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('fa043c0789b39970b9d1952c6dbdd03b2f245c3bd15ee2d86fe638e49e5027e0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('c89d990febbd5f74b249a457ba99e5ea10d13ae2ecc7e87afe59da139512eb64', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximal Square - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('081a09631eb2870355c6d264a3a01fbbfed27a69ca1894b71d0a8952099990c2', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Longest Palindromic Subsequence - attempt 1 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *nums = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('e2decd9f800d08e7c26a3b51a300139d7f7e6b1398961a8753234d8ab164c320', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Russian Doll Envelopes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('c793d08dabbdb793fd1a79086b78eda6cee1d92375ada721285977d098eb174a', E'import sys\n\n# Longest Palindromic Subsequence - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('209341c4e0feedbe15127a9b82438042da274a9779945080aa8dfdd978bb39aa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5c5a5adefcd975e86d712051ef15de10a8d54b60145836005b3195c67316c8f6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Russian Doll Envelopes - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('cb8aaf4f06ee7f474fa095c9c65ac36bd9a8db0918e6821d4bb546ef2f8a4aac', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Subsequence - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f68fece0cede1e2376e1346d7cda367fc6949253f16043fe7dc4cbf3214ff842', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Subsequence - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('08fcaf0186d9917ec07a5e4326a7e7066e96eea2357c700cc4009b18f2da14ec', E'import sys\n\n# Maximal Square - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('87726ecf546d343fa7be47c296d64a72d5143cacab469fae1c6b2d545eff2f02', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('a346c109ed73cf22b84cb17f6525fec01a7b7e9070a0f278236f8fb776d5e81d', E'import java.util.*;\n\n// Largest Rectangle in Histogram - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('dc53b5fd8e1df7877e092055a819d39bfec62892596a637dafb18ecf72022b92', E'import java.util.*;\n\n// Number of Islands - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('5bd25d4370638ca62046322f55c4b6a7b14d152db791c20f854958e0e3232de3', E'import java.util.*;\n\n// Rotting Oranges - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best)\n    }\n}\n'),
    ('776f4c96d80bd08d8b5a414db3764b06e77d4a50dbd4839b09e5b0231b9b6ca8', E'import java.util.*;\n\n// Palindromic Substrings - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('ba72108a42aaf3e1c71fcb963f0ff51aa43e7cf598d620645a4e01cab2615c54', E'import java.util.*;\n\n// Reconstruct Itinerary - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('0b185f199583667fd9d9465ab7e8956d6ef75d9ce910ba300fea01745e54b5b6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Coin Change II - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('78b9fe5b2be88301ee05a976feb02105cc89bcaf4ea1dc69686d5ad5fbcc434d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('d83f595860c2dacc770d2a605b771712c708dd71ef3a75b08fb4ccf72479009b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('a0069f088208b4d2b553ccd02aa19d82d8ea0e7021bb98efd56b0d26064e9ba9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d46a569fbf55c3a79f0eb88a50695ab93abc3928c8dc537f97bb0843c727506f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Target Sum - attempt 6 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *arr = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('b0437320ec77949ac38486e9dff09b42c7b3e66a839b22f17fbcd8a78112a4f0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Partitioning II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5f0791138e85f224ea8b7d5a470f9f7762b8ea4c5542888fa01af0406f5a91b7', E'import sys\n\n# Min Stack - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('5a9ead37b0203f48aebad6a248bc03d7f5e71efe2c3d7dc7512a8d993ffd92ac', E'import sys\n\n# Alien Dictionary - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('64dbbb6355d24e6cb8fd4bd134ce7e8959b422e475387af42f12714d624374ea', E'import sys\n\n# Partition Equal Subset Sum - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('64419e070b186b9093b07614a0c65c63e3791f905e40f41c08fcf1f9a8bff212', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('be6317194823751642e3b056e9543d512762e6db3c33b7bbf8bcb7c460e2e3b5', E'import sys\n\n# Generate Parentheses - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d96780f7cf5f3fde974532e31d4e551d3e42b9acb1c6e0c8234e2cd3101181c7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search Insert Position - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a17868a00427280338ad54c28007de46ac896ff3152007b2527b88e9a48daa78', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Search - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('fc0761fb004349a6de8b674f76eeeadee44f07e2ce3c842ec088709dbdb2a30b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b28e94e39c4527f0d665609220bc958c1b1cf4fd38df4c2d5fe5fbe68a3f3847', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('013b81b9a4034313096ca0cae94bab70ce0ff184d204037e2361eb0bd13fa44f', E'import java.util.*;\n\n// Search in Rotated Sorted Array - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('cc550bf213aa60f246a94e9fa1325f764a05bf45439cd5b6415fb43e76ae0392', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Nth Node From End of List - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('57851e17314c8c0d5b6b8f1e5718c3b3dac54d7b8863eef09da72b2088dce1d5', E'import java.util.*;\n\n// Number of Islands - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('6df3cd826203546f0557a134b22f5086b39cfbea1f97cb76050ebd69d9540e8b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Connected Components in an Undirected Graph - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('eca1423fe74161731622723a4f77732c27eacf9add6b4af4e06d6ae25a86e595', E'import java.util.*;\n\n// Unique Paths - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('6b97eb405c0bd94b5297aa2cd4efc6c467e7336118d047d8c75c958d0ab000cc', E'import java.util.*;\n\n// Egg Dropping Puzzle - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('812f53ca6e04b74f2765fd5c0d46c372b3b10c1092d0e476ac6337519868c485', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('9082737a083796eb714a679019fedbba2f1bf9b690082874b11e8a3b9358965c', E'import java.util.*;\n\n// Maximal Square - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('4afa5e99ce174c661b30992722092e2b148d17774199363de7ce92a2e227ba0e', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('0f04f3151032a2d430ff6e0f404c618cb60b9939fafec4d7b37228aa357b7a11', E'import sys\n\n# Longest Increasing Subsequence - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    import heapq\n    k = max(1, len // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('2ac62797e2d6af18e9ae430b1138552d0a98af19191e139a9b1cb5423c960b06', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Subarray - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('6d22f1ad79c3414bf7a2229ec364f0c20b9e02ae7298fbbd7efad191c0901acc', E'import java.util.*;\n\n// Balanced Binary Tree - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('5a3cb3df1ba35acdab7f3245d357c857edf0561e0173a036668f939b242bb2ac', E'import java.util.*;\n\n// Binary Search - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('46f4ea0996aa3d755052115d6c9c40b0b0eff7e0946aad019a1272378e62c71f', E'import sys\n\n# Koko Eating Bananas - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d3e4030aa7b1f750bbc15b24c9a33de959e8545d76541b0a413d807421efd2ad', E'import java.util.*;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] nums = new long[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('2cf3a616c78eb17e9f792c702fb84d70281f827b2b1da79aaefe3df85446207e', E'import sys\n\n# Binary Search - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('e13855a981f4fde30b86b2c21e0154778e8af909cc298998530f096531e1e266', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n''\n    return 0;\n}\n'),
    ('92ff4fa3b91cf80c74c0a1efe762f5be0dd5adef8f670747ae831b2386d15d73', E'import java.util.*;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('e2a287bb36e63fe732ab69f557b19f967390e3d41df0ffe2dee3e203734f00c2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3ddad2af8e99b373eb3b377f6638e51e7e953fc027893949140cfe6a8ef8d689', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4ad5f06f6b834910c8b3ed4b75963a2c6423f3807d4a61f46bbd8d1ef59e0b79', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5cbd7743b32788825da7f1700c2280ad7b36c256de201775796f80354eef6bfa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Cost to Connect All Cities - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('21397e8c14e81299adcb5b318eb165510118aa3e1e0870abd8b68eea8859610c', E'import java.util.*;\n\n// Evaluate Reverse Polish Notation - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('842ca3941b6ecea17f03da9261d4a0aed7d15357eb402bc287f0441304e1be25', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('8934b2188a9b05f2e5377d0badb770536341bf29c7947b931b93fb2d9305d650', E'import java.util.*;\n\n// Jump Game II - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.printn(-1);\n    }\n}\n'),
    ('48868df1975aff4e99b63f425871350e6e47329c7d21b17f2f2f02e83436cce6', E'import sys\n\n# Regular Expression Matching - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('5f5ee94ea6d706eb3d055cc40be8842cbb704b4533d88fe98170c1263e9b37ed', E'import sys\n\n# Same Tree - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('35e6534ea0fa24a027aebe16fb84f719abf75d2ec5fd546baca4299b40c75c96', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Diameter of Binary Tree - attempt 3 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *arr = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < cnt; i++) {\n        ans += arr[i];\n    }\n    printf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n'),
    ('bb3d57458578edf34cbd56136419d3f2418aee308a9c7c0b53bd4cb7d7d63f4e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('e7fbada1d6d91dd8cbb4c5383423cae74d07efafa682ae6842a55f6214611862', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('f4a1ccd511644e38f9f601a54d86e9b71b0b9cbfa7181fac92c0dd363bf1fdb6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Swim in Rising Water - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('d0742d9087469c8d04a26bed6629fd5f313093622be1f0e93b1cde80330ffd82', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Graph Valid Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('977e398f69c0b95cc83615059949bf51bc66f814d423dff95ae89040473e51eb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('c698a1e3a0c1890f25e9401f9af6f0f44e1b7ebd3c47e076d8c0c5e57c26b630', E'import java.util.*;\n\n// Symmetric Tree - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('cda2a01d958dcbf40e49659661fbf1c0141425b23dca61dd29f78e0c7e325260', E'import java.util.*;\n\n// Search Insert Position - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('ace03ad24d0b9eaeb04e30b8a8fe306787571f12d7004edc6bf2fbd4018fb2ef', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Median of Two Sorted Arrays - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('c08696956fd3e4dc83ff5c0c32ede0ef0b1c424a9a034b256b56dfdd82ebcb29', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search Insert Position - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('46bdb4f6bc6d7ba4a97224e8dbfd53ded8f1797afea985c643f2ad8092a8d510', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Median of Two Sorted Arrays - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('4ab522221110cf85ddae110b5390584b2743e74d5baaf662089e5f22a3f54b51', E'import java.util.*;\n\n// Search Insert Position - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('37ddd6926083293043f8fae0e80b2d39f99cd1580c3ce21c1c4f30f48db55d27', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Unique Paths - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('21f08a20dbc8f1a5bb389a4af270dc48a09e6f571a415360afd6830f33381406', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subarray Sum Equals K - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('742f8faa7e7fedc345c6b5893a0c43d5437ac490856acc634c7591b90eddc349', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Rotting Oranges - attempt 4 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    prnitf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('520bc8e803b4d30f2f5052d77c1427cb22d00e34e841ef0a7a3e82d02fb02e0d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9a2ec3d066e6510fc0a50f24eb4c746e4a06b2c644b233ab29dfbd5b3322a681', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Koko Eating Bananas - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('eaf55683005f62606cdcb1b7751ee8616191a81daed44bf693348acafced5bcc', E'import java.util.*;\n\n// Add Binary - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('5c900a9778943f23e0f761c1cbd6b2f2162dbdbec86ad661858bf76eb91faa27', E'import java.util.*;\n\n// Spiral Matrix - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('4812b73a9fc20a19c0de5fc572b004abca79e60cd12355e565ee83a8846c8f6f', E'import sys\n\n# Diameter of Binary Tree - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('7315005d53e386ad1f778cc87c60359b2d593ed5c924c77fe5b85f513c8e313f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Critical Connections in a Network - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('c064f092a34785b09e5990357c07827e6b782034442d1a391989031a2c9c0147', E'import java.util.*;\n\n// Cheapest Flights Within K Stops - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('c5cf079df11b76baace7ffe3fae7b04875d3164c1edd6d87d402a7c1aaadc5ea', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Substring - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('dceb57497152b74d22785a5a2295cb7254062fe661d481a4f976eb6039c8d043', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pow(x, n) - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('37041a59fe6c29ff086596e860fd84aee68f288931a68f74a8b15ada39d5ceb6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('dee1d35f9511d61e3443cd7439e6571444ce58df5abcd6799dc9a8d68d2735c5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Three Sum - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2b18dde5862ea19699597c00cadb276868325902189be4c82315a2c4fb22e29c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('db6a9d405f63f32e32887e52c3a4d8805648b152f5a41f77de8e19565cf3736d', E'import java.util.*;\n\n// Longest Repeating Character Replacement - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('9c5756bb3f268cebdc31808d2eacc7705c0db19a1e2ee6e09a6c24827ee850fa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('57a660a82d7a3580eb2c86977ca96f1a561035bc90602b9a763ec27fec69473c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Minimum in Rotated Sorted Array - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('953c02098f4103c9ff94c50fda70ea7c4c9b6ed5f5abac82165779397ed3703d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// String to Integer (atoi) - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('d2fcf3d42d1ba112e0a746da23406b8f19cd696d8833174e55c170ad46973928', E'import sys\n\n# Median of Two Sorted Arrays - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('f9aa6266d046a6df64e2bbd1cdfabc04e63a6cfcc50d10f755b78089fc308dda', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Median of Two Sorted Arrays - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('90bc9c5777e4e037e10bca786b28edab96c456dbbe3620eeac770eabe11af8a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('40d6903eb08a5498dea0b1a183551d7b56e5216fd1c413b0605fae04e8ddf954', E'import sys\n\n# Triangle - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('0489d0edb6b07a0a03ed0d8c1a37465881b1977a039e9a2304b3bf6e61ad5624', E'import sys\n\n# Sqrt(x) - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('429cb8c4e4be92d657fe85472b48052088d98c49868853fdb144e736859ed572', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Sqrt(x) - attempt 2 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *a = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('d12eed8fa6f427c3f714fe48f7b69d6f09d6d1395eedf203d1d75014ed108b75', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('d35f15717abf19285be7d035256b791b7a231eb74d5a6c3b574030e7eb857108', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Jump Game II - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('2dae1767bda527bbb17d218fa095d7124899ae0c38be279f2ecf33b62c436851', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Ladder - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('a1cc7b7796dadad8bd87f6e249c592d67cd02749414b804a87b3fbc4ed18371e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('5d6f3f6586937f8f5223fdb8d595632881bd0a2a7f1081cfe18da04bc6225d6a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Largest Rectangle in Histogram - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('2c5a70d158425fde7f38cceffacd221f785bd1af9d1d4c004436fdfb97f793a5', E'import sys\n\n# Shortest Path in Binary Matrix - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('5ffef8f9506f5ae636fc982debdc2094e9a3835068f02e78bf600b423e6ae2c6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindromic Substrings - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('24f11a8700fb5441331b0accba4e381964523610b48590e1781d92b2c8297e0a', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Swim in Rising Water - attempt 4 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *v = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('6c6bf0ef647f7b39c4f1d8da23cea767070933233cac3c6ab180f23ae9fa334b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('470786975b13a9ce4a21761b850761cc1b1682492c8af790db4a2352792eab0a', E'import java.util.*;\n\n// Pow(x, n) - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('3561f63e8bf18fb9e1c15e3c7656a8d1b6dc7292b7f5fa624fcb9bc7e19e883d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b964055d7fd97e69e1e428333a667caee3da0e5fef5deea5f54ab3481611632e', E'import sys\n\n# Pow(x, n) - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('1cec79b1b1eceb30a575d5d53a888c98c7ee65e994072a086d4d53c84c029c65', E'import sys\n\n# Best Time to Buy and Sell Stock with Cooldown - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('64341931bec933bde5e9c275354651cdaac9105749a093c3cef20d437b0d090d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('32784d50e2192a2af5f9545d8f43b6fbdca17aacc113b1186ecfc3e8ee6c4cd7', E'import java.util.*;\n\n// Best Time to Buy and Sell Stock with Cooldown - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('a227b43c9035a5ff18a5500852c5862e48f116da486b3201690e847fe5814993', E'import java.util.*;\n\n// Koko Eating Bananas - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('66cf837c1eb15992926828a37de73e13be805438406ba0ba03cb5ccbcccea2d1', E'import sys\n\n# Count Primes - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('a8dc8e4e5fa48edbb6684ecc5567823ccc31136f08f764fd1f9c5f4fc6e8de7e', E'import sys\n\n# Best Time to Buy and Sell Stock with Cooldown - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('4b1c21454aa09cd2d492d89b4a66b03bd949670fe5d1e67b58678276b5a18ae9', E'import java.util.*;\n\n// Sqrt(x) - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[sz]);\n    }\n}\n'),
    ('36a1add6ceff87023bd3d9dbbf386976f50cd79972f2c05b0b82b8c10c07284c', E'import sys\n\n# Count Primes - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('cb90c039740b0253bfef8c8992bff02717cf9411af321a878fcfd6ff78bc143f', E'import sys\n\n# Best Time to Buy and Sell Stock with Cooldown - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('5218d74fd49a8f90d3ccb26ad90942872fbb79e1cb46bebdcb01829584d1b8d4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('896b6676172dbb16881390b63a2a63ae81b8353cb5fb50fd8c7286b48d14bc8a', E'import java.util.*;\n\n// Climbing Stairs - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('5f37d57cdd40c429c78ab827ef2259009424d5e06c4f62ebe1534a0440ee7686', E'import sys\n\n# Find Minimum in Rotated Sorted Array - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('b692f9ff476c37a84b2b7ff9cc57240f8adae077c56f972bd6215eec79788ad4', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('379407e12feee3ffbd6d4b911769a9ade82dfb7a81587183d99b27657769a090', E'import sys\n\n# Largest Rectangle in Histogram - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('9b615f88c362d42fc93609a7c2bc5eff71c7aac28728855803aba1aee51aa4a0', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Longest Consecutive Sequence - attempt 4 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *data = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('4b849b1384d1f9f1b83ec264275dbabb29741573dbc480e8ddf4dc82e9c87042', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Validate Binary Search Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('638c78e23fba4d998d51aa2df6a0cd31ed5f18fe2c4c8b0ef62831b2bd823a60', E'import sys\n\n# Count and Say - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('1ea93ba17bdce144ba334aec8f9cb00fd6c62bf7bdc53de8069222fcb7789f81', E'import java.util.*;\n\n// Egg Dropping Puzzle - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('da5f29b2494655a9bc99893a9cc0519f480d7df11ceddd9e2645751bc1213321', E'import sys\n\n# Count Primes - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n'),
    ('7e4f56a9b494ef601e3bc225e8cc44fe8f2c940008220d89ad8d9ebebefe5064', E'import sys\n\n# Add Binary - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('af22afaef03d0f8811668e0f31bd47d7fe5a385a03643e3d4b4c28a0a18bf9f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('72e354bb24cbab929e486740602be695fa7758c2b6a589f0a4d9550a8e7e9bec', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('97ab688a0b8d9fd900e4a2fe5b97aa288cf81c813563c541332e30b418886e66', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Parentheses - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('697e95313aa4e1cef0a4c24c3d3ba5d44e23eca644a5222017f4462a4d438fb2', E'import sys\n\n# Triangle - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('775f5f730e6398ef52600894cc4d7bd72ea5c07ff7e4a763f01ae6d37c797efd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('351705e99e1e39c9d99efa74d5560354e0d2fd4d82a04e29464f86351109df95', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('932bc84d89e3f349f9a3a61842c5b427787ef59ba04389f9c3e8ad8cca691390', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a762266c8e860bb8dbd5b12e3cf5ced8bbbe43c6e4e68ef5e78a7b2c827aa362', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Cheapest Flights Within K Stops - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('d1f05479046f967ce4a6fcf2b9a51e45294cc4b8b723432c3ca1fdd7a15ff910', E'import sys\n\n# Regular Expression Matching - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('eb01cdc3319f4a67a8072fc5205d9b0dfd592fbd159cfe5b93be5a8f8873189e', E'import java.util.*;\n\n// Is Graph Bipartite - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('dbd91b2ddbf03a8f9a911c787cd47738bdeac15205b02547d064fd47c757daa2', E'import sys\n\n# Valid Parentheses - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('8a66435926667cebc71b90fecb5ce983e470ba1592ed9251c7698c8a1b1a5467', E'import sys\n\n# Edit Distance - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('037124e042022398a080493476c39441c9de99ff290be0dfb4f604fe95eec38f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pow(x, n) - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('20b6b69f8d7b861d4967348f7eb3d19c10114642e9c33bfc63b8039c9c055346', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pow(x, n) - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('a211a1c24f14c879ca55d54b94487103b65ba1dd7efb5fe4452c2e6c4d168ac7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pow(x, n) - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('974d18ffb4d715180e4884cb713c00054bac3fd1864b083538cdb972be3047f8', E'import java.util.*;\n\n// Happy Number - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('d4c80d872097e448e5f5a46726236b9bab23e5b9bfdef492c9db561fdcdf0ea9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Happy Number - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('da8f49080bb3b3b40b31b6972d7c292d6f761e3c8e91cbecb08dfa6ee188daea', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Integer - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('6efaed8858568091cb3ac08dcc93f3268c580280c2ed77ce357620a5c226de61', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('4d5edb73e69b10708f1d431771f3d2e388c028c630147f771de0cf6019bb728c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('5428df6024a0bd0d7876a29044d9799ac58830d9d475caf2151ac6f36d2478b1', E'import sys\n\n# Triangle - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('5ea2b9d21d863ab73beac9454fb6b448cfc66ac3c5e6971ba711e6560b70f097', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('48354e01069ef0799aedd4e2264440e9886af14f62d7d3bdacc61109ab77c238', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Best Time to Buy and Sell Stock with Cooldown - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('7504645aee8e65744ba96aefaa9c31b1f7eb652fa92e71b6634fb055af64aa8d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Alien Dictionary - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('e13d02901ef953bf2c88c245c6f28e3e8c1372922d1065eafc20cea5e4ade5fd', E'import sys\n\n# Find Minimum in Rotated Sorted Array - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('63bb2960633f68c33c6863b6a5294d9b4d191cc3370984ea5b688adfe92b3f12', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('373ad119d03475ef56222302b0920b0d13496ac20cef4c002bb877ce3e9e798f', E'import java.util.*;\n\n// Binary Tree Level Order Traversal - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1)\n    }\n}\n'),
    ('6308c763773c2a27eff5f925604cb67c818feb1214a517eb76c60cbec2317137', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('be6c604943263819e03750d6c34100de8a82a6197f94b8b8867cb36d200fd030', E'import java.util.*;\n\n// Maximum Length of Repeated Subarray - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('437f0621af0dd1d000067c7e9749968248e4e7e53fc3b4d41b96e61c74db2df8', E'import sys\n\n# Graph Valid Tree - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('86614834346d3ca0a297a5a7f440bda366c8e268658372d037dde2a6dc1803c1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Two Numbers - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('84b5a25788fb76882756f4ed7fe668fd706582da763f5a6628255ae6b73f90af', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Median of Two Sorted Arrays - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('04723be991058fe7a24c95731fb4adccc247d6d403509b6217bb332e52ef0a08', E'import java.util.*;\n\n// Reverse Integer - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('be3389b0c24840b51b644929fbd5e09f96c1ee1c8ab3a7ceb86ceb5c17e4e05e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Path Sum II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('50a35fc23bb3839e89ce70c3c4a4af90b031a90eedc3366d6066f1a4d9fb0c9f', E'import java.util.*;\n\n// Subarray Sum Equals K - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.printn(best);\n    }\n}\n'),
    ('04bef580a985496efdd1c794d82b49bdd61944f716886bfa97aab59b55202740', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('bb297dda4c88bf5b2d6a81819b803bcf3d09c88ac57471ad88ed72a9145c6966', E'import sys\n\n# Alien Dictionary - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('206975fa8bf4e04c7237df256874de4e6bbe82a644361e19e411cb09b04cfbe0', E'import java.util.*;\n\n// Search Insert Position - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('b21947e06451968df40d7f526f37f194bc70e963087ef5fe9a005b609c87b177', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('0824f78422048c1ebef999591bf6b948a0fe2a6346868da1b35d295421470e21', E'import java.util.*;\n\n// Symmetric Tree - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('670194b8260d038e1e599e3e2cac9cbf683d1c085cc06a71774bdc57a67c21d3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('25a88333b8e1843836b18a86a2826bba47bbb61ebc9615e1e66df5bf4c9794c4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Missing Number - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('b3aaa52dd81fe81341995c4744aac3733a3b4efce96a624630a673c10bd3a94c', E'import java.util.*;\n\n// Happy Number - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('db7766ca4898202d4b787871dbdc80b27cd04af6837d5d5f46a5015cb141956f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('0bc746ceb29f6fc5ad3679f61e2aab45c1b6f6acddf71a5aaf0b2323ecf19984', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('19ebc337012a45fdd3446a25cbb809b6d4683fe1b7239c16b93f507110e52fc6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Happy Number - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('6c2905a50406dbfed63e6b69564b242e4e8c35ab00bd5e387211f7d05127cd4e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Happy Number - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5f4b9617c97af186e828604d11dc429fe88b930a06b128c38bd7b75687d31c38', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of 1 Bits - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('f78f8b85920f1457a9e64ca438cb5f679c4e28c90e194cd01bcdf531647e847e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of 1 Bits - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('fdfb5fa668379ea3350a992f556316b7291f962cb5f0f69cd5c974368c46bed5', E'import java.util.*;\n\n// Partition Equal Subset Sum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('d1b72ab3a41520b3ab65d416dae8d12079879d98a59ae52b34bebea7be0e9bdc', E'import sys\n\n# Regular Expression Matching - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('0483b33a3602ba7b0d2fab179e4db8c9915e06f8909503b8241e86f222633575', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('80f830337cc10ade9c6fe6877a9938b2c5f217037bf143e916e09f81e5acfc6f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Majority Element - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('14b301f6f3a608a754ba4453ba405916eca1045fb11cb38e39424b86ba83b71f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Binary Tree Maximum Path Sum - attempt 1 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *a = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('ed119107cff74836b46fad4b9fe9200598a4265d0d62611436032f713bdf19f5', E'import sys\n\n# Wildcard Matching - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1\n\nsolve()\n'),
    ('7a55eaa7a2f53e5ce0177b5d77d50c75357cfff8fa5006ea7e09f7d84719eb35', E'import java.util.*;\n\n// Coin Change - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('3dd62867645da90a341bda088c66342f22fdadeca51cf0c751a09920a4f0342e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count Primes - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('99eff7066f549d3380882eaad11163bb214a9103fbfabcd0f688ddaf5d8ef5e3', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Best Time to Buy and Sell Stock with Cooldown - attempt 2 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *arr = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('4e699849f2d37f74e33a680f58b5e88b15f1c31b9977e53269489f760835742f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotate Array - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('d68fc253ed7f0ea7dae4bd985e1699f36bb6b847469628670f0b25519c334c96', E'import sys\n\n# Copy List with Random Pointer - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('a2183c749ab954150edb76bbfcb0281212352122a5f6a332c58dd6be7f8fa403', E'import sys\n\n# Partition Equal Subset Sum - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('89604a0be233509f7282779f15d24d1f6a9327369606523e059596caff69e617', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Product of Array Except Self - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e201cf4733babeb7188782bda7f07588ba6d503d31ee7b01123419846b374308', E'import java.util.*;\n\n// Palindromic Substrings - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('d000e97d1d1bc135b08e6ef855072add90a395989a954d52f78fac5f6fdd5a94', E'import java.util.*;\n\n// Count Primes - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('53c2a5d9bf1b37550033c98a77a849d5c671a3ca04f34092e96ae3ffa106f0d1', E'import sys\n\n# Counting Bits - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('5a86c77ed0f273234040118fac86858787b13a7c48e1441441436637b52aa046', E'import java.util.*;\n\n// Add Two Numbers - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('51d11200428e53ea803a74550fdd505354e6017a2b553cd218766f544024619f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* House Robber - attempt 5 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *data = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &data[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (data[i] > cur + data[i]) ? data[i] : cur + data[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(data);\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('d161250a4348f830f4078617c26a9c81590541f66903090e17f2fc79b3954d7b', E'import java.util.*;\n\n// LRU Cache - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('41be181572b0ced2ebd5a9ff5a2479c556e2acd68dfdf569ec79da13f3fd8bff', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count Primes - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('e6d6b6c6efb6a4630fbddfd00069d4a2c19f095f47c5412b6942d4b52fac60eb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('f4779e34ad1b9fa1de017b22031f0928ca8c7408a92707608c8a04b928eb9ebf', E'import java.util.*;\n\n// Letter Combinations of a Phone Number - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('81d5bd4b17d4123475ee95fdf32033804fbff25e7e2be5b764a1a8e6df0903e0', E'import sys\n\n# Sqrt(x) - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('210f006ce517f9e8a2ac1dee986c90ec5708383121d0d604408f34a8109ee08a', E'import sys\n\n# Validate Binary Search Tree - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('596e8007791e8037872eca760f2176c9977891093ac3326ae761b6501de17356', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count Primes - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('5679e88bfe239471073a68ba913184634a8e2805c764669017d29dd6b46838ab', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('47bb6bcba61f773e081330f63e8b8a836cd58cb5a974b8f930746a6e1c7105fa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('9839284aed013f28ec854e822664a100e8eaaadcf86233035fc00d39e83897b6', E'import sys\n\n# String to Integer (atoi) - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('59d2ee50eed8a00dbb4d2ee8434536cf3c192b643325d029a74ab37c5b08acb7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('9bd58ecc4282f26d66ec2270b039f2cb74136630684d3b8fff4356beca8566b6', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Product of Array Except Self - attempt 3 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('6574b99c511f6bd6e111d461d99fa9e53628c165fc1a795f3ea5bb3283648ec6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('f79e7db2837f4bf1cd164a645c127f81766079b6f05c1ea65fb31f86634cb11f', E'import sys\n\n# Merge k Sorted Lists - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('e8dad8e45df73fdbb2614524439b7eee377fff344ea8e1ddf911d774a72b8c0c', E'import sys\n\n# Balanced Binary Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('783a6bcf2abd9f2ba22ab855343d0ee47db5a7077631b16de934df6e34dfe6f7', E'import java.util.*;\n\n// House Robber II - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('ffb41858cef7a9aceb9ed69eda24a36b019d363521e1cc777be48a606300a68b', E'import java.util.*;\n\n// Count Primes - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('b5cf5539a4704f64e3f01a0d203deaa8ae55bd3798ff56e446a1fc99da675daf', E'import java.util.*;\n\n// Cheapest Flights Within K Stops - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[n]);\n    }\n}\n'),
    ('7f8496067edc746c2aa707078108ce0a13c4c6e815664b9603e2ea8933eafe03', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Search - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('ffd98b123abb0e3f9f17c85647ee5e80431ec779e65d5d08de9962df16e6a94b', E'import sys\n\n# Top K Frequent Elements - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('c6ca079c5e38bf0209ee2b60ec877a07397bef59ce3a41902a9d8fef096a4290', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Shortest Path in Binary Matrix - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('3ee0c4c1e66bfffa97e745bda3d258150455f4a56b7cd9138f58fcaab1f40027', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('1389779b02f48f86e21cea4d3bed42388da6aa23a14502a9726936cb5c4fef77', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Nth Node From End of List - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ddb1a7dd1245510ac45920bd60a5c4b835570ab7eaa53378b7553835e1f5f9d2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b64d49515d5e4f5306504a71281e6c5490c117a16ef382b9001ffe4899fe7c4d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Triangle - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('dc38dd4f87c3652c95da16a40220fed589c508c269ce18b52fcbfc770eefa6ac', E'import sys\n\n# Task Scheduler - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('b48f759c2f32f4655425b6751ede4baaf12c77654eab74fc1068ac200b1fbec6', E'import java.util.*;\n\n// Find Minimum in Rotated Sorted Array - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('bc205558af35997a8037d279a8cf53846c3c0934e1e0de495f7d008b9a15f70c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Counting Bits - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d841cdc959b5847a40f2e6f31706bcb5e494c5a4579f1a90d97f3c38fe6cecd1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Counting Bits - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('692717b18e6343842f651fe8abb6fcbc82031eabb8b1f2694a36d0b67a47b57f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Single Number - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('92e2d8d27a07db1fff247623d5c2619d79913d92a8dd2e04fe089a823007a8c6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Single Number - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b6d20501135fcfa23d8b3c3712c51c8ce11d16b9c1743de01aa906d2082602c3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sum of Two Integers - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('4323d1e3f55f9705355a82ee94d2fa33090c908bcd7593d70e7823eabfb0c76d', E'import sys\n\n# Sum of Two Integers - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('818277465c278ff3093f734778fa4667a35cb36bff5818cedd51c5b91c2f2883', E'import sys\n\n# Binary Tree Maximum Path Sum - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('172be58879f109d0123d7195a399987c7a08d14778306a0160ff00e659d21ea3', E'import sys\n\n# Russian Doll Envelopes - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('0268bad6d1492cc64b881301e5c777815c38ff1a51d1c81bbceee0d5f24f3dfd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Flatten Binary Tree to Linked List - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e5789ff0d6389ae3dd4e7cde30fbfc3a8ecdb72fa401bb4ee1867b5430a5d2a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Common Subsequence - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('6fed29f3e61ca79a92e0283a03135eeaee7e5d96999d36a0c99cf86c41bf7767', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cot << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4c182140f434038c2876cefeecc6a1fb1b4b4a3c6d39c3917234dc7c19be4ca1', E'import java.util.*;\n\n// Happy Number - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('5b4a3e315a917e59641531e7e2bdff75a5df5478c8fbe106f60e300b9f1a9474', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b964e82ab09d6a8e847cfd7756673e0d7d3d01d0ea425d3b899cf65ed8f7508c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d9f727a2901b75efaa5d983b841bd1105f38c1c55c40c32335a2f80afa2580e2', E'import sys\n\n# Single Number - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f9993c4ef5de062ded26da075ad408b46e75a4a681a95a8ac139b146fac77f23', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('abb2df6fe68a9013e2dabebb667f17ca32c77793f60f960bba1df9cb9bf6cf02', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search Insert Position - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('f700dfb5699109ab9cbc49e9e259fed5b8c0ecacef592a2de73643524ed9eebe', E'import java.util.*;\n\n// Flatten Binary Tree to Linked List - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('c32fcc8d44c78166cdec7b5d9eb98307dfb4d0c37da647e673e521afd34c838f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Repeating Character Replacement - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('c152938275682c0e3729e6fce7c00878470bcc002b0b0d34f86dbed493490547', E'import sys\n\n# Path Sum II - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('7bd167e17a2b989a81bd702c106600e4716a3b71ed14f3568312822c075aa4ad', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Partition Equal Subset Sum - attempt 6 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *nums = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('266fb6a72f67c0702235d3f0d389c33c8d8e0674ea401c93449b5b9873b56244', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Meeting Rooms II - attempt 1 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *a = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('9b255241f0e68da09629bd7f89e632aa562b3886d2dd7d8c204d9b2c3a1b2721', E'import java.util.*;\n\n// Russian Doll Envelopes - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('d8a1ba9153ca4d1e74a79c2df0fbb88f7af3d996295f0fbaa2691e4d0506dcb4', E'import sys\n\n# Jump Game II - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('cf525a662e7ae9619cca876abe7d32e2d4e6826e3d924f96cb3b1b1d2f9c0663', E'import java.util.*;\n\n// LRU Cache - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best)\n    }\n}\n'),
    ('ecacf73db6900c719f18507cbe156cf436f3dba3897083e1c2acea4f8ea10a53', E'import sys\n\n# Subsets - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz]\n\nsolve()\n'),
    ('a00a29f31747d1ab9e8345a679a23b51f104dbe24cbe8a81f183f12fda56e23d', E'import sys\n\n# Single Number - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('0870fe3fbe03a69c4cc1edaa81638c762dbf532fd083e96969dbd01039096050', E'import sys\n\n# Find Minimum in Rotated Sorted Array - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N]\n\nsolve()\n'),
    ('2169c78563f1baa10a31865593db79f83dd891796a947e64eecf5218e619ff11', E'import sys\n\n# Valid Anagram - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('c9a6b15b343cd32ee99635b57ed9b4a455dbbae408c9e9dfe07e5920e0db66ad', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d9c7941dfd7cd571b5a222077d1a9315509c0abc03765c50f35d48a74fdd7a6c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Next Greater Element - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('741c2bffda0ef91ffe1e739e901360333314b6d85fad80ad1a2171d5bb85d179', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('0d5e2e2a97eeb3ab3445f9eca2494c440018ecff8d35f844d18014d2d20187af', E'import java.util.*;\n\n// First Missing Positive - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[n]);\n    }\n}\n'),
    ('c37c2f3cf76abaf3cc0e0f08c7324353cacd1d20553e39cfc96cdb10381c8f2b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Graph Valid Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('e49b43498c9351b18aae09b337fb98e0ca933e90880247bba763366743de132a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('257e0f48d7bb95391132392e4ce5044af4bcfadeb2d3a6d43d2b217d4820bd77', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Egg Dropping Puzzle - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('c786559aad2e74891310565665ed8c12b81e903aca35f4ecc312ba48140c7eaf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotting Oranges - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('602741934aee882b34a3b8d5652a4bce707a315fe2ca91b74086d18b1f817dbb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Parentheses - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('dd05707413c38803aa0612c61738c35a9b7f48f813d4e0fe7c2f0c16797e6b3c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('6d41136bc34dad3f86e7298912fc4036f2f6eb823db1609a6ccdd21391282474', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sum of Two Integers - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('cd83fb65b44da6d390fa06e67b0bfba18eca84914b673988c76d2fa1a64f0d59', E'import java.util.*;\n\n// Target Sum - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('c155bee5d5a66bd2958f9360cf1f3bd82bdeabc74f85aa1fa8a1b30d39b5ac01', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('fb5aec12d0e1daae569aec0c895040d7cf523c27c391af746ec4997c2e78d596', E'import sys\n\n# Single Number - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('f875e2a575c7866dc1b3ede269d231bb7d8183efda12a4233844342706362b71', E'import sys\n\n# Meeting Rooms II - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('973139460c58f034ea68780572914820e34a1e08efefd5d6ba7c807d7d7ba0a3', E'import java.util.*;\n\n// Number of Islands - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('6881502467c6d3ff68b40b1e956ee6cec855cef80fae8b86babbbcd5cf65c86e', E'import java.util.*;\n\n// Burst Balloons - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('98b8a553a5dd612be5bdbd5b1a647b49343c6863e9b985a77a88a97cd65f9a78', E'import java.util.*;\n\n// Diameter of Binary Tree - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('7e60bf88083081f72cbfc65595504dc7c93374a1af1437ba9a3d1e425b2a8625', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('cc9edc928b1b2633bf8f79092b82a134473014c77232f8be7abab40447c0b72e', E'import sys\n\n# Number of Connected Components in an Undirected Graph - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('037d1ae8d07c50c9e655d103ca40dcf2115bf7514305c361dc2fef9dc5eac813', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Largest Rectangle in Histogram - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('e5e019249845a61eff2bb1b418db4a0f6152be72f4a9a0ad58b8190e38229f0e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Koko Eating Bananas - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('77cde67f11d677c6d55b8ee167db3a69b18885283c4020ff1cb3dcc3ca7089ef', E'import sys\n\n# Permutations - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('78a0f45c33677e0e507ec09f9286f63f638bbb4ca879b16919402050efdbc90b', E'import java.util.*;\n\n// Subsets - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('50071489cdda49b213bf745f6af954b263cdd18d36c48c05de850d140a5c0b3e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('056ae7c4f723b86993c0b35706f327f2ecde4f807705d846639b38bf8d3374c5', E'import sys\n\n# Combination Sum - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n'),
    ('4a610a9ae511990c4d9282d4db8bd31e3834acb0e343507368a33515ef473d34', E'import java.util.*;\n\n// Pacific Atlantic Water Flow - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('7fd038de7e0857641eae2d869afd12f1fb3a2d5f0f75c2e918daed26514eb2b2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
