    ('abc2d10839cf1690e9d82e461ab832b61d961df00a96f4a8954aeec9dacfc900', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Permutations - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('0b1968e8e38941c1a1658a18e1d3f6ef700163287166150ed10d76af73e5c316', E'import sys\n\n# Permutations - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('3b0d82cfef1a3e8c891c33c36bb574dec52c2b2bc861fc528499f75e467d5c22', E'import java.util.*;\n\n// Permutations - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('e64dcc877f0333fe8dcbd0ef2801e8c2aa061745b8052e17db78e9bd3cd21dd4', E'import sys\n\n# Pacific Atlantic Water Flow - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('93810b6da9d66818ec9583d4814a86ea17faeed56beee5773bb564d80caaf731', E'import java.util.*;\n\n// Pacific Atlantic Water Flow - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a736f1477ad1221867667c8498b8c442219313392699ef636fb507bb6e2d43bf', E'import java.util.*;\n\n// Number of 1 Bits - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('91817fa14aa36f4202b6a181aa44bebb57086ef88210b599a8b1bf81e144afea', E'import java.util.*;\n\n// Number of Islands - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('68a17dd88874223d67bec9da0c051c549a855738abcbd5d8482701b9a001e2ff', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Set Matrix Zeroes - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('e370e09da809248f0fbc12330c08c8f20a82a0186a882995a5535f9d10920569', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Distinct Subsequences - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2fac535390be44e31fb4afd6b5c0ec7bab565fecd06468398276ada05e004743', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('41e3bb3ad41f5a1d81316fe7fa745e3b94149df0f12b6c22aa688810fc5180bd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Search - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3048cc94228a112c4bc01f97b5868322ec98abe23cbc95810d469b3fc5fa1bbd', E'import java.util.*;\n\n// Kth Smallest Element in a BST - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('b5a697f80e4c4b20496355ca2d617236bc4fc80309c112074b672c1d3b07626f', E'import java.util.*;\n\n// Russian Doll Envelopes - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.printn(ans);\n    }\n}\n'),
    ('c197d4010fa3f7e223752d40b4207228945d3231c79e2d5336f773bef268b7cc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Non-overlapping Intervals - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('be79b8d9b0f23c97222bdfd46f823fac3822902e1e1e88dfc37dd4d392793d30', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Increasing Subsequence - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4a989bcdf27e2ffc132831c4b41b2a0b925c6dc93b1028d538ad531dab317696', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximal Square - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('991a4014dd77008538254015c6e2e348208cf94e66572cffcdd9962176dbf45f', E'import java.util.*;\n\n// Russian Doll Envelopes - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('8a22b7e854336b557b6af494b5d106df3f7b16b634f08b9fbbe377382880d91b', E'import sys\n\n# Counting Bits - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('5b617847531fe65196eeddfde3c84ba6ed306cbc235cefd88f607a925735749d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('d0bde2c26579812716bb604aa5cfb70b6c93903c041f6b619e2b27562e765430', E'import sys\n\n# Longest Substring Without Repeating Characters - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n]\n\nsolve()\n'),
    ('8f82275314128ba4b0cf520d7a502a0c5cf464237dcb081fc9f1b4c4b9f893d1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Largest Element in an Array - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('5736ec2e6534e1cf7b0bd20800364b428b86510b5f5a23beca8e653e89ebf864', E'import java.util.*;\n\n// Counting Bits - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('f35b5bb55a23d21e35be9e1b3a735c42ab79d7f5a8c9aa7d3c39ea15c6227543', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Balanced Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('930874a8bcd339becca9d2f0be903a0ea6f6bb3262f8d886b1c7e3f8ab6f8b40', E'import java.util.*;\n\n// N-Queens - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('66b42e49265b6188c056d85b9f2c0690d11705d98d71afdeb4e3bcdfc37c94ee', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Partitioning II - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('6ae6bab0db252bbab28eede67a867dd01bfc91787d9cea7b2092163273b0875b', E'import sys\n\n# Palindrome Linked List - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('88dc32a6873cdd341f24790036c51ac92daad5126a1e5dbe48acd070be4bc6ce', E'import java.util.*;\n\n// Palindromic Substrings - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('e39633b0f9a9875708fd122e6fd97fbc4436f13611a2871686194e92cb4e07dd', E'import sys\n\n# Reverse Integer - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('e8a304d6611f54c7dd687027f03f2f19d4254c3a7d737c5c4a83cfa6f59a8d16', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Design Hit Counter - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9ea3eba87a23d8ca571d8c5419265518eae32a11e73a969b02fbcea9e7f94124', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Subsequence - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('92a1d0958ea629ef944f2c6122a54d97d2c01011372c2e98a8182770099bb7ca', E'import sys\n\n# Contains Duplicate - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    arr.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += arr[hi] - arr[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('edccc667085f6d576371d328f8c1e5b23ee95a05ab0c66b8ff6415c8b48e9ca2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Contains Duplicate - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('1ada8c105fd4befa333e2cbf1bf9dd4e0bace98401ca70b3c77698564c7d4690', E'import java.util.*;\n\n// Contains Duplicate - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('7fe5896d0163f935b6a50a035f75c16501b3a6e4822c5557657934bacc52b5d7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('56d1c2fc1d6c3f7e58f4842cb5512be5a23c86948565964195475342ce1bbab3', E'import sys\n\n# Contains Duplicate - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('a0e1ca695ce56d1f2f77d51217d4859334616afe0768d1bc7dc41a8ab378c17e', E'import sys\n\n# Target Sum - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('00b6960543b98f26e06509be91da5d2023a4c2e388d2f85afdfb9fb0545287c2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Target Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('7c18a6114ef845d18a6a65d116fd99419db3b05fcd257d178e8dc366ba30ac04', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Contains Duplicate - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('ac1fa2365c68857f31879d7c431be67f7f61877dd9ffcebeff274d93959dabb1', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Sudoku Solver - attempt 2 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *arr = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += arr[i];\n    }\n    prnitf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('24d05348ca839f9749f2177fd4f82141516d232d9f584431eb3fcc753882fa95', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximal Square - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('89a23e6ae6c58a24a02bbe7c21eaeb342b58155da4c2a23326347e3088ca5d91', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('144b0160a0fc8d1b197859e55eddfd5145837a929883538f0c295d6deec604f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Integer - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('923efa1da2688999ab8575db1b222377d2fa96cad56274f66b91cdcc5fbfc995', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Balanced Binary Tree - attempt 7 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *v = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('0eff9d62fc642b64a7d7e262e8b420b4e5f626964680b78c4d45ad343af1aa29', E'import java.util.*;\n\n// Subsets - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('098a24169509e93f3909191e1166814e367681d5928acb0e74b00092631af92f', E'import java.util.*;\n\n// Jump Game II - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('f239246de7f26fcaaf049a69888e8b738779d25f8a62fa2cb794cabd7aa2479f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Wildcard Matching - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('b297c05d77047764a763c7a99ea0ef40d30b0c5b26770b29e12700ed20f341a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9efe477ea4cefab4ea48016050d9bdf10b99d386a716e0ad980c6ebd2350b859', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Consecutive Sequence - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('815dcea8a206db380104e3c92e71168d2fbfa2736915659b1c23d8f3b6fcbb14', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('062c9f4f1a9f5371ccef611cb429d06e330da81e90202f7a9baef2fa3da1e672', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Move Zeroes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('dd40a5b3780d1360f00ef5c9762a1e65a25eabdcbe0bcc5c4406753d875e308c', E'import java.util.*;\n\n// Construct Binary Tree from Preorder and Inorder - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('b3c28471a4198d2fbdaf259ad8e853dffb719c48e53d379167f95bf4223f26d2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sudoku Solver - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('f37f5909ef46bac1987a6c8ac5b9cd52044d8ea4f319a010b42464e8b7b95a8e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3bee5840c8c884d45f3ed49ff1ab5dd9ffb4b9454c196d20315529c28357b8aa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('a94c9e9aa0b159baaabd5a019556de4a9b3845eeeafc58a9786df8a727fb1e17', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Combination Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('59d416457698972de112727d84f2c382d4f3b6f4d78d6506e23da93e0efee21f', E'import sys\n\n# Linked List Cycle - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('9ebfdf47d5961afaec08b6a02178fa19a93627acb1da54e2312d2bb12003138a', E'import sys\n\n# Number of 1 Bits - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('a114e6ddd6f4ad1d15454fbe1eb6df0cf1c9676a2317107556e8ac909d023021', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('150be99f2684e2ca2d622d8fb6b8dae1a648d9160a2c675ba6fc7ea3a9e63156', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// N-Queens - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('231f4620faf33c1bae743cca1c7089150998fc6a542b63ce05f628396fbbba68', E'import sys\n\n# Sum of Two Integers - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('6e04cfac01dc81193c5c77647028603cfbda0849bcb8927ccc6b8b87398d3c54', E'import sys\n\n# Number of 1 Bits - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('28fee5669f8cec80bee0cafb362ea48c029e4d67360faa47cdb80a183eacaa1b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of 1 Bits - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('aca694e2b27291f0115227525b3be60bea499ee312ae2b58302288193f8f1f41', E'import sys\n\n# N-Queens - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e6246b0b701ec5fdb9141cac5334f485c4a4ab07cddfb86c5a84b86b9510badc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('4e50f2d53de4f98fdaa45b55c9f5863e8f2f47ee59087ae221b827d1797ac407', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Find Minimum in Rotated Sorted Array - attempt 7 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *a = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < N; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('a16a36885afa71829aafddb02b8caafa0c95680ed080b30ed8d26dadc507d838', E'import sys\n\n# Contains Duplicate - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('9073ba9bb7bc9fad874267bcd9408e6127e19123d27592bfe2eeabee9b54f3a1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('51bb1f3d7c3d7bfb2c6d659434c172f86cc0210623f6bae83ecc76b335f287db', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Repeating Character Replacement - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('67f773699c23be2d28b81a23114e2fe3c197902f3c3b07944543f85d06fd2d64', E'import sys\n\n# Container With Most Water - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('8417ad89509b06f6b0595354e67da1fe41790f2fd4eed05d008167cfe7e371b4', E'import java.util.*;\n\n// Generate Parentheses - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('62b5e9f7da9e7edfeb750d160fd5f5dbbe15d4ea35ba2eefccc7d1193e2fba24', E'import java.util.*;\n\n// Number of 1 Bits - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('8ec85309c7402add8c6274b236727692efdc2c8574b0055eb87f3f4936b89c17', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8d495137e03d760723c37488b1cdfb140179ef021d8e5f31639c86f73174da74', E'import sys\n\n# Valid Sudoku - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    arr = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('5db0569966e80ef8fae9129d8f66db8d9f6b217e366962d86ee45afc3d23f542', E'import sys\n\n# Reverse Integer - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    arr = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('0953bb3667b1e661cd03f96ccf9ef3e15ceecbd89511a45d492e0289f9dce94e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Diameter of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('8e8efed6063a1ec0003471191b8f6171d056b85e26e5c6e6c2bad6fc17d991f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Daily Temperatures - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('dc86ce17132c2d8d972607a0a497ec3f8518804b71d97512d0113b38e137cd24', E'import sys\n\n# Kth Largest Element in an Array - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    arr = list(map(int, data[1:1 + len]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('bcaeb0755930d79e8c38d90ffabe07c936275d60ec04ae5de3d8b15efeff3370', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Decode Ways - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('77deb3ed61ee0b03ae673152e6e3c66d948df10a3caa2d78d331737bd66e9008', E'import java.util.*;\n\n// Sudoku Solver - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('2315304efd68bac311fbd6031116e49727bf7b4211f559db86a1f4ac1d4682f7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of Connected Components in an Undirected Graph - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b36ae4eac60b044b746be76c8350fb2e45eecdfae3dff2902dcaba12250412bc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Combination Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('a87f768386b84af9adfb78600884052b70625d6dd36de2398e0c2c8adf34cffa', E'import sys\n\n# Copy List with Random Pointer - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('966070949175ebde16078f4d31e371ebfaa9de1931b7ab16d19d1d645b95987f', E'import sys\n\n# Maximal Square - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('1156aaf3fcf2eb84fbc3decf4b4da356a4d632253eda5f85c71fde79ebda2847', E'import java.util.*;\n\n// Diameter of Binary Tree - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('1066b6f5b366174e1e9218b0cb8935032d0f90ac8d0d84c4cc657dc141669c69', E'import sys\n\n# N-Queens - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('c4848ace372c94bb98a7383a07adbe9763dbf3f5f88117175c7bab5fda478e25', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('a530fde60e5d7988ad5caf3edf403826f3a18bed103cb0a10e738d1f9e622a29', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Triangle - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('ceb11f34ef09cff51d93b47265d15bb67f03e40511ab49668d9f74f3ee6cd51d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Regular Expression Matching - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('acfa62f2adba005920320895abb6d2ed8655772a866055fdfa08a9339c861a35', E'import java.util.*;\n\n// Happy Number - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('c53a5e2a6dba3700b8e2f7f8111bb067400644be2f64d96329af3ae108e07c1c', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Implement Queue using Stacks - attempt 1 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *data = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('4606750864e5354d3000239b5733d7f6ce730dfa616536ccf10e9c45eff01435', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('267affb2bfb580b7301a556a22118a1be2b6d542b0d90ad33c7c5d84377cc5b5', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Container With Most Water - attempt 6 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *a = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('3508983c4f9b5668f98e9ec9e6e84aa76e534923ec2dec192b95e2953935cf6b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('e0c4e2172827a6737c8b9149168a2252219737725bca2145bd77f253e2767ac8', E'import java.util.*;\n\n// Letter Combinations of a Phone Number - attempt 8\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('491ee8f83dc4e9ec5de5fa7b0e0cb5cb13c6573bb90815c03c34bc874da869f9', E'import java.util.*;\n\n// Combination Sum - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('980cb3906c1928ed4263b4747aecba550bb32f84dca2b45cbdc0d0a88a665c56', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Valid Parentheses - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('892ebaf09007b460e2bd6215b3cca6b1f0e6199b993ed24b4c9cc1d9469b1839', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Min Stack - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('569f92eaa667b1185a0f3881efed35425e2c9263eb631d6cdae4a0935af2500a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('0d60e609258eab0405c1aa6839d7048d5d7a208461f0d962c7d499a000096a2b', E'import java.util.*;\n\n// Gray Code - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] v = new long[N];\n        for (int i = 0; i < N; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('e5176d1e9e184b8d140c8a8a73af16535a2757d2aa6fb180fa8e47af70c3b041', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count and Say - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('f70530d694c165ee24769ecd1b32e8fcf5eeb267d90341ef2b201702a079f3ac', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Interleaving String - attempt 2 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *v = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < len; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('2ad78c2e48faa0599c12a7b368b064b98bd36bbca2c5add54bac1ae72c39c513', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Validate Binary Search Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('354cf64eac7c3dec02d690144acab3e898e008470a0d8b341a089b51575d1f70', E'import java.util.*;\n\n// Longest Valid Parentheses - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - a[i])) {\n                System.out.println(seen.get(target - a[i]) + " " + i);\n                return;\n            }\n            seen.put(a[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('fa604477557b0f4049b8a957fad4a93b6104c78fa69861dd40419f9a9269674c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Product of Array Except Self - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('cdf17f65c3566c393f6cdf9fbd6202a748665c91fcd93b332ad317f4a783a46f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Validate Binary Search Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('1b22f97065f81588ee09dac5f8a168cae27baa548cab886cf567c3d3b9238617', E'import sys\n\n# Validate Binary Search Tree - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('78d49ee35a701dce6486bc33b0daa616f772923528dde0c4617c381367f2118b', E'import sys\n\n# Gray Code - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('3302312355dba0ffec4f27d1cecc24d1b2f7e7d7dd9665f25d8adc445c2f170d', E'import sys\n\n# Longest Valid Parentheses - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('49520c9e56ebbcbfb3374b7d3ba4d9f3633ca27cf4b7cb7a2a453b6c5ca1aa0e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sudoku Solver - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('fd5826fe2faad522724f5893f5c29bb4d873271d953a0b55ca41b812c3dd840b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sudoku Solver - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9ccfac4ba13e2645935137bed9515bf2116c4ae811a57fe49ad90939654f2e75', E'import sys\n\n# Longest Valid Parentheses - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    seen = {}\n    target = int(data[1 + sz])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('268d7cf6be6753e157650f3ce3009b7e5b7e864b1d57c34f9d1c80f3835353d7', E'import sys\n\n# Validate Binary Search Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('330d92d7433e81a3bdf8b05fef1c56ec7a6e22abafaf4faa751946b302f6da62', E'import java.util.*;\n\n// Validate Binary Search Tree - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('f7b9cdeb0c6fabc933ddf3011e9102e0e87c83203b09be90f9451ddc66e3a56e', E'import java.util.*;\n\n// Reverse Words in a String - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('557cb2500426929cac7f2e9960247a5bddc249b487f8504e369a559074665a3a', E'import sys\n\n# House Robber - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('348744df6cfadffb6c9389ab7add671fe1714b7c437a36e1a84624fb1af10674', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Subsets - attempt 3 */\nint main(void) {\n    int len;\n    scanf("%d", &len);\n    long long *data = malloc(sizeof(long long) * len);\n    for (int i = 0; i < len; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < len; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('defcffbf717850cab715c7dbe0da8e2cdebc05a9eaffa99b1e78e7293757f5d3', E'import sys\n\n# Regular Expression Matching - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n'),
    ('2b704d6f3af8a78825fe54278d2ac7fd6b8b53aecd7b298f5d35628f3eb5c81d', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Two Sum - attempt 3 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *data = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &data[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (data[i] > cur + data[i]) ? data[i] : cur + data[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(data);\n    return 0;\n}\n'),
    ('596c3831436fc79aae9b0de2e1ea0b8471d5bcc141bf2093bb9b3cfc4b8978f9', E'import sys\n\n# Sudoku Solver - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    dp = [0] * (len + 1)\n    dp[0] = 1\n    for i in range(1, len + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[len])\n\nsolve()\n'),
    ('27ee1606223bcead85860b565e7df7db814edc12e577cd04cfebc9c14500666d', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Pacific Atlantic Water Flow - attempt 3 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('75657e11b205ffb4e00f9016675d59e5e9e3ff0ebd590fd52dcce5e447a79972', E'import java.util.*;\n\n// Three Sum - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('b1c8ea9aa2bb0e5379abb1c807f1e5f921f28e1ff71707e07bdf2b8b85097291', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('04aee0c1703fefd42fc944f22695691147dbe7969442625ee6059a0befe0ba3d', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Linked List Cycle - attempt 4 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *nums = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &nums[i]);\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n        ans += nums[i];\n    }\n    printf("%lld\\n", ans);\n    free(nums);\n    return 0;\n}\n'),
    ('9b92786460e42db24a8ede1a3e33e3ad02057cfe5e702a83e7a131f972e92aac', E'import java.util.*;\n\n// Pow(x, n) - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('0b3a610957ec32f3bb05d043493bae1df0b3eb08277c927a5764997c98f8aa1e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Coin Change - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('c24a40e4bbd04d5e0632c5bdb15d644145e0620c32f771d8e0475a76c71dc07e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('01f016ea71824a2f61dbcac2d59f2c5d5cfcad0b19b4885cf75ec27542ddca1e', E'import sys\n\n# Combination Sum - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, sz - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('87532fdec287f1f9b5912311beaff63ecfd9e321fbf6935e734e6bd1229f4c05', E'import sys\n\n# Reverse Integer - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('fa2bff080848a87f8c0a0e073f1d92da9c3756dc53d8b0d416ba740119804343', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Level Order Traversal - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('aed2167f5477ec9179f5a2084564dcdbb307557c124eea2ea8b8cfc18c735f0c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Is Graph Bipartite - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('427359f5802f6679ba9b143036eac4fe8d1baabe6d0aea0ccc14181c0d6dced0', E'import java.util.*;\n\n// Kth Largest Element in an Array - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('69128e17fac03ed19fc286cf78d9ff7b0981f052a517d5dbddbba063b4c4f3ef', E'import sys\n\n# Kth Smallest Element in a BST - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e54a070b1dd17b71bce9d52f34cbffe2fb7fa66efaaefd4cfeab9ec6ddbdd693', E'import sys\n\n# Unique Paths - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('d9fe7c8a3edb347606a49b7a57eefa49266965e484d79e2c8ad1b6681bbfe477', E'import java.util.*;\n\n// Palindrome Partitioning II - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] data = new long[N];\n        for (int i = 0; i < N; i++) data[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('53331294b37b63420fc192edcf43ca2e459d29154dab85ed166023d5c0cace09', E'import java.util.*;\n\n// Is Graph Bipartite - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('8cb205c934d46f70acf63db84a7c3bf08f81da9ec7bd6adeb73ae93d9eed2627', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Koko Eating Bananas - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('a1408f2cd06a1c5bdfe94eb71753ab3b70f54625659e989b9e264da8557deffd', E'import java.util.*;\n\n// Jump Game II - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < n; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('57109dc364f4033b9d5bee035aa7b349d228242103f4f43e6ab5aa9c362cab21', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Tree Maximum Path Sum - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('d42a65afa378dfbc45fb30411d70fe356b0f30351e5e4d9750b6ad6c030b60f4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('32526d8e0ea35a6c2c2b1275e4c53fa0440fbf0e369240b51c9e632c8b5e9bd0', E'import java.util.*;\n\n// Decode Ways - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - data[i])) {\n                System.out.println(seen.get(target - data[i]) + " " + i);\n                return;\n            }\n            seen.put(data[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('2ae2770aa8c2b1aea01026f3ca8ce5dfe4c365b2b32bbe6d48d50c19b76c1fd5', E'import java.util.*;\n\n// Swim in Rising Water - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('89f86c58abb64d727c9ba098e4d97fdba69136a577bc46e2b5f1d52abcbb2710', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Serialize and Deserialize Binary Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('4ede4e0931718c830b49ab00642a5d292d1cad3a741fcd6be24b2e4dc211800a', E'import sys\n\n# Implement Queue using Stacks - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('4e33357a0589479afa27f84011c2f14c12682ec24b65b814691f3a6ab7ebd03a', E'import java.util.*;\n\n// Jump Game - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('07d7c39140d84140a52bbdf586a960aa3f20297653368114829fd32fc5736520', E'import sys\n\n# Counting Bits - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0]\n\nsolve()\n'),
    ('976cbb0d96cf5e2a8ec17bae104f746023dee33604c83f0e2c844938dee58c45', E'import sys\n\n# Subsets - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('56f7e1f9bce6a82b3fa0a8073b5dae8595881dafb9e3846eb5957c5f4ed83a6d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Permutations - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('fc00b3919654c54777741a6d18d8306412e7409ab1ee40788167b0f55790d0d9', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Set Matrix Zeroes - attempt 2 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *data = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &data[i]);\n    long long ans = 0;\n    for (int i = 0; i < n; i++) {\n        ans += data[i];\n    }\n    printf("%lld\\n", ans);\n    free(data);\n    return 0;\n}\n'),
    ('9a053ff6f5f2eb40982f52c555048e850eacc66b3a8f53971a5da331eb42eb31', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5085f52a6eb0930d790f4624b9b0176dd6ec432023fa3492f7909dfca7c2d397', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('d4da3861c88a7670dba5db9608dc2b39f08f7b8a3a4d15bc6d70c4fdaab409eb', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Length of Repeated Subarray - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n''\n    return 0;\n}\n'),
    ('fabd782ec435e98adaca3b1b73c35239e2663b96506dd20d7e3f5303e69ad152', E'import java.util.*;\n\n// Graph Valid Tree - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] a = new long[len];\n        for (int i = 0; i < len; i++) a[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(a[i], cur + a[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('2f2db2dda1d9921e5a80554c15c182b9fb004366e051636ce91ea9b4c6bf8ef6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9db5d4b48c4e58f371c8e4cf30ec1167448e160e6288dcdcadcc345f5094fc81', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Unique Paths - attempt 2 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *nums = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &nums[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (nums[i] > cur + nums[i]) ? nums[i] : cur + nums[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(nums);\n    return 0;\n}\n'),
    ('3f0da65f8fab52bd9f89732a0eae83e7b6b06e7ea703973ff21c40d5c5b7530a', E'import sys\n\n# Generate Parentheses - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('0bb2d757ade4e3791f96e0e640d55db49b083af02e13f5dd9376ba68f173e5c2', E'import java.util.*;\n\n// Merge Sorted Array - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = cnt - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('a726305a99b58e392882044170fe9b2ec0906d3487990fc7abd6b0d52431bcbc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('2f58f445730892f07dc827453c1c7452b84873187c7653cf7210b80da72e05a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('ee98e1c2dcd79d13c4bdef81d2203f6571c7d7bce5df673db64c3fd72e8b211e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('183cad5f68c48f0dd05d35c3fd33f4bcaa6f50f83baf3d6ce2204bf86fe05d6b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('c9f3e5344824d2a02f787b8014387dbcc6a3e12b1ba2e97254144f55854a5558', E'import sys\n\n# Merge Sorted Array - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('676f2b9c05dacb4ccf76efb118081912c4057c2159f6c6e18e72b9c50d7665aa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Permutations - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('63c166bc1bab902660100be4507e5832596ff56fbecd72da4270f754d1936de0', E'import sys\n\n# Merge Sorted Array - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('155810e8aabab74c22a4a7075c86bb626576a8c4bfca99dce2bfdfabf6640de5', E'import sys\n\n# Gray Code - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('9a04b1613d7838fbb4f4752f4265b728738d63f37f32a7037825023e362135a2', E'import sys\n\n# Remove Duplicates from Sorted Array - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('eb9581fce7d398e91cb1759fac48814c0e39f79ca3750de7032c14f8231b119e', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Merge Sorted Array - attempt 5 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *arr = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('ecf50b636e8b6185034339b66855eeecef3a79504f0b9f958f54eeb5f77c5c86', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Jump Game - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n''\n    return 0;\n}\n'),
    ('a88af1089b6c37360e82ae87694c53c58e5f357c08a328e5278955905458ef65', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Unique Paths - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4dd7a8245ba2b72072bb8b30ec5cdcda1f6e425e1354a66b37d802860ec2dfd5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subsets - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3e5a6d8d8f5525a93fbb368447645dc71591feee89ca0122ff26e34cef52de09', E'import sys\n\n# Swim in Rising Water - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('978508bcf7247dd8ea2646a5558e5b712a41a3b208724080eeade6d3664a43db', E'import java.util.*;\n\n// Egg Dropping Puzzle - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[len + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= len; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[len]);\n    }\n}\n'),
    ('7637c66f86ec03599ac67c436459b6dc968ae430d44adb58243d7ad65e38cc8f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Count Primes - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d4c9255eb148091cf36d36671d58ef24664da7498702c527d715c77dd7da6033', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('93c4f5a8160837a9cb89c7ceb38af871907f72d3b3aae552dfb3bf9cb03e0124', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('263bd277549e7f584b7146293cbc12f725874fb4dc8ab06a6183577b31dc29fc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Triangle - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('b6027bfd175fd7447fa91449c6f5a33ef66e87d74a8db300dfe1ffe086b0cd1d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Anagram - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('e103d0a4f5a62cdf4b9648d0be882431f583f77136be86b3af6762f7c4f721d6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Length of Repeated Subarray - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cot << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('faa5d6c8db2e99eac6dcdcdddd20d29ba3fb4e02e11beb158c6fe2e4296b746f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Ladder - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : a) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('17736797e9d45579bf236884c33ca3ffee928e70c44ae17b2f5f5f9874ae7880', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Task Scheduler - attempt 5 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *arr = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += arr[i];\n    }\n    printf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n'),
    ('84da427014c273fe40367410ac42c38bf15f58a18535d9d9692203639efd7853', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('18af4a40d32b9e09c6f9a2a40d395d3decaba19cbf3d97112eb0ed0809befbc9', E'import java.util.*;\n\n// Valid Anagram - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('8d39fe93d4d2d8bfab615e34876cc3dfadb47e395658ec46998d38b59b56a98e', E'import java.util.*;\n\n// Reverse Integer - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] data = new long[len];\n        for (int i = 0; i < len; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('143029cfdde3c7c040c8e9524df72d67dd037a845cc7f9d054eca9e7909038f4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Insert Interval - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('467f1190567611e2032e8c3d21ce10b5ecb63eb86b51bf41e1ec906a55fe9438', E'import java.util.*;\n\n// Maximum Length of Repeated Subarray - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('5092b3a008e0dca8dcc1e489e1aaeb2e8baa64ef002a57eaed4234acd4701490', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Single Number - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('43583a185b2ce0620a593314fd7e324edf3d7d16835907f66751555d3ab8b4c2', E'import java.util.*;\n\n// Sudoku Solver - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('eb9aaba61c7e3297d4a569e5d120379b656f1f6e0a02162be718d9019e5a2f52', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('591694a15f1ca38a3f9c493e15a08c33d1ef3f05f3772fc00a9f32e2e3860ecf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('afdd21cf6481ec8eb50504ff36dc8f95763b85c6c8a3c60e20a60f0780bc94b4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n');
