    ('9239141ebb4a400b4d1cd64fc84ada5465a4cf3ca9a69051e0a35833ad865ce2', E'import java.util.*;\n\n// Remove Duplicates from Sorted Array - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] a = new long[cnt];\n        for (int i = 0; i < cnt; i++) a[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('b48729b3f1db1d1fb10372d2f361d305e6a05890ab9918ae2089693e55f9144d', E'import java.util.*;\n\n// Merge Sorted Array - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] a = new long[N];\n        for (int i = 0; i < N; i++) a[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('9812f582571b3a211bcef91e86e0e58075eed65affe71f19993bb9ced3c882f4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Intervals - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('adb8aa3646fc5ae82b70a77c12595d4376c92de6b439fe4267254d7ea7044b1f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Climbing Stairs - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b880cf6cbc4b994e69222f9d825860c0dee5d1f427967f839653e6734685b313', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Search - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('b85bd81d9a35b4e440f10ae27f6ddc3fafaaf27c780ae0bf1488ff6ee67685b1', E'import java.util.*;\n\n// Subsets - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('f6925b9ae09a252c18f92b9f27563b84030910fb6a4f28456bcfc44554870e17', E'import sys\n\n# Subsets - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    v = list(map(int, data[1:1 + len]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('78b84b0d190fabaed82ce7a6413de433c31571b176c6468904c6a0dec0eea9b4', E'import java.util.*;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < cnt; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('62755353881d01b3ddb484f667561cd15983a47efa57307d1fe7357cfff45f1d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Evaluate Reverse Polish Notation - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('22718e274d82782f8b2e1878443b017a8dd2b1cc942985cbda9e55edbd839643', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Valid Parentheses - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('62e089aeecf2a2ba0cff62a9c6427c182de0686b9c15963c8d3fbfee94fb4754', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// N-Queens - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> data(sz);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('0438f251ac5af46d771a232d9d12f279c9a34afb44ca393a31ac3cbd00a85394', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Partitioning II - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('0db56dbbf7c7203580867c805bf25f29df20cad2db19506589821d620617212b', E'import sys\n\n# House Robber II - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n'),
    ('5b47cfb2f7c75ed45948239488d3f9a5dfcb19ce5efec2fe801b8e10375ab717', E'import java.util.*;\n\n// Reverse Words in a String - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] data = new long[n];\n        for (int i = 0; i < n; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('84c1641ba0044c691025607fe0679cfe3fdb90f925e311daa22badf4de20dcd8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Subsequence - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('2f460eb9dd29502064197228ea1d5d1747b973128e3423850cf55e804d9a9a94', E'import java.util.*;\n\n// Russian Doll Envelopes - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[N + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= N; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[N]);\n    }\n}\n'),
    ('0780ce1e04965d52cb929a52218a8baf9361e9025f3681569db0b92292a0510d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Add Binary - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('7d96731e92c2593313e8534503c083357c5090e19be08eb0e7cdcfc14c6a776e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Contains Duplicate - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('93569e0695f43a8d3b47b95780d2f14d3542d72bff39c5dea0d16229eb0a7c4c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Redundant Connection - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('e3bd8712f2c280288c717b4577eb1e74c25f318a8511e3cb505ca87de101c13c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f0c47a852b85b766fadbc34e583955c567a744451296c7f9c9d8f991084d8f29', E'import sys\n\n# Count Primes - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    v.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += v[hi] - v[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('853bc4dca8ac772aa0b61f06e493315b0aae65f2328460e384f32c979d136a0b', E'import sys\n\n# N-Queens - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n'),
    ('d7a783296984b408ff72c46ff58ac94d416d39e4e19fc56276b3ec7ebf4fcfe5', E'import sys\n\n# Maximum Subarray - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('a9d414e6c1d13439f08dd4df1ec1837e9695be3adb2a34720fc811a40caa79a2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Minimum in Rotated Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('2230302969246e6359b8a291e2dae4fc2b4fb0210853cec1ee865b274b8971a9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Linked List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('00ada51742487f9d42f3c35fa368f7d33f8f41bf0e46bc24c53c7a92577afcba', E'import sys\n\n# Edit Distance - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    data = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(data):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('2ac08c85f9a3da3f0886e8c14a0b2fde68e9003d688de5066fc25a76a7261933', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Unique Paths - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3ac3f28c40ff4e88df556f092f907e3f95004b9a9f8235bd67bf52d5f9d128bf', E'import java.util.*;\n\n// Redundant Connection - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('2374bae3c3037abb56a262f418dc8c474fb4d06a26472c78f5ac465ac2de067e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sudoku Solver - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('36468b2c46a114b7053d519b7f12d99caecd4c778209b18fde747afe28762b82', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('7939fee4ee39d3be34621e78326fc84333721606d4faf4a3274c48bb591d317c', E'import java.util.*;\n\n// Sqrt(x) - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('465c254b72a0937a72fd9734e4ddc261521b2b7258ae8c71b52c5ffc9326d10d', E'import sys\n\n# First Missing Positive - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    data.sort()\n    ans = 0\n    lo, hi = 0, n - 1\n    while lo < hi:\n        ans += data[hi] - data[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('6fa5a826b1b1417761cc22fa6f5b1495a8bfcc2770c84bdd9f9605d1649021ca', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('23407ec8bcbaf80830de367f0e5a84be3b5f57740ffedb53287ee2df2025de94', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('77ac86939cf5c68ec1eec36722c317b796b8127ed890a79cc3e0dfecc1dc2d51', E'import java.util.*;\n\n// Binary Tree Maximum Path Sum - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('40f73c381377821e0e0797d6e2b082da946dbeddded10978124b6251b6b65807', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Product Subarray - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(a[i], cur + a[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('d543f993d358820b023a45951790feea764841b3855102e574b06f22149609fa', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cot << best << ''\\n'';\n    return 0;\n}\n'),
    ('5845a35ae44c23dc85bb892c9a68500807b87790090e190669535ba5cfe1e745', E'import sys\n\n# Maximal Square - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    nums.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += nums[hi] - nums[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('e6a8764fc676461d7f5082f3de5f296559ec9ef989bd099836bc25d729449736', E'import sys\n\n# N-Queens - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    seen = {}\n    target = int(data[1 + cnt])\n    for i, x in enumerate(arr):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('6c9ddd8a1cfdbfdd9b1383ce38a848d86c96deaec6ccfd26be8142c9657e4f71', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Spiral Matrix - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('7d4dcbd67c74d84a5354c6e048e97f30afdbcda78cfc5298d2a91222dcb2ceb9', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Maximal Square - attempt 1 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *a = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &a[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(a);\n    return 0;\n}\n'),
    ('64f57bd9c7979eab28c7aab01fbbd80ede4ea1490d7adbf68d159b511223261d', E'import sys\n\n# Path Sum II - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    nums = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('8c8358ff6fba80411269c38b7c5a04d97979dfc52fce46bd9771f97e5f6acd36', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('af890e3be94f67b8393ef5d517cd50b858332e39c14aa7bef0061c71a49c46d3', E'import sys\n\n# Maximum Depth of Binary Tree - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('01271037ed85cb1d5f1d7ba16e6ccc892b7774d8e618f19dca624cc931ad7a9b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Validate Binary Search Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f1c90a82aa047b9a9c34479c5c34ca6ba28d92f2b44ee99751be49f58fdee996', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Happy Number - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('1fffa415c7801f766494d2540647fd2f4e4145574bb828d43d9c1a0d0f8a2f31', E'import java.util.*;\n\n// Longest Valid Parentheses - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('7cc8d0703d380b5922cf105c5826a5f661ef6745f9ccadc84d6baecac415b0e6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Majority Element - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('ba5b2eba3172808ec4541870ffa1d3aa7cbd0c17f647b71cb4d7b78f340c1c92', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('be6fb0fc6c9cb35801fd167d366649985cab0df1ce64a023d4da690a79356320', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Majority Element - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('906903f8c366a08e01b42906106f6a7f857114bc90bc300500cf47049348c5d3', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Majority Element - attempt 2 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *arr = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('4a3d685f608f74581954b2ec757f9b1312d478485db262c6710b17afeaac20ff', E'import sys\n\n# Majority Element - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n])\n\nsolve()\n'),
    ('037157a4899c39da46a04f146355f4caf4d8f27520d95b162db7556c8b910e57', E'import sys\n\n# Reorder List - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in arr:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('5df0e098a672c32f44c19d5c5e6b3c56441d07a28a5331764b39db250742a827', E'import sys\n\n# Merge k Sorted Lists - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    dp = [0] * (sz + 1)\n    dp[0] = 1\n    for i in range(1, sz + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[sz])\n\nsolve()\n'),
    ('9a236ab4e2fa0ab6941d77717f8ec4ef201105ba984027a3db41d590bd6f3f01', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Reorder List - attempt 3 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *arr = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &arr[i]);\n    long long ans = 0;\n    for (int i = 0; i < sz; i++) {\n        ans += arr[i];\n    }\n    printf("%lld\\n", ans);\n    free(arr);\n    return 0;\n}\n'),
    ('96be976bab94cc47bc890798d96ae1340cf29a394afcc17a1e794cc00ad28e18', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge k Sorted Lists - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('4b819a8c50f9161bfd816885a02934c97033f514e519f734d637aeff0d3ea892', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sum of Two Integers - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d12dc06751c7a6b986d3db5bcd9b293a4a882bd612a2a74e69b402584dabac86', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('0640ef07372fa9b436a37489909e1f7fcdde91aa9909349d3bde4f9322634aab', E'import sys\n\n# N-Queens - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('6497a80014b719ab38e28105aea63b4e8b5791140d2e548b6d3a8d152811e652', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Common Subsequence - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('6695932d8403237c8951f4a3703546a7a70052ceeb50c18f2bd20704f4dcaf30', E'import java.util.*;\n\n// Count Primes - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        Arrays.sort(data);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += data[j] - data[i];\n        }\n        System.out.println(ans)\n    }\n}\n'),
    ('e593ffe8c2e3622b93c43843fa5b84c9ee8bbb41cb9fb674d3d6b27c0ddd0107', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Egg Dropping Puzzle - attempt 6 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *v = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('c43cb29fc0c795a07b3132439e06e94e141ec4c27135746c92041180bdc663c2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('29fa28cf9b652c880d843f526e103aa260679cb62c75dc7413349b5a11fadb39', E'import java.util.*;\n\n// Next Greater Element - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('7c7c49f27e5c2bdf80700678b2924057ba0eb215742e3b9e505d7e065de0c744', E'import sys\n\n# Remove Duplicates from Sorted Array - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    data = list(map(int, data[1:1 + N]))\n    import heapq\n    k = max(1, N // 2)\n    heap = []\n    for x in data:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('9d6624e7cc95f6b16be3b7e4dedf1364b75f2c569f28452df9f684cb8ecf5928', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('73a4879b8b99518b149ce05b91ba67c27976b4ed48fc2c58c5e6bc7733736e2b', E'import sys\n\n# Distinct Subsequences - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('c30b3047891f244430167ff1d5c7f6276198e08d40075db0d5638102e17c90e7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Repeating Character Replacement - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('1e5070e02bf46e8e424b6461ad7d02c69139d41a4f9916d0a8139b50146a0a6d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Missing Number - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('c1b77f2fd4196952d9f0928a770f2395f797444e044000be43d4d5b90fe8581a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sum of Two Integers - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < sz; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('a14f9a4616a781b7bd83520c2d4029ed8ee039f3d9c19ad76fa9c7e52ea0920e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reorder List - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('afc17ca8bcd643390a3792018be3ea2958fd4b5b5dd2dda32fb79422b874c457', E'import java.util.*;\n\n// Remove Duplicates from Sorted Array - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('86af8ee2532f81a38c79915fa7a8de9dcade3300013f85b2a7fa64e6ecbf9ed6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Binary Search - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('77b2bd83767fbafc8a27d2ab09e34bd43d6a7575ea6b2dc49e1b1c3e7c7b7a8f', E'import sys\n\n# Add Two Numbers - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    best = cur = v[0]\n    for x in v[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('e2e9948ac081519b23ed14401fb3fd177c79f5775f761a76774e7fc438deb1fd', E'import sys\n\n# Word Search - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    a = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('b651e9a181d3af6ec6de6a8ea4b18fe4203497a4c9845f4193bcb5c2fae52f1e', E'import java.util.*;\n\n// Regular Expression Matching - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('654a89053938645e486732da62ba08140112ad5feb789bbe09544e9e6d9332cc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Cheapest Flights Within K Stops - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('42511dce93e2c50261812820c99834c7540524f900219762aa820a79935745e7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('b64e3174e533aad6fd29d8e7f93afccd6c89fb785e469798b4e69956e720da76', E'import sys\n\n# Single Number - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('65bf2ced9a2e98cf4193571d3a5da2bdb31f8198b70489cad2b0f639549e2036', E'import java.util.*;\n\n// Minimum Path Sum - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('0e18d80633b0534bacba12371f9f117ce518de7076d7457064a739fca46338b6', E'import java.util.*;\n\n// Triangle - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = N - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('c835e25fda45500e05dfabb2919cc302f1ff40419fb658cd31ee9c29a3031b67', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('4bcf5800cad95e929533013fec1e8a8f4b3935f36e34c7cdf2a45d71188007e1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Meeting Rooms II - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < n; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('1b871a9acb0ebe4f71839f869d70efad1b6ae0abf4641c13a7c74a32d115d97a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Palindromic Subsequence - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('6b4c9657f552e8b7e493034221546ddf7d0cb962239506d7de40b4efa558f4a5', E'import java.util.*;\n\n// Number of 1 Bits - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        Arrays.sort(arr);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += arr[j] - arr[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('016d7573d4ab6724a32a848e6b94bd437aeb7585d1d51b419d8ca13208031cf3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('b0464c3729c2e84c95d4cc67f908b36155d950f4debb16f8c487e4de99a29f58', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subsets - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('7ea27ef93f57d3ec9b9c26e187e3012a0af86da4fa1e00f5d3842530f1e066b5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    sort(v.begin(), v.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += v[j] - v[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('624a8a93c9ff342908e3ca927d3dade0a60a968c7f65f9f3de617e6d2e5d83d9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Same Tree - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('025ebbf8becdc71c96167fb8c8acac431502e08ae1e59bff33eec7aca21b4a86', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('524a2d6c3d07a9938ebaeedcf9cdc84dc33f3e872f5c393718c28b1c3a09ad89', E'import sys\n\n# Partition Equal Subset Sum - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('9f2be62c57e1f68687536ff354a3d382eca96d228fde70fb560de662d8c6f889', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Partition Equal Subset Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('9542a3d2905049bc74d0b9bf216e0a79c526e560e7cfb6dfb30a5bc0823a5782', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Two Sorted Lists - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('d328ff3b10b5c5bd5031270251a3335f5e0d8ef7101094688c71238c500c048b', E'import java.util.*;\n\n// Merge Two Sorted Lists - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] data = new long[sz];\n        for (int i = 0; i < sz; i++) data[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(data[i], cur + data[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('fc069baeb0f6d30904c782fa86733ad3e056198d9e041d8b5dd9b2fdaca353cc', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('0a6aa5307833332013e99abc3c971dcb6041d2a3b9037d773e00a07fd9b5388f', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Permutations - attempt 3 */\nint main(void) {\n    int cnt;\n    scanf("%d", &cnt);\n    long long *arr = malloc(sizeof(long long) * cnt);\n    for (int i = 0; i < cnt; i++) scanf("%lld", &arr[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < cnt; i++) {\n        cur = (arr[i] > cur + arr[i]) ? arr[i] : cur + arr[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(arr);\n    return 0;\n}\n'),
    ('e97a5638ef932e1772945c34d7ac05af3aa2da29f6f2c8bb2aacac36563a5d26', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Task Scheduler - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('e5fca59c0b795b2d4c49f58c7d29460c6461198ff7c22bcf6187ccb40f72230a', E'import sys\n\n# Remove Duplicates from Sorted Array - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    nums = list(map(int, data[1:1 + cnt]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('e48e08b11105ebe088a26ff2ce14610b89ecfd02c9cb5b25d70e464d3cf87063', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Russian Doll Envelopes - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('0718496f07782ddb4658612fa824c7f79ad5c861232a621b5a337844c15ad8a9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Queue using Stacks - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('43b08854128abdb50a7358b4e051c644de7b1ace6d7efa177de6c229cc669fad', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Task Scheduler - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('f0e9004affc5b7ce36e007e4cd7c1b87806d4f6f353e581205c8cd85e0ad631a', E'import sys\n\n# Same Tree - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    v = list(map(int, data[1:1 + n]))\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    for i in range(1, n + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[n]\n\nsolve()\n'),
    ('412c54f0124e29e03cd85249ff0b97142780ef425b9b0c869cce5a2840624161', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    sort(data.begin(), data.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += data[j] - data[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('4cc3cdaccf31665cbbea8e73b53ca5203f63c9469827a9ce706910630f786c2c', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sqrt(x) - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('7d1b5e67fd7f11e2c4debfe58936221a400a52da117df694e603824982f400cf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Regular Expression Matching - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n''\n    return 0;\n}\n'),
    ('f0c306c907bd2ddd6171c1571930dca85b39992349ae5acefd1c8a4418555e33', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Surrounded Regions - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('fae487a31f71a5dcb04ade8a278b03ad303883da95554cda343b647bf2e7fb83', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n''\n    return 0;\n}\n'),
    ('4a6eb497febb49e3c7cc95a02ad5410fcb90be9fd11215cc4c63825b7cfd751e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Number of 1 Bits - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('39d4fe7548f4ad54d82d123d3bf43aa08019c245c6b6f55ce3938d1d5974c8e9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Pacific Atlantic Water Flow - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('b1a567a7ac747d25cda6316c1966d1c3680b538c2669d1bbbb432d04bf568c62', E'import sys\n\n# First Missing Positive - attempt 7\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    best = cur = a[0]\n    for x in a[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('8db26fe6de1d2496ef0df1519343730de725fa5d3cb8b3f9c1fbb79ab0049286', E'import sys\n\n# Move Zeroes - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    dp = [0] * (N + 1)\n    dp[0] = 1\n    for i in range(1, N + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[N])\n\nsolve()\n'),
    ('3e2d122e80f4c5e78d5b41e9d2dccdbd2078c37bade022031b69ceee1c29708e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Clone Graph - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('3b5f1c8d5bb660fdb2cf6cac4703384123ee97282983bfe1f7a38e1525fd0605', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> v(n);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('673d931a20cb72db77e28cdeb6c4dd871c87c70cf8057708e18ae62ad597f7b2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('04a4b9075a76e2f667c8e7b4dbdda705736251aa5a6f7111f8cc72b313bc7364', E'import sys\n\n# Diameter of Binary Tree - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, len - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n'),
    ('36c21d9b3ecd55ec1d35f2a386d5ec1784929467e1f898f45f17f25b976ecff4', E'import sys\n\n# Counting Bits - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    len = int(data[0])\n    a = list(map(int, data[1:1 + len]))\n    seen = {}\n    target = int(data[1 + len])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('6620c741bbf071a16d5d03f7a9ee69e7a09243707a134c895b9af569a531c3e1', E'import sys\n\n# Search Insert Position - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('b27fe317be2507b075b8859abd13f1ee82083a51a7165262fad3da53c49e1ede', E'import sys\n\n# Merge Sorted Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('3f49bc6646c7573dc1cc20ecea2876d2d63c0a6ccfa3ac96e06f1705e028e2a1', E'import java.util.*;\n\n// Remove Duplicates from Sorted Array - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] nums = new long[N];\n        for (int i = 0; i < N; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < N; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('523da42d3e046ae2768dd5be40c05bf8f97f688067687d7b320cca75457f0653', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Number of Islands - attempt 2 */\nint main(void) {\n    int n;\n    scanf("%d", &n);\n    long long *v = malloc(sizeof(long long) * n);\n    for (int i = 0; i < n; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    printf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('b527fc65321f1ae3d10e3091446d9b006a02cd87c28ffe12f96ac6bedba3ab4e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Words in a String - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('c494d6eaaa678450245978285aa1630ce5993cd6cd1828426c93e9468aef38e5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('18d2a326314446164e5cdfe63ae303f2019bab0d3f742581ac642cc85d136588', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Search - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('9fe38664bc4673249186503d602b0b101144f674fa53f5eb6240e4ab89eab9cf', E'import sys\n\n# Maximum Length of Repeated Subarray - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    v = list(map(int, data[1:1 + cnt]))\n    import heapq\n    k = max(1, cnt // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('fba84cbe890a94b542d4dc1cf785baf4a1d4f670af46e379f74a79cfd2555180', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// N-Queens - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cot << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('c871ef9fc01620317ea0c48d3389e6d211bd9efa2e89c719fa9267f04be7fd45', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Search - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = N - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('0e8f421c1fa409a5d22bf7ba55675d26aae5c80308ace26481f4ce870ca2b5f4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// LRU Cache - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('c228d8b183ffb6e8a62d0f1861b4f81bf0c135442c02725e54f26eed1a55090a', E'import sys\n\n# Longest Valid Parentheses - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    data = list(map(int, data[1:1 + cnt]))\n    dp = [0] * (cnt + 1)\n    dp[0] = 1\n    for i in range(1, cnt + 1):\n        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)\n    print(dp[cnt])\n\nsolve()\n'),
    ('dcd4d62c8935098b758f710273063d5c3d09cb77594092d23f3ca4c17da0697f', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('b827a1bf2db0773fca5fa18f14ef8dceb1c415f44cb632280b3f2693949227bf', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindrome Partitioning II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('3c465169ffa6a9e52def77ec33ce22db636c3f715e43872f73538252d7c43130', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('063a29ff9d04dcc83843c471848c453463bfdc532193e04cbdc29dcff79efbc0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('445a409f548c52f607745bd75a019d134f6bc6ab89fe693cfc72e22abbda96f7', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> v(cnt);\n    for (auto &x : v) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('972dd83a3bdd2a84a4d0a95a18100de2f99d8b899a854f75e1eb571cc6ca36e5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> a(N);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('0634539b374ffddc7934545724f78e720dc32e131672e34df7dfbbff087d591e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Implement Trie (Prefix Tree) - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('abddd05fcdc4ed595fc6d2dcd7329f60075fcc498247b67ec6a667e714f73d5b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('fed551a114deff599745fb70b0327f72552a8002406a3dac30b7c3da112b745c', E'import sys\n\n# Decode Ways - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    nums = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('d50e69c9864c25019f5f949ba24d2a498adf62e7d8bbec2c381d58741f75c95b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Interleaving String - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(arr[i], cur + arr[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('4e75275fca0d4597ea05411acf7bc12e3e9c19535e474fb4334d3b2cc46e871f', E'import java.util.*;\n\n// Linked List Cycle - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] a = new long[sz];\n        for (int i = 0; i < sz; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('e499c79735c3ad4693b76169a2015ced8c9963963726b5e4aa3a805cb4132a05', E'import sys\n\n# Kth Largest Element in an Array - attempt 8\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('77bbeaeb7fb048f324806aaeabc847be2f79363fddc201f75786aa528b4447cd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Invert Binary Tree - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('72205d6f7fe5daad461e7fa61f9c994632a42255c0d79afdce6d7e8911bbad6e', E'import java.util.*;\n\n// Triangle - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        Arrays.sort(nums);\n        long ans = 0;\n        for (int i = 0, j = sz - 1; i < j; i++, j--) {\n            ans += nums[j] - nums[i];\n        }\n        System.out.printn(ans);\n    }\n}\n'),
    ('89e7c5b06308a83a016d984e6f2005f4bc5e4e1f837c90e754cfeb66e41b6f47', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Find Median from Data Stream - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, N / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('82b57073725abb279cae013909cceefff9751b865f96173a891ab0db81dd0ef2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Alien Dictionary - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('d583b4d9a8c6dce3aea93e7b5d76db5400b9ccda9f71d84d09a771e00d6f9d78', E'import java.util.*;\n\n// Sqrt(x) - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('165f16cfedc521316fd6989d1cd69c66796d575df00c3451590052550f9b73a8', E'import sys\n\n# Daily Temperatures - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    data = list(map(int, data[1:1 + sz]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('3e139b26e2787f751b9d2c6d0d063e3a1b0dcfcf288467737bd2a6e20cb53131', E'import java.util.*;\n\n// Shortest Path in Binary Matrix - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] data = new long[cnt];\n        for (int i = 0; i < cnt; i++) data[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n'),
    ('f2e2308cbded4f5deef659533d216f4b894669076ba3acc8601d26b46b7145f9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Combination Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n'';\n    return 0;\n}\n'),
    ('d5dadd234c6ad54384bafae6686943fd053538e20794cd20e8770db2b68de082', E'import sys\n\n# Three Sum - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    a = list(map(int, data[1:1 + cnt]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, cnt - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans)\n\nsolve()\n');
INSERT INTO code_blobs (code_hash, source_code) VALUES
    ('63bf2cea9a9ede5eae68b2b1717602f3a791e9e67291354c213328df0aeac5e3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Course Schedule II - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('0d10e5b21644d4fcbe9a31681bc1570a205023eeb650694ec84a341e8decdee1', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Sudoku Solver - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, len / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('d6de2eb647a64459efdacb4f32e96ffb9229c6f29b9eae443b126787ed285959', E'import java.util.*;\n\n// Permutations - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] arr = new long[len];\n        for (int i = 0; i < len; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('d50ce6d929d085068fdbfd7b8facb50059e961d66e9ef0d9265746190ec35c28', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Construct Binary Tree from Preorder and Inorder - attempt 5 */\nint main(void) {\n    int sz;\n    scanf("%d", &sz);\n    long long *v = malloc(sizeof(long long) * sz);\n    for (int i = 0; i < sz; i++) scanf("%lld", &v[i]);\n    long long best = -1000000000000LL, cur = 0;\n    for (int i = 0; i < sz; i++) {\n        cur = (v[i] > cur + v[i]) ? v[i] : cur + v[i];\n        if (cur > best) best = cur;\n    }\n    prnitf("%lld\\n", best);\n    free(v);\n    return 0;\n}\n'),
    ('2f7341bece5e02cdf440a77b01240225c0a09b3022a8b841989e76ae82e81bbd', E'import sys\n\n# Redundant Connection - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    import heapq\n    k = max(1, n // 2)\n    heap = []\n    for x in a:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('50aea6d10dfca7a1e00457c9cd65302d0cf0acd49c47ac78537aa8e95eb34d01', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Reverse Integer - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < cnt; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('ea45ccaacce709d5041e37c83974a4e537af4140481b9aa66d293cc87b756a98', E'import java.util.*;\n\n// Longest Valid Parentheses - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('c87823f5d4241baba87e881a37c2292050cdc7ac4efed54918601f2a62981461', E'import java.util.*;\n\n// Set Matrix Zeroes - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('1446af7fc7fd2a5ee26fcaf4a65dd5324e7f0f6401a8fff646564781f7b2398e', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Permutations - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> arr(cnt);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = cnt - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3cd8e64adadfb9f01644d87b96c42e3566606a05ff7ef168d683e2cf0e9ecfed', E'import sys\n\n# Construct Binary Tree from Preorder and Inorder - attempt 2\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    data = list(map(int, data[1:1 + n]))\n    best = cur = data[0]\n    for x in data[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('fe20b9af9de3385f117187b7cfe1bc994f93ac265712d744349d1a3a189db0c3', E'import sys\n\n# Valid Parentheses - attempt 1\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    a = list(map(int, data[1:1 + N]))\n    a.sort()\n    ans = 0\n    lo, hi = 0, N - 1\n    while lo < hi:\n        ans += a[hi] - a[lo]\n        lo += 1\n        hi -= 1\n    print(ans\n\nsolve()\n'),
    ('9d204a9f71b349770ec703e6e64cb551da00cba80e3814917d3a68c7fa90a139', E'import sys\n\n# Reverse Integer - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    seen = {}\n    target = int(data[1 + n])\n    for i, x in enumerate(a):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('b2637176b5d4c117f83c297546d84dace7dbc765265b7cfc012b9ecb686db4e3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Maximum Depth of Binary Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> nums(N);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < N; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('bf6ceae9eb7ed14ccec444162299ae8f079c294a9eb90311210b56b518af5ee8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Substring Without Repeating Characters - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> v(N);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < N; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('5890974bbd826fc769cc3f434d35883a8cd79f128f146bce0dfb3f2e2db5ebea', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> a(cnt);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ff59d46f83225b521bc1411f433acfc7184d5cb0aad90886f5829f0fe01798cd', E'import java.util.*;\n\n// Course Schedule - attempt 5\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('4d1da81fb4a2f54b4732ecb4df15ad7bd36c3044612850e8aa4901eebbb5c3df', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Kth Largest Element in an Array - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('ada1a67660db141b236250f9e92189c0855d0e19fc3b5ecab184d29febf18ad3', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Lowest Common Ancestor of a Binary Tree - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    sort(nums.begin(), nums.end());\n    long long ans = 0;\n    for (int i = 0, j = n - 1; i < j; ++i, --j) {\n        ans += nums[j] - nums[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('fecbbbf9998f444e1d174cea6bc866e7185bae7c68de5b78c3e9c866152872dd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Linked List Cycle - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> data(N);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('6cea7198208d910ecdb7031cec9b951783d5b64416786f34c95e8f5a7b199218', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Egg Dropping Puzzle - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int N;\n    cin >> N;\n    vector<long long> arr(N);\n    for (auto &x : arr) cin >> x;\n    vector<long long> dp(N + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= N; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[N] << ''\\n'';\n    return 0;\n}\n'),
    ('9b05378f60e5a40af00a2a4bd9915a9e70f417a5785ee33435542f357a24f7cd', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Symmetric Tree - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - v[i])) {\n            cout << seen[target - v[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[v[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('bfaf549ce388c8f16294e798b72751ab268439e7da724ed7cea86d76f64eeded', E'import java.util.*;\n\n// Longest Increasing Subsequence - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextLong();\n        Arrays.sort(a);\n        long ans = 0;\n        for (int i = 0, j = n - 1; i < j; i++, j--) {\n            ans += a[j] - a[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('1887ebac44c8632fb67fbba902fe550ae0bc1f80babd8eb2660fa5f6a8181d90', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Intervals - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cot << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d718959d80899bb770dcfc95829dc0485ca1846d53f508369456aff26f60b7c9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Product of Array Except Self - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('551c847aaffa323ca28fd09617a83875a5c086447b9b1ac437dbd24f9f07048e', E'import java.util.*;\n\n// House Robber - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n');
