    ('582754951037be95616abdc41d336c43480f4e0e4b86251982a354de04d342ec', E'import java.util.*;\n\n// Koko Eating Bananas - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(arr[i], cur + arr[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('6c5a5b11f3316b3792fb672fef6986fe5987d8cfcb9c45066221d183237f1484', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Remove Duplicates from Sorted Array - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('df0ff5f2eee118f2e1420484b70e55aa84b3c70d899aceb6d151274a0d4cb34d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Combination Sum - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('23b7b39cab0ae1c94f9844d3d812dccc188ebd6d11a54965bcfaf283323f5597', E'import java.util.*;\n\n// Triangle - attempt 3\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] v = new long[len];\n        for (int i = 0; i < len; i++) v[i] = sc.nextLong();\n        Arrays.sort(v);\n        long ans = 0;\n        for (int i = 0, j = len - 1; i < j; i++, j--) {\n            ans += v[j] - v[i];\n        }\n        System.out.println(ans);\n    }\n}\n'),
    ('9da91bf89add76565a359c4c1701823d36bf81dc3bb75f7fa76be83d97d9c0e6', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Subsets - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
