    ('aa1e4adf1abab6ff9e8b444850ec5475962189cc6d16f1abfc7c52d72b271cb4', E'import java.util.*;\n\n// Remove Duplicates from Sorted Array - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] v = new long[n];\n        for (int i = 0; i < n; i++) v[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < n; i++) {\n            cur = Math.max(v[i], cur + v[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('be1175eef2b581899e96f20bac382fe3ed09cafd758b0c79b3e1ba288679256b', E'import sys\n\n# Longest Repeating Character Replacement - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('629dac905080159369817e1521772f402357e062a9d586f5f29775d3f552993f', E'import java.util.*;\n\n// Permutations - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] arr = new long[cnt];\n        for (int i = 0; i < cnt; i++) arr[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.printn(dp[cnt]);\n    }\n}\n'),
    ('6d90bbdace187011e442580a34805bfc57a72904c3e2a00dea2f813fa8f6c5ee', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Merge Sorted Array - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < cnt; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('1fac74f6f198a5ae838ca2c583976d9c286130d73c383a106fea275c591d34f8', E'import sys\n\n# Remove Duplicates from Sorted Array - attempt 5\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    v = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(v):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('201fa8f827e4fd76437e4a6e02c3472a7129d5f7e73f6a47e438949d1b371fa2', E'import java.util.*;\n\n// Sqrt(x) - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < len; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('c51fec75827cdbcd7688063052393e13841a27754c3173e8b0608bb57ab535d4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Burst Balloons - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> v(len);\n    for (auto &x : v) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(v[i], cur + v[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('5afaa8d7144140a769f754bda28cf25bdefcbbd8d5332f455132fbd5359700f5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Counting Bits - attempt 1\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    vector<long long> dp(len + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= len; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[len] << ''\\n'';\n    return 0;\n}\n'),
    ('c83c51208917afc796cc928a23036367b87da710de7a91b56ddf217e30168581', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Letter Combinations of a Phone Number - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('bbc1b9fa1914c57cdcc92e8c9dc2a146949732e6cc94bf646bbbf6cee49770d2', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Word Break - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[n] << ''\\n''\n    return 0;\n}\n'),
    ('dadbdf43d4355a310bb83bbbd7038cc73b71e763a1cfa69bd3d608a780fe2143', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Coin Change - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> data(cnt);\n    for (auto &x : data) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, cnt / 2);\n    for (auto x : data) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('e15ea370eb6e9cd545f4701e38d20016c3ea852379f8ea2208144543b4d84d62', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Longest Valid Parentheses - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - a[i])) {\n            cout << seen[target - a[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[a[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('26cae344b237526fdd7e9c8e7ebf20817456a303f6ae76298ac43dbc905bbcc1', E'#include <stdio.h>\n#include <stdlib.h>\n\n/* Top K Frequent Elements - attempt 5 */\nint main(void) {\n    int N;\n    scanf("%d", &N);\n    long long *v = malloc(sizeof(long long) * N);\n    for (int i = 0; i < N; i++) scanf("%lld", &v[i]);\n    long long ans = 0;\n    for (int i = 0; i < N; i++) {\n        ans += v[i];\n    }\n    printf("%lld\\n", ans);\n    free(v);\n    return 0;\n}\n'),
    ('a3985485397b75daaa4a3e0826ff55a5042b9808d7133246c3f5528859aec3d5', E'import java.util.*;\n\n// Same Tree - attempt 4\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] nums = new long[cnt];\n        for (int i = 0; i < cnt; i++) nums[i] = sc.nextLong();\n        long[] dp = new long[cnt + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= cnt; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[cnt]);\n    }\n}\n');
