    ('8ec83901a3d0c4f6f6e3e502df4f7107d573e1baedb817765531489d56fb37f6', E'import sys\n\n# Longest Valid Parentheses - attempt 6\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('96ea01b322730117892af4ad16f32dcfdb6fd53c5b8c77c7f7a79aa9d2eb9de8', E'import java.util.*;\n\n// Rotate Image - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] v = new long[sz];\n        for (int i = 0; i < sz; i++) v[i] = sc.nextLong();\n        long[] dp = new long[sz + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= sz; i++) {\n            dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n        }\n        System.out.println(dp[sz]);\n    }\n}\n'),
    ('bdc27dc5b2cfbcfba9409890dc0e665aab681946fdd245aa733a21a24eef0c58', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = sz - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('8502467301eb39491bb870880f7c5da97b36f7c1c15dea0c4974fadada1d24b5', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> nums(n);\n    for (auto &x : nums) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, n / 2);\n    for (auto x : nums) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('723a47c3193304c1a452066cb2cc988e963d951c7a2cc8f73b1ef6821dd78098', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// House Robber II - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(nums[i], cur + nums[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('ba62aa4c5875aace9fbe9dbfd8cd3cb7cde9afcacf112497711b4c8eb0a33bd9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Minimum Path Sum - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> nums(len);\n    for (auto &x : nums) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < len; ++i) {\n        if (seen.count(target - nums[i])) {\n            cout << seen[target - nums[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[nums[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('0700d8bea09f169b395489e09160c4c8b249a8a9e8179d5f5e12abca760fa366', E'import sys\n\n# House Robber II - attempt 4\ndef solve():\n    data = sys.stdin.read().split()\n    N = int(data[0])\n    nums = list(map(int, data[1:1 + N]))\n    seen = {}\n    target = int(data[1 + N])\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            print(seen[target - x], i)\n            return\n        seen[x] = i\n    print(-1)\n\nsolve()\n'),
    ('f97e006dfbe67c21a216988696605b38a8b7cdc824bbb009692d5b4e4f567edd', E'import java.util.*;\n\n// Rotting Oranges - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] nums = new long[sz];\n        for (int i = 0; i < sz; i++) nums[i] = sc.nextLong();\n        long best = Long.MIN_VALUE, cur = 0;\n        for (int i = 0; i < sz; i++) {\n            cur = Math.max(nums[i], cur + nums[i]);\n            best = Math.max(best, cur);\n        }\n        System.out.println(best);\n    }\n}\n'),
    ('a0efddb65215766664eee1b85f2bd2707afba230dedc0e47ebf382db45a4d92b', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Rotting Oranges - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> a(sz);\n    for (auto &x : a) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('e572a8befb094c76009f893386d6be2c063cd3ff80170fd1ef5d58a585c6ecc8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Valid Sudoku - attempt 3\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> data(len);\n    for (auto &x : data) cin >> x;\n    long long best = LLONG_MIN, cur = 0;\n    for (int i = 0; i < len; ++i) {\n        cur = max(data[i], cur + data[i]);\n        best = max(best, cur);\n    }\n    cout << best << ''\\n'';\n    return 0;\n}\n'),
    ('577192afbc595a17ec7586320fc116b0047b81525442e0bc967333e287eb5f16', E'import java.util.*;\n\n// Number of 1 Bits - attempt 6\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        long[] nums = new long[len];\n        for (int i = 0; i < len; i++) nums[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < len; i++) {\n            if (seen.containsKey(target - nums[i])) {\n                System.out.println(seen.get(target - nums[i]) + " " + i);\n                return;\n            }\n            seen.put(nums[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('575fc4d8ee232cdac333ca662e4e06591f50c95cc42cf064783cc9cf57b894b4', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Critical Connections in a Network - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    cin >> n;\n    vector<long long> data(n);\n    for (auto &x : data) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < n; ++i) {\n        if (seen.count(target - data[i])) {\n            cout << seen[target - data[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[data[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('27a7a299dbbb246cdf688a296f71b9976b754b646aa89b2de2745d80226a24b0', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Search in Rotated Sorted Array - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int cnt;\n    cin >> cnt;\n    vector<long long> nums(cnt);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(cnt + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= cnt; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[cnt] << ''\\n'';\n    return 0;\n}\n'),
    ('569ea862bc76f40ca8f20ceeceffc05b74fe4292d6a10ec76f38db63cd827db6', E'import sys\n\n# Palindrome Partitioning II - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    cnt = int(data[0])\n    arr = list(map(int, data[1:1 + cnt]))\n    best = cur = arr[0]\n    for x in arr[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    print(best)\n\nsolve()\n'),
    ('d6e3227461388e7190f308f71f17a3f63c6b75f88d505ea6711b9c8fcfb745a8', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Palindromic Substrings - attempt 2\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> arr(len);\n    for (auto &x : arr) cin >> x;\n    sort(arr.begin(), arr.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += arr[j] - arr[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('3a35e0a304805526fdea7b374789322e3285072c7967e64567d4be8518c625d4', E'import java.util.*;\n\n// Generate Parentheses - attempt 2\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        long[] arr = new long[N];\n        for (int i = 0; i < N; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < N; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('3c3eea99d96492c13b3b8a935d049529c08d65ccff98e418c14d13c978fdc170', E'import java.util.*;\n\n// Combination Sum - attempt 1\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cnt = sc.nextInt();\n        long[] v = new long[cnt];\n        for (int i = 0; i < cnt; i++) v[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < cnt; i++) {\n            if (seen.containsKey(target - v[i])) {\n                System.out.println(seen.get(target - v[i]) + " " + i);\n                return;\n            }\n            seen.put(v[i], i);\n        }\n        System.out.println(-1);\n    }\n}\n'),
    ('ad0394e362e0b798a624fe2d3885316117ff54a7299c9caf9ece794b24d364ad', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Counting Bits - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    unordered_map<long long, int> seen;\n    long long target;\n    cin >> target;\n    for (int i = 0; i < sz; ++i) {\n        if (seen.count(target - arr[i])) {\n            cout << seen[target - arr[i]] << '' '' << i << ''\\n'';\n            return 0;\n        }\n        seen[arr[i]] = i;\n    }\n    cout << -1 << ''\\n'';\n    return 0;\n}\n'),
    ('c5e25f5444fcd8a48bd1d5698c9f688909a863a9914da588cc99aaf089cb415d', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Top K Frequent Elements - attempt 7\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int len;\n    cin >> len;\n    vector<long long> a(len);\n    for (auto &x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long ans = 0;\n    for (int i = 0, j = len - 1; i < j; ++i, --j) {\n        ans += a[j] - a[i];\n    }\n    cout << ans << ''\\n'';\n    return 0;\n}\n'),
    ('d88af0df6ad94a1e37c43d858c87a09b4ddfce20dac50f30e6692c0cb5420258', E'import sys\n\n# Distinct Subsequences - attempt 3\ndef solve():\n    data = sys.stdin.read().split()\n    sz = int(data[0])\n    v = list(map(int, data[1:1 + sz]))\n    import heapq\n    k = max(1, sz // 2)\n    heap = []\n    for x in v:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nsolve()\n'),
    ('e9a72aabfeae6c539f4fc6c3f403f67c379e5c0fdfe48eddcd1840221fe29a11', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Combination Sum - attempt 5\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> v(sz);\n    for (auto &x : v) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : v) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n'),
    ('ccb3da32b1269c099bb924e97463d6be1d567f284453bb3684e181896983262a', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// Gray Code - attempt 6\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> nums(sz);\n    for (auto &x : nums) cin >> x;\n    vector<long long> dp(sz + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= sz; ++i) {\n        dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);\n    }\n    cout << dp[sz] << ''\\n'';\n    return 0;\n}\n'),
    ('fcc6a9456b90680fe62f4df99cd67bd52d9412441ab7662f774420a0d478e85b', E'import java.util.*;\n\n// Maximum Length of Repeated Subarray - attempt 7\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int sz = sc.nextInt();\n        long[] arr = new long[sz];\n        for (int i = 0; i < sz; i++) arr[i] = sc.nextLong();\n        Map<Long, Integer> seen = new HashMap<>();\n        long target = sc.nextLong();\n        for (int i = 0; i < sz; i++) {\n            if (seen.containsKey(target - arr[i])) {\n                System.out.println(seen.get(target - arr[i]) + " " + i);\n                return;\n            }\n            seen.put(arr[i], i);\n        }\n        System.out.printn(-1);\n    }\n}\n'),
    ('221483c87d7f1eef98f9a27d8a0874ae5aa1a6ce6e0b1648f6c6f98ea2c7ead9', E'#include <bits/stdc++.h>\nusing namespace std;\n\n// N-Queens - attempt 4\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int sz;\n    cin >> sz;\n    vector<long long> arr(sz);\n    for (auto &x : arr) cin >> x;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    int k = max(1, sz / 2);\n    for (auto x : arr) {\n        pq.push(x);\n        if ((int)pq.size() > k) pq.pop();\n    }\n    cout << pq.top() << ''\\n'';\n    return 0;\n}\n');
