INSERT INTO posts (post_id, user_id, problem_id, title, body_text, code_snippet, programming_language_tag, time_complexity_analysis, edge_case_explanation, creation_timestamp, post_status) VALUES
    (1, 8, 10, 'Intuition and dry run for Container With Most Water', 'After reading the editorial I rewrote my solution in a cleaner way. The main trick is to choose the right data structure (Two Pointers) up front.', E'int solve(vector<int>& a) {\n    // Two Pointers\n    return a.size();\n}', 'C++', 'O(n)', 'Duplicates and negative numbers need separate handling.', '2023-08-27 16:26:01', 'Removed'),
    (2, 252, 3, 'Why my first attempt failed on Contains Duplicate and how I fixed it', 'Most solutions fail because they ignore the boundary cases. Below is a version that handles all of them and still runs within the limits.', E'int solve(vector<int>& a) {\n    // Sorting\n    return a.size();\n}', 'C++', 'O(n)', 'Check the case where the answer does not exist and print -1.', '2023-09-08 11:58:17', 'Hidden'),
    (3, 91, 11, 'Python solution and a faster alternative', 'After reading the editorial I rewrote my solution in a cleaner way. The main trick is to choose the right data structure (Hash Table) up front.', E'int solve(vector<int>& a) {\n    // Hash Table\n    return a.size();\n}', 'C++', 'O(n)', 'Watch for integer overflow when sums exceed 2^31 - 1.', '2024-01-18 11:47:44', 'Approved'),
    (4, 288, 7, 'Step-by-step approach for Find Minimum in Rotated Sorted Array', 'I started with the brute force approach and then removed the repeated work using Binary Search. The key observation is that each element needs to be processed only once.', E'def solve(a):\n    # Binary Search\n    return sorted(a)', 'Python', 'O(log n)', 'Watch for integer overflow when sums exceed 2^31 - 1.', '2024-02-11 08:44:01', 'Published'),
    (5, 39, 27, 'Python solution and a faster alternative', 'I started with the brute force approach and then removed the repeated work using Prefix Sum. The key observation is that each element needs to be processed only once.', E'int solve(vector<int>& a) {\n    // Prefix Sum\n    return a.size();\n}', 'C++', 'O(n log n)', 'Duplicates and negative numbers need separate handling.', '2024-05-17 06:57:30', 'Published'),
    (6, 216, 9, 'Interview tip: how to explain Three Sum', 'I started with the brute force approach and then removed the repeated work using Sorting. The key observation is that each element needs to be processed only once.', E'int solve(vector<int>& a) {\n    // Sorting\n    return a.size();\n}', 'C++', 'O(n)', 'Check the case where the answer does not exist and print -1.', '2024-06-22 07:24:49', 'Published'),
